export default "\\\" in response.json()[\\\"detail\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_ingestion_run_endpoints.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"238ad53610f95f97d14aa55bbeaf44aa7ea7e9bbfff2f640aec1a5cafffe2eae\",\"content\":\"\\\"\\\"\\\"Integration tests for the KB ingestion-run visibility endpoints.\\n\\nThese drive ``GET /{kb}/runs`` and ``GET /{kb}/runs/{run_id}``\\nend-to-end against the real FastAPI app and test DB so we catch\\nrouting, auth scoping, pagination, and SQL-level behavior in one\\ntest pass.\\n\\nStorage note: as of the unification onto the canonical ``job`` table,\\ningestion-run data lives on ``Job.job_metadata``. The URL ``run_id``\\npath parameter is now the ``Job.job_id``; the response shape is\\nunchanged so the frontend is unaffected.\\n\\nAsset-id semantics: ``Job.asset_id`` carries\\n``KnowledgeBaseRecord.id`` (the indexed DB pk) so the read path\\n(``list_runs_for_kb``) hits a btree-index lookup instead of a\\nJSON-extract on ``Job.job_metadata.kb_name``. Tests therefore seed a\\nmatching ``KnowledgeBaseRecord`` alongside each ``Job`` so the new\\nindexed read path is exercised.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport uuid\\nfrom datetime import datetime, timedelta, timezone\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.api.utils import knowledge_base_service\\nfrom langflow.services.database.models.jobs.model import Job, JobStatus, JobType\\nfrom langflow.services.deps import session_scope\\nfrom lfx.base.knowledge_bases.ingestion_sources.base import IngestionRunStatus\\n\\nif TYPE_CHECKING:\\n    from httpx import AsyncClient\\n\\n\\n# Bump ``created_timestamp`` per insertion so the newest-first ordering\\n# test has a stable sort key. Without this, two rows inserted in the\\n# same wall-clock millisecond can flip order on fast hardware.\\n_INSERT_OFFSET_SECONDS = 0\\n\\n\\ndef _next_created_timestamp() -> datetime:\\n    global _INSERT_OFFSET_SECONDS  # noqa: PLW0603\\n    _INSERT_OFFSET_SECONDS += 1\\n    return datetime.now(timezone.utc) + timedelta(seconds=_INSERT_OFFSET_SECONDS)\\n\\n\\nasync def _ensure_kb_record(*, user_id: uuid.UUID, kb_name: str) -> uuid.UUID:\\n    \\\"\\\"\\\"Create a minimal ``KnowledgeBaseRecord`` for ``kb_name`` if absent.\\n\\n    Returns the record's ``id`` so callers can wire it into the\\n    ``Job.asset_id`` field \u2014 the indexed-read path filters on it.\\n    \\\"\\\"\\\"\\n    existing = await knowledge_base_service.get_by_user_and_name(user_id, kb_name)\\n    if existing is not None:\\n        return existing.id\\n    record = await knowledge_base_service.create_record(\\n        user_id=user_id,\\n        name=kb_name,\\n        model_selection={\\n            \\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n            \\\"provider\\\": \\\"HuggingFace\\\",\\n        },\\n    )\\n    return record.id\\n\\n\\nasync def _insert_run(\\n    *,\\n    user_id: uuid.UUID,\\n    kb_name: str,\\n    kb_id: uuid.UUID | None = None,\\n    status: IngestionRunStatus = IngestionRunStatus.SUCCEEDED,\\n    source_type: str = \\\"file_upload\\\",\\n    items: list[dict] | None = None,\\n    succeeded: int = 1,\\n    failed: int = 0,\\n    source_config: dict | None = None,\\n) -> uuid.UUID:\\n    \\\"\\\"\\\"Seed a ``Job`` row carrying KB ingestion-run data on its metadata.\\n\\n    Auto-provisions a matching ``KnowledgeBaseRecord`` (when ``kb_id``\\n    is not supplied) so the new asset_id-indexed read path is\\n    exercised. Returns the ``job_id`` so callers can use it as the\\n    URL ``run_id`` \u2014 the two are equal post-unification.\\n    \\\"\\\"\\\"\\n    if kb_id is None:\\n        kb_id = await _ensure_kb_record(user_id=user_id, kb_name=kb_name)\\n\\n    run_id = uuid.uuid4()\\n    items_payload = items or [\\n        {\\n            \\\"item_id\\\": \\\"0:a.txt\\\",\\n            \\\"display_name\\\": \\\"a.txt\\\",\\n            \\\"status\\\": \\\"succeeded\\\",\\n            \\\"chunks_created\\\": 3,\\n            \\\"error_message\\\": None,\\n        }\\n    ]\\n    started_at = _next_created_timestamp()\\n    async with session_scope() as session:\\n        job = Job(\\n            job_id=run_id,\\n            flow_id=run_id,\\n            status=JobStatus.COMPLETED,\\n            type=JobType.INGESTION,\\n            user_id=user_id,\\n            asset_id=kb_id,\\n            asset_type=\\\"knowledge_base\\\",\\n            created_timestamp=started_at,\\n            finished_timestamp=started_at,\\n            job_metadata={\\n                \\\"kind\\\": \\\"kb_ingestion\\\",\\n                \\\"kb_name\\\": kb_name,\\n                \\\"kb_id\\\": str(kb_id) if kb_id is not None else None,\\n                \\\"source_type\\\": source_type,\\n                \\\"source_config\\\": {\\\"source_name\\\": \\\"demo\\\"} if source_config is None else source_config,\\n                \\\"status\\\": status.value,\\n                \\\"error_message\\\": None,\\n                \\\"total_items\\\": succeeded + failed,\\n                \\\"succeeded\\\": succeeded,\\n                \\\"failed\\\": failed,\\n                \\\"skipped\\\": 0,\\n                \\\"total_bytes\\\": 1024,\\n                \\\"chunks_created\\\": succeeded * 3,\\n                \\\"items\\\": items_payload,\\n                \\\"ingestion_run_id\\\": str(run_id),\\n            },\\n        )\\n        session.add(job)\\n        await session.commit()\\n    return run_id\\n\\n\\nclass TestListIngestionRuns:\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_returns_runs_for_kb_newest_first(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"visibility_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        first_id = await _insert_run(user_id=active_user.id, kb_name=\\\"visibility_kb\\\", succeeded=2)\\n        second_id = await _insert_run(user_id=active_user.id, kb_name=\\\"visibility_kb\\\", succeeded=5)\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/visibility_kb/runs\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        payload = response.json()\\n        assert payload[\\\"total\\\"] >= 2\\n        ids = [r[\\\"id\\\"] for r in payload[\\\"runs\\\"]]\\n        # Newer first\\n        assert ids.index(str(second_id)) < ids.index(str(first_id))\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_excludes_other_users_runs(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"only_mine\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        mine = await _insert_run(user_id=active_user.id, kb_name=\\\"only_mine\\\")\\n        other_user_id = uuid.uuid4()\\n        # Pass an explicit ``kb_id`` for the foreign-user run so\\n        # ``_insert_run`` skips the auto-create-kb-record step (the\\n        # foreign user has no User row, so the FK would reject it).\\n        # Using a fresh UUID here also models reality: even if a\\n        # foreign user did own a same-named KB, its record id would\\n        # be distinct from active_user's, so the indexed asset_id\\n        # lookup wouldn't match either way.\\n        foreign_run_id = await _insert_run(\\n            user_id=other_user_id,\\n            kb_name=\\\"only_mine\\\",\\n            kb_id=uuid.uuid4(),\\n        )\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/only_mine/runs\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        payload = response.json()\\n        ids = {r[\\\"id\\\"] for r in payload[\\\"runs\\\"]}\\n        assert str(mine) in ids\\n        # Must not leak the other user's run even though kb_name matches\\n        assert str(foreign_run_id) not in ids\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_exposes_source_name_from_source_config(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"named_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        await _insert_run(\\n            user_id=active_user.id,\\n            kb_name=\\\"named_kb\\\",\\n            source_config={\\\"source_name\\\": \\\"Test6\\\"},\\n        )\\n        await _insert_run(\\n            user_id=active_user.id,\\n            kb_name=\\\"named_kb\\\",\\n            source_config={},\\n        )\\n        await _insert_run(\\n            user_id=active_user.id,\\n            kb_name=\\\"named_kb\\\",\\n            source_config={\\\"source_name\\\": \\\"   \\\"},\\n        )\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/named_kb/runs\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        names = [r[\\\"source_name\\\"] for r in response.json()[\\\"runs\\\"]]\\n        # Order is newest-first: whitespace, missing, then \\\"Test6\\\".\\n        assert \\\"Test6\\\" in names\\n        # Whitespace-only collapses to ``None``.\\n        assert names.count(None) == 2\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_pagination(self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"paginated_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        for _ in range(3):\\n            await _insert_run(user_id=active_user.id, kb_name=\\\"paginated_kb\\\")\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/paginated_kb/runs?page=1&limit=2\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        payload = response.json()\\n        assert payload[\\\"limit\\\"] == 2\\n        assert payload[\\\"page\\\"] == 1\\n        assert len(payload[\\\"runs\\\"]) <= 2\\n        assert payload[\\\"total\\\"] >= 3\\n\\n\\nclass TestGetIngestionRun:\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_returns_full_detail_with_items(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"detail_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        items = [\\n            {\\n                \\\"item_id\\\": \\\"0:ok.txt\\\",\\n                \\\"display_name\\\": \\\"ok.txt\\\",\\n                \\\"status\\\": \\\"succeeded\\\",\\n                \\\"chunks_created\\\": 4,\\n                \\\"error_message\\\": None,\\n            },\\n            {\\n                \\\"item_id\\\": \\\"1:bad.txt\\\",\\n                \\\"display_name\\\": \\\"bad.txt\\\",\\n                \\\"status\\\": \\\"failed\\\",\\n                \\\"chunks_created\\\": 0,\\n                \\\"error_message\\\": \\\"parse failure\\\",\\n            },\\n        ]\\n        run_id = await _insert_run(\\n            user_id=active_user.id,\\n            kb_name=\\\"detail_kb\\\",\\n            items=items,\\n            succeeded=1,\\n            failed=1,\\n        )\\n\\n        response = await client.get(\\n            f\\\"api/v1/knowledge_bases/detail_kb/runs/{run_id}\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        payload = response.json()\\n        assert payload[\\\"id\\\"] == str(run_id)\\n        assert payload[\\\"succeeded\\\"] == 1\\n        assert payload[\\\"failed\\\"] == 1\\n        assert len(payload[\\\"items\\\"]) == 2\\n        failed_item = next(i for i in payload[\\\"items\\\"] if i[\\\"status\\\"] == \\\"failed\\\")\\n        assert failed_item[\\\"error_message\\\"] == \\\"parse failure\\\"\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_other_users_run_returns_404(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"secret_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n\\n        other_user_id = uuid.uuid4()\\n        # Foreign user has no User row, so skip kb_record auto-create\\n        # by passing an explicit kb_id (see notes in\\n        # ``test_excludes_other_users_runs``).\\n        foreign_run_id = await _insert_run(\\n            user_id=other_user_id,\\n            kb_name=\\\"secret_kb\\\",\\n            kb_id=uuid.uuid4(),\\n        )\\n\\n        response = await client.get(\\n            f\\\"api/v1/knowledge_bases/secret_kb/runs/{foreign_run_id}\\\",\\n            headers=logged_in_headers,\\n        )\\n        # Must be indistinguishable from \\\"never existed\\\" so the ID space\\n        # isn't a covert enumeration channel.\\n        assert response.status_code == 404\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_run_from_different_kb_returns_404(\\n        self, mock_root, client: AsyncClient, logged_in_headers, active_user, tmp_path\\n    ):\\n        mock_root.return_value = tmp_path\\n        (tmp_path / active_user.username / \\\"kb_a\\\").mkdir(parents=True)\\n        (tmp_path / active_user.username / \\\"kb_b\\\").mkdir(parents=True)\\n\\n        run_id = await _insert_run(user_id=active_user.id, kb_name=\\\"kb_a\\\")\\n\\n        response = await client.get(\\n            f\\\"api/v1/knowledge_bases/kb_b/runs/{run_id}\\\",\\n            headers=logged_in_headers,\\n        )\\n        # Correct owner, wrong KB \u2192 still 404. Prevents a user from\\n        # querying their own run history under someone else's kb_name.\\n        assert response.status_code == 404\\n\\n\\nclass TestChunksFilters:\\n    \\\"\\\"\\\"Sanity-check the metadata filters on the chunks endpoint.\\n\\n    The endpoint now streams chunks through the backend abstraction\\n    (``backend.iter_documents``) and filters in Python so the behavior\\n    is identical across Chroma / Mongo / Astra / Postgres. These tests\\n    feed synthetic batches through a mocked backend and assert the\\n    correct chunks surface for each filter.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _fake_backend(entries):\\n        \\\"\\\"\\\"Build a mock backend whose ``iter_documents`` yields ``entries``.\\n\\n        ``entries`` is a list of ``(content, metadata)`` tuples. Each\\n        entry is wrapped in an ``IngestedDocument`` and yielded as one\\n        batch so the endpoint's in-Python filter has data to pass through.\\n        \\\"\\\"\\\"\\n        from unittest.mock import AsyncMock, MagicMock\\n\\n        from lfx.base.knowledge_bases.backends.base import IngestedDocument\\n\\n        async def _iter_documents(*, batch_size: int = 1000, include_embeddings: bool = False):  # noqa: ARG001\\n            yield [IngestedDocument(content=c, metadata=m) for c, m in entries]\\n\\n        backend = MagicMock()\\n        backend.iter_documents = _iter_documents\\n        backend.teardown = AsyncMock()\\n        return backend\\n\\n    @pytest.mark.parametrize(\\n        (\\\"query\\\", \\\"expected_source_types\\\"),\\n        [\\n            (\\\"?source_type=folder\\\", {\\\"folder\\\"}),\\n            (\\\"?file_name=a.pdf\\\", {\\\"file_upload\\\"}),\\n            (\\\"?job_id=deadbeef\\\", {\\\"file_upload\\\"}),\\n        ],\\n    )\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.release_chroma_resources\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_single_metadata_filter_narrows_results(\\n        self,\\n        mock_root,\\n        mock_create_backend,\\n        mock_release,  # noqa: ARG002\\n        query,\\n        expected_source_types,\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"filter_kb\\\"\\n        kb_dir.mkdir(parents=True)\\n        # A dummy chroma.sqlite3 so the local-Chroma \\\"has_data\\\" guard passes.\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_bytes(b\\\"\\\")\\n        await _ensure_kb_record(user_id=active_user.id, kb_name=\\\"filter_kb\\\")\\n\\n        mock_create_backend.return_value = self._fake_backend(\\n            [\\n                (\\\"hello\\\", {\\\"source_type\\\": \\\"folder\\\", \\\"file_name\\\": \\\"b.md\\\", \\\"job_id\\\": \\\"cafe\\\"}),\\n                (\\\"world\\\", {\\\"source_type\\\": \\\"file_upload\\\", \\\"file_name\\\": \\\"a.pdf\\\", \\\"job_id\\\": \\\"deadbeef\\\"}),\\n            ]\\n        )\\n\\n        response = await client.get(\\n            f\\\"api/v1/knowledge_bases/filter_kb/chunks{query}\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        body = response.json()\\n        assert {chunk[\\\"metadata\\\"][\\\"source_type\\\"] for chunk in body[\\\"chunks\\\"]} == expected_source_types\\n\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.release_chroma_resources\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.create_backend\\\")\\n    @patch(\\\"langflow.api.v1.knowledge_bases.KBStorageHelper.get_root_path\\\")\\n    async def test_multiple_filters_combine_with_and(\\n        self,\\n        mock_root,\\n        mock_create_backend,\\n        mock_release,  # noqa: ARG002\\n        client: AsyncClient,\\n        logged_in_headers,\\n        active_user,\\n        tmp_path,\\n    ):\\n        mock_root.return_value = tmp_path\\n        kb_dir = tmp_path / active_user.username / \\\"filter_multi\\\"\\n        kb_dir.mkdir(parents=True)\\n        # A dummy chroma.sqlite3 so the local-Chroma \\\"has_data\\\" guard passes.\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_bytes(b\\\"\\\")\\n        await _ensure_kb_record(user_id=active_user.id, kb_name=\\\"filter_multi\\\")\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_bytes(b\\\"\\\")\\n\\n        mock_create_backend.return_value = self._fake_backend(\\n            [\\n                (\\\"match\\\", {\\\"source_type\\\": \\\"folder\\\", \\\"file_name\\\": \\\"a.pdf\\\"}),\\n                (\\\"wrong-source\\\", {\\\"source_type\\\": \\\"file_upload\\\", \\\"file_name\\\": \\\"a.pdf\\\"}),\\n                (\\\"wrong-file\\\", {\\\"source_type\\\": \\\"folder\\\", \\\"file_name\\\": \\\"b.md\\\"}),\\n            ]\\n        )\\n\\n        response = await client.get(\\n            \\\"api/v1/knowledge_bases/filter_multi/chunks?source_type=folder&file_name=a.pdf\\\",\\n            headers=logged_in_headers,\\n        )\\n        assert response.status_code == 200\\n        body = response.json()\\n        # Only the row matching BOTH filters should survive.\\n        assert [chunk[\\\"content\\\"] for chunk in body[\\\"chunks\\\"]] == [\\\"match\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_knowledge_base_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5398703f1eb8b212a99519ffa3e98fac9e7c08cf31c01dce980ef37291ae7904\",\"content\":\"\\\"\\\"\\\"Unit tests for ``knowledge_base_service``.\\n\\nExercises the real DB session (via the test harness) so SQL-level\\nconcerns (unique constraint, JSON serialization, update behavior)\\nsurface here rather than leaking into API-level tests.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom langflow.api.utils import knowledge_base_service\\nfrom langflow.services.database.models.knowledge_base import KnowledgeBaseStatus\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\nclass TestCreateAndRead:\\n    async def test_create_and_get_by_user_and_name(self, active_user):\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_alpha\\\",\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            chunk_size=512,\\n            chunk_overlap=64,\\n            separator=\\\"\\\\n\\\",\\n            column_config=[{\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": True, \\\"identifier\\\": True}],\\n        )\\n        assert record.id is not None\\n        assert record.status == KnowledgeBaseStatus.READY.value\\n\\n        fetched = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"phase_15_kb_alpha\\\")\\n        assert fetched is not None\\n        assert fetched.id == record.id\\n        assert fetched.model_selection == {\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"}\\n        assert fetched.chunk_size == 512\\n\\n    async def test_get_by_user_and_name_returns_none_when_missing(self, active_user):\\n        result = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"does_not_exist\\\")\\n        assert result is None\\n\\n    async def test_list_by_user_orders_newest_first(self, active_user):\\n        first = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_list_a\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        second = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_list_b\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        rows = await knowledge_base_service.list_by_user(active_user.id)\\n        ids = [r.id for r in rows]\\n        # Both ours must be present and the newer one must precede the older one.\\n        assert first.id in ids\\n        assert second.id in ids\\n        assert ids.index(second.id) < ids.index(first.id)\\n\\n\\nclass TestUpdates:\\n    async def test_update_stats_refreshes_cached_counters(self, active_user):\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_stats\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        await knowledge_base_service.update_stats(\\n            record.id,\\n            chunks=10,\\n            words=200,\\n            characters=1000,\\n            size_bytes=4096,\\n            source_types=[\\\"pdf\\\", \\\"md\\\"],\\n            chunk_size=512,\\n            chunk_overlap=64,\\n            separator=\\\"\\\\n\\\",\\n        )\\n        fetched = await knowledge_base_service.get_by_id(record.id)\\n        assert fetched is not None\\n        assert fetched.chunks == 10\\n        assert fetched.words == 200\\n        assert fetched.characters == 1000\\n        assert fetched.size_bytes == 4096\\n        assert fetched.source_types == [\\\"md\\\", \\\"pdf\\\"]  # dedup + sorted\\n        assert fetched.chunk_size == 512\\n        assert fetched.chunk_overlap == 64\\n        assert fetched.separator == \\\"\\\\n\\\"\\n\\n    async def test_update_stats_can_clear_separator(self, active_user):\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_separator_clear\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            separator=\\\"\\\\n\\\",\\n        )\\n\\n        await knowledge_base_service.update_stats(record.id, separator=None)\\n\\n        fetched = await knowledge_base_service.get_by_id(record.id)\\n        assert fetched is not None\\n        assert fetched.separator is None\\n\\n    async def test_update_stats_missing_row_is_silent(self, active_user):  # noqa: ARG002\\n        import uuid\\n\\n        # Should not raise \u2014 logged and returned.\\n        await knowledge_base_service.update_stats(uuid.uuid4(), chunks=1)\\n\\n    async def test_update_status(self, active_user):\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_status\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        await knowledge_base_service.update_status(\\n            record.id, status=KnowledgeBaseStatus.FAILED, failure_reason=\\\"test error\\\"\\n        )\\n        fetched = await knowledge_base_service.get_by_id(record.id)\\n        assert fetched is not None\\n        assert fetched.status == KnowledgeBaseStatus.FAILED.value\\n        assert fetched.failure_reason == \\\"test error\\\"\\n\\n\\nclass TestDelete:\\n    async def test_delete_by_user_and_name_removes_row(self, active_user):\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_delete\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"phase_15_kb_delete\\\") is not None\\n\\n        await knowledge_base_service.delete_by_user_and_name(active_user.id, \\\"phase_15_kb_delete\\\")\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"phase_15_kb_delete\\\") is None\\n\\n    async def test_delete_missing_is_noop(self, active_user):\\n        # Should not raise \u2014 the row may have never existed.\\n        await knowledge_base_service.delete_by_user_and_name(active_user.id, \\\"never_created\\\")\\n\\n\\nclass TestNormalization:\\n    def test_record_to_metadata_dict_matches_json_shape(self):\\n        import uuid\\n        from datetime import datetime, timezone\\n\\n        from langflow.services.database.models.knowledge_base import KnowledgeBaseRecord\\n\\n        record = KnowledgeBaseRecord(\\n            id=uuid.uuid4(),\\n            name=\\\"kb\\\",\\n            user_id=uuid.uuid4(),\\n            # Provider / model now derived from ``model_selection`` \u2014\\n            # the flat columns no longer exist on the table.\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            chunk_size=1000,\\n            chunk_overlap=200,\\n            backend_type=\\\"opensearch\\\",\\n            backend_config={\\\"index_name\\\": \\\"kb_index\\\"},\\n            chunks=4,\\n            words=200,\\n            characters=1000,\\n            size_bytes=500,\\n            source_types=[\\\"pdf\\\"],\\n            created_at=datetime.now(timezone.utc),\\n            updated_at=datetime.now(timezone.utc),\\n        )\\n        snapshot = knowledge_base_service.record_to_metadata_dict(record)\\n        # Flat fields are derived views over ``model_selection``.\\n        assert snapshot[\\\"embedding_provider\\\"] == \\\"OpenAI\\\"\\n        assert snapshot[\\\"embedding_model\\\"] == \\\"text-embedding-3-small\\\"\\n        # Matches legacy JSON keys so downstream readers stay intact.\\n        for key in [\\n            \\\"id\\\",\\n            \\\"embedding_provider\\\",\\n            \\\"embedding_model\\\",\\n            \\\"model_selection\\\",\\n            \\\"chunk_size\\\",\\n            \\\"chunk_overlap\\\",\\n            \\\"backend_type\\\",\\n            \\\"backend_config\\\",\\n            \\\"chunks\\\",\\n            \\\"words\\\",\\n            \\\"characters\\\",\\n            \\\"size\\\",\\n            \\\"source_types\\\",\\n            \\\"status\\\",\\n            \\\"avg_chunk_size\\\",\\n        ]:\\n            assert key in snapshot\\n        assert snapshot[\\\"size\\\"] == 500  # note the legacy JSON uses \\\"size\\\" not \\\"size_bytes\\\"\\n        assert snapshot[\\\"avg_chunk_size\\\"] == round(1000 / 4, 1)\\n        assert snapshot[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert snapshot[\\\"backend_config\\\"] == {\\\"index_name\\\": \\\"kb_index\\\"}\\n\\n    def test_record_to_metadata_dict_maps_zero_chunk_ready_kb_to_empty_status(self):\\n        import uuid\\n\\n        from langflow.services.database.models.knowledge_base import KnowledgeBaseRecord\\n\\n        record = KnowledgeBaseRecord(\\n            id=uuid.uuid4(),\\n            name=\\\"kb_empty\\\",\\n            user_id=uuid.uuid4(),\\n            model_selection={\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            chunks=0,\\n            words=0,\\n            characters=0,\\n            size_bytes=0,\\n            status=KnowledgeBaseStatus.READY.value,\\n        )\\n\\n        snapshot = knowledge_base_service.record_to_metadata_dict(record)\\n        assert snapshot[\\\"status\\\"] == \\\"empty\\\"\\n\\n\\nclass TestBackfillFromDisk:\\n    async def test_backfill_inserts_missing_rows(self, active_user, tmp_path: Path):\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n\\n        # Two on-disk KBs, no DB rows yet.\\n        for name, provider in [(\\\"diskonly_a\\\", \\\"OpenAI\\\"), (\\\"diskonly_b\\\", \\\"HuggingFace\\\")]:\\n            kb_dir = kb_root / name\\n            kb_dir.mkdir()\\n            (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n                json.dumps(\\n                    {\\n                        \\\"embedding_provider\\\": provider,\\n                        \\\"embedding_model\\\": \\\"m\\\",\\n                        \\\"chunk_size\\\": 512,\\n                        \\\"chunk_overlap\\\": 50,\\n                        \\\"chunks\\\": 161,\\n                        \\\"words\\\": 3200,\\n                        \\\"characters\\\": 18000,\\n                        \\\"size\\\": 4096,\\n                        \\\"source_types\\\": [\\\"txt\\\", \\\"pdf\\\"],\\n                    }\\n                )\\n            )\\n\\n        inserted = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        assert inserted == 2\\n\\n        a = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"diskonly_a\\\")\\n        assert a is not None\\n        # Provider lives on ``model_selection`` now (synthesized by the\\n        # backfill from the legacy flat fields on disk).\\n        assert a.model_selection.get(\\\"provider\\\") == \\\"OpenAI\\\"\\n        assert a.chunk_size == 512\\n        assert a.chunks == 161\\n        assert a.words == 3200\\n        assert a.characters == 18000\\n        assert a.size_bytes > 0\\n        assert a.source_types == [\\\"pdf\\\", \\\"txt\\\"]\\n\\n    async def test_backfill_adopts_recorded_stats_without_opening_the_vector_store(self, active_user, tmp_path: Path):\\n        \\\"\\\"\\\"Adoption reads the sidecar as-written; it never boots a Chroma client to recount.\\n\\n        This is a legacy-recovery path, so it stays cheap and non-mutating: opening a\\n        persistent Chroma client per directory would be slow and would take a SQLite\\n        lock on data the operator is trying to rescue. The counters are refreshed by\\n        the next ingestion anyway.\\n        \\\"\\\"\\\"\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n        kb_dir = kb_root / \\\"legacy_with_chunks\\\"\\n        kb_dir.mkdir()\\n        (kb_dir / \\\"chroma.sqlite3\\\").write_text(\\\"legacy vector data\\\")\\n        (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps(\\n                {\\n                    \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                    \\\"embedding_model\\\": \\\"m\\\",\\n                    \\\"chunk_size\\\": 512,\\n                    \\\"chunk_overlap\\\": 50,\\n                    \\\"chunks\\\": 161,\\n                    \\\"words\\\": 3200,\\n                    \\\"characters\\\": 18000,\\n                    \\\"size\\\": 4096,\\n                    \\\"source_types\\\": [\\\"file_upload\\\"],\\n                }\\n            )\\n        )\\n\\n        inserted = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        assert inserted == 1\\n\\n        record = await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"legacy_with_chunks\\\")\\n        assert record is not None\\n        assert record.chunks == 161\\n        assert record.words == 3200\\n        assert record.characters == 18000\\n        assert record.size_bytes == 4096\\n        assert record.source_types == [\\\"file_upload\\\"]\\n        assert knowledge_base_service.record_to_metadata_dict(record)[\\\"status\\\"] == KnowledgeBaseStatus.READY.value\\n\\n    async def test_backfill_dry_run_reports_without_writing(self, active_user, tmp_path: Path):\\n        \\\"\\\"\\\"``--dry-run`` must count adoptable KBs and leave the database untouched.\\\"\\\"\\\"\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n        kb_dir = kb_root / \\\"diskonly_dryrun\\\"\\n        kb_dir.mkdir()\\n        (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"m\\\"})\\n        )\\n\\n        would_insert = await knowledge_base_service.backfill_from_disk(\\n            user_id=active_user.id, kb_user_root=kb_root, dry_run=True\\n        )\\n        assert would_insert == 1\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"diskonly_dryrun\\\") is None\\n\\n        # And the same call without dry_run actually adopts it.\\n        assert await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root) == 1\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"diskonly_dryrun\\\") is not None\\n\\n    async def test_backfill_is_idempotent(self, active_user, tmp_path: Path):\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n        kb_dir = kb_root / \\\"diskonly_idem\\\"\\n        kb_dir.mkdir()\\n        (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"m\\\"})\\n        )\\n\\n        first = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        second = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        assert first == 1\\n        assert second == 0  # already backfilled \u2014 no duplicates created\\n\\n    async def test_backfill_skips_missing_metadata(self, active_user, tmp_path: Path):\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n        kb_dir = kb_root / \\\"unreadable\\\"\\n        kb_dir.mkdir()\\n        # No metadata file \u2192 skip, don't crash.\\n\\n        inserted = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        assert inserted == 0\\n\\n    async def test_backfill_missing_root_returns_zero(self, active_user, tmp_path: Path):\\n        inserted = await knowledge_base_service.backfill_from_disk(\\n            user_id=active_user.id, kb_user_root=tmp_path / \\\"does_not_exist\\\"\\n        )\\n        assert inserted == 0\\n\\n    async def test_backfill_skips_directories_with_deletion_sentinel(self, active_user, tmp_path: Path):\\n        \\\"\\\"\\\"Backfill must skip directories carrying the ``.kb_deleted`` sentinel.\\n\\n        A KB whose row was deleted but whose bytes remain on disk (locked\\n        Chroma SQLite, etc.) carries a ``.kb_deleted`` sentinel.  The backfill\\n        must NOT re-insert such directories or the deleted KB would\\n        reappear on every server restart.\\n        \\\"\\\"\\\"\\n        from langflow.api.utils.kb_helpers import KB_DELETED_SENTINEL\\n\\n        kb_root = tmp_path / active_user.username\\n        kb_root.mkdir()\\n        kb_dir = kb_root / \\\"tombstoned\\\"\\n        kb_dir.mkdir()\\n        (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"embedding_provider\\\": \\\"OpenAI\\\", \\\"embedding_model\\\": \\\"m\\\"})\\n        )\\n        (kb_dir / KB_DELETED_SENTINEL).touch()\\n\\n        inserted = await knowledge_base_service.backfill_from_disk(user_id=active_user.id, kb_user_root=kb_root)\\n        assert inserted == 0\\n        assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"tombstoned\\\") is None\\n\\n\\nclass TestBackfillAllUsersFromDisk:\\n    async def test_backfill_all_users_scans_each_user_root(self, active_user, tmp_path: Path):\\n        from langflow.services.database.models.user.model import User\\n        from langflow.services.deps import get_auth_service, session_scope\\n\\n        other_username = \\\"phase15_other_user\\\"\\n        other_user_id = None\\n\\n        async with session_scope() as session:\\n            other_user = User(\\n                username=other_username,\\n                password=get_auth_service().get_password_hash(\\\"testpassword\\\"),\\n                is_active=True,\\n                is_superuser=False,\\n            )\\n            session.add(other_user)\\n            await session.flush()\\n            await session.refresh(other_user)\\n            other_user_id = other_user.id\\n        assert other_user_id is not None\\n\\n        for username, kb_name in [(active_user.username, \\\"startup_kb_a\\\"), (other_username, \\\"startup_kb_b\\\")]:\\n            kb_dir = tmp_path / username / kb_name\\n            kb_dir.mkdir(parents=True)\\n            (kb_dir / \\\"embedding_metadata.json\\\").write_text(\\n                json.dumps(\\n                    {\\n                        \\\"embedding_provider\\\": \\\"OpenAI\\\",\\n                        \\\"embedding_model\\\": \\\"text-embedding-3-small\\\",\\n                    }\\n                )\\n            )\\n\\n        try:\\n            inserted = await knowledge_base_service.backfill_all_users_from_disk(kb_root=tmp_path)\\n            assert inserted == 2\\n            assert await knowledge_base_service.get_by_user_and_name(active_user.id, \\\"startup_kb_a\\\") is not None\\n            assert await knowledge_base_service.get_by_user_and_name(other_user_id, \\\"startup_kb_b\\\") is not None\\n        finally:\\n            async with session_scope() as session:\\n                other_user = await session.get(User, other_user_id)\\n                if other_user is not None:\\n                    await session.delete(other_user)\\n\\n\\nclass TestReadMetadata:\\n    async def test_read_metadata_prefers_db(self, active_user, tmp_path: Path):\\n        record = await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_read_db\\\",\\n            model_selection={\\\"name\\\": \\\"from_db\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        await knowledge_base_service.update_stats(record.id, chunks=7, words=42, characters=100, size_bytes=2048)\\n\\n        # Write a conflicting disk copy \u2014 DB read should win.\\n        kb_path = tmp_path / \\\"phase_15_kb_read_db\\\"\\n        kb_path.mkdir()\\n        (kb_path / \\\"embedding_metadata.json\\\").write_text(json.dumps({\\\"embedding_provider\\\": \\\"from_disk\\\", \\\"chunks\\\": 999}))\\n\\n        metadata = await knowledge_base_service.read_metadata(\\n            user_id=active_user.id, name=\\\"phase_15_kb_read_db\\\", kb_path=kb_path\\n        )\\n        assert metadata[\\\"embedding_provider\\\"] == \\\"OpenAI\\\"\\n        assert metadata[\\\"embedding_model\\\"] == \\\"from_db\\\"\\n        assert metadata[\\\"chunks\\\"] == 7\\n\\n    async def test_read_metadata_falls_back_to_disk(self, active_user, tmp_path: Path):\\n        kb_path = tmp_path / \\\"phase_15_kb_only_disk\\\"\\n        kb_path.mkdir()\\n        (kb_path / \\\"embedding_metadata.json\\\").write_text(json.dumps({\\\"embedding_provider\\\": \\\"only_disk\\\", \\\"chunks\\\": 3}))\\n\\n        metadata = await knowledge_base_service.read_metadata(\\n            user_id=active_user.id, name=\\\"phase_15_kb_only_disk\\\", kb_path=kb_path\\n        )\\n        assert metadata[\\\"embedding_provider\\\"] == \\\"only_disk\\\"\\n        assert metadata[\\\"chunks\\\"] == 3\\n\\n    async def test_read_metadata_returns_empty_when_nowhere(self, active_user, tmp_path: Path):\\n        metadata = await knowledge_base_service.read_metadata(\\n            user_id=active_user.id, name=\\\"not_in_db_or_disk\\\", kb_path=tmp_path / \\\"ghost\\\"\\n        )\\n        assert metadata == {}\\n\\n\\nclass TestUniqueConstraint:\\n    async def test_duplicate_user_name_rejected(self, active_user):\\n        from sqlalchemy.exc import IntegrityError\\n\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=\\\"phase_15_kb_dup\\\",\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n        )\\n        with pytest.raises(IntegrityError):\\n            await knowledge_base_service.create_record(\\n                user_id=active_user.id,\\n                name=\\\"phase_15_kb_dup\\\",\\n                model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_opensearch_backend.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0c20a1831b3350b9228e2d003ea7da9bb72822b69d8dd71081455cca75a12deb\",\"content\":\"\\\"\\\"\\\"Unit tests for ``OpenSearchBackend`` defaults.\\n\\nPins the default vector-field name to ``vector_field`` \u2014 the field\\nLangChain's ``OpenSearchVectorSearch`` actually writes embeddings to.\\nThat wrapper resolves ``vector_field`` from per-call kwargs (default\\n``\\\"vector_field\\\"``) and ignores the value passed to its constructor;\\nthe KB backend never passes a per-call override, so ingestion writes\\nand similarity searches both land on ``vector_field``. ``iter_documents``\\nreads ``DEFAULT_VECTOR_FIELD`` to pull stored embeddings back, so a\\nregression here (e.g. back to ``chunk_embedding``) silently returns\\n``_embeddings: None`` for every retrieved chunk even though retrieval\\nitself still works \u2014 the exact ``include_embeddings`` bug these tests\\nguard.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.knowledge_bases.backends import OpenSearchBackend\\nfrom lfx.base.knowledge_bases.backends.opensearch import (\\n    DEFAULT_TEXT_FIELD,\\n    DEFAULT_VECTOR_FIELD,\\n    derive_index_name,\\n)\\n\\npytestmark = pytest.mark.usefixtures(\\\"fake_opensearchpy\\\")\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _make_backend(\\n    kb_path: Path,\\n    backend_config: dict | None = None,\\n) -> OpenSearchBackend:\\n    backend = OpenSearchBackend(\\n        kb_name=\\\"kb_os_defaults\\\",\\n        kb_path=kb_path,\\n        backend_config=backend_config or {\\\"index_name\\\": \\\"test_index\\\"},\\n    )\\n    # Pre-populate resolved secrets so ``ensure_ready`` is a no-op and\\n    # ``_build_vector_store`` can run without touching variable_service.\\n    backend._resolved_url = \\\"https://example.local:9200\\\"\\n    backend._resolved_username = \\\"admin\\\"\\n    backend._resolved_password = \\\"secret\\\"  # noqa: S105 \u2014 test fixture  # pragma: allowlist secret\\n    backend._secrets_resolved = True\\n    return backend\\n\\n\\nclass TestOpenSearchBackendVectorFieldDefault:\\n    \\\"\\\"\\\"Default field names must match LangChain's write field (``vector_field``).\\\"\\\"\\\"\\n\\n    def test_relevance_score_remains_higher_is_better(self, tmp_path: Path) -> None:\\n        backend = _make_backend(tmp_path)\\n        assert backend.normalize_score(0.75) == 0.75\\n\\n    def test_default_vector_field_is_vector_field(self) -> None:\\n        # LangChain's OpenSearchVectorSearch writes embeddings under\\n        # ``vector_field`` (its per-call default, which the constructor arg\\n        # cannot change). ``iter_documents`` reads this constant to fetch them\\n        # back, so it must match the write field or include_embeddings\\n        # retrieval returns None for every chunk.\\n        assert DEFAULT_VECTOR_FIELD == \\\"vector_field\\\"\\n\\n    def test_build_vector_store_uses_vector_field_by_default(self, tmp_path: Path) -> None:\\n        backend = _make_backend(tmp_path)\\n        fake_wrapper = MagicMock(name=\\\"OpenSearchVectorSearch\\\")\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\n                \\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\",\\n                fake_wrapper,\\n            ),\\n        ):\\n            _ = backend.vector_store\\n\\n        fake_wrapper.assert_called_once()\\n        kwargs = fake_wrapper.call_args.kwargs\\n        assert kwargs[\\\"vector_field\\\"] == \\\"vector_field\\\"\\n        assert kwargs[\\\"text_field\\\"] == DEFAULT_TEXT_FIELD\\n        # Sanity-check the field the backend stashes for iter/count helpers\\n        # so the in-memory state agrees with the field LangChain reads/writes.\\n        assert backend._os_vector_field == \\\"vector_field\\\"\\n\\n    def test_build_vector_store_honours_backend_config_override(self, tmp_path: Path) -> None:\\n        # Operators with a legacy ``vector_field`` index (or any custom\\n        # name) must still be able to override via backend_config.\\n        backend = _make_backend(\\n            tmp_path,\\n            backend_config={\\\"index_name\\\": \\\"test_index\\\", \\\"vector_field\\\": \\\"embedding\\\"},\\n        )\\n        fake_wrapper = MagicMock(name=\\\"OpenSearchVectorSearch\\\")\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\n                \\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\",\\n                fake_wrapper,\\n            ),\\n        ):\\n            _ = backend.vector_store\\n\\n        kwargs = fake_wrapper.call_args.kwargs\\n        assert kwargs[\\\"vector_field\\\"] == \\\"embedding\\\"\\n        assert backend._os_vector_field == \\\"embedding\\\"\\n\\n\\nclass TestOpenSearchIndexIsolation:\\n    \\\"\\\"\\\"Each KB / Memory Base must get its own index.\\n\\n    Before this, every base copied the single global ``OPENSEARCH_INDEX_NAME``\\n    into ``backend_config`` and shared one index \u2014 mixing vectors across bases\\n    and making collection-level deletion drop everyone's data. The index is now\\n    derived from ``kb_name`` (mirroring the Chroma backends' ``collection_name``)\\n    unless an explicit ``index_name`` override is configured.\\n    \\\"\\\"\\\"\\n\\n    def _make(self, kb_path: Path, kb_name: str, backend_config: dict) -> OpenSearchBackend:\\n        backend = OpenSearchBackend(kb_name=kb_name, kb_path=kb_path, backend_config=backend_config)\\n        backend._resolved_url = \\\"https://example.local:9200\\\"\\n        backend._resolved_username = \\\"admin\\\"\\n        backend._resolved_password = \\\"secret\\\"  # noqa: S105 \u2014 test fixture  # pragma: allowlist secret\\n        backend._secrets_resolved = True\\n        return backend\\n\\n    def _built_index(self, backend: OpenSearchBackend) -> str:\\n        fake_wrapper = MagicMock(name=\\\"OpenSearchVectorSearch\\\")\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", fake_wrapper),\\n        ):\\n            _ = backend.vector_store\\n        return fake_wrapper.call_args.kwargs[\\\"index_name\\\"]\\n\\n    def test_index_derived_from_kb_name_when_unset(self, tmp_path: Path) -> None:\\n        # No ``index_name`` in config \u2192 derive from kb_name so the base is\\n        # isolated in its own index rather than the shared global one.\\n        backend = self._make(tmp_path, \\\"chat_memory_a1b2c3d4\\\", {\\\"url_variable\\\": \\\"OPENSEARCH_URL\\\"})\\n        assert self._built_index(backend) == \\\"chat_memory_a1b2c3d4\\\"\\n        assert backend._os_index == \\\"chat_memory_a1b2c3d4\\\"\\n\\n    def test_distinct_kb_names_get_distinct_indexes(self, tmp_path: Path) -> None:\\n        idx_a = self._built_index(self._make(tmp_path, \\\"mem_aaaa1111\\\", {}))\\n        idx_b = self._built_index(self._make(tmp_path, \\\"mem_bbbb2222\\\", {}))\\n        assert idx_a != idx_b\\n\\n    def test_uppercase_kb_name_is_sanitized(self, tmp_path: Path) -> None:\\n        # OpenSearch index names must be lowercase; a user-supplied KB name\\n        # (\\\"My KB\\\" \u2192 \\\"My_KB\\\") would otherwise be an invalid index.\\n        backend = self._make(tmp_path, \\\"My_KB\\\", {})\\n        assert self._built_index(backend) == \\\"my_kb\\\"\\n\\n    def test_explicit_index_name_overrides_derivation(self, tmp_path: Path) -> None:\\n        # Operators pointing a KB at an externally-managed index keep control.\\n        backend = _make_backend(tmp_path, backend_config={\\\"index_name\\\": \\\"external_index\\\"})\\n        assert self._built_index(backend) == \\\"external_index\\\"\\n        assert backend._os_index == \\\"external_index\\\"\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"kb_name\\\", \\\"expected\\\"),\\n    [\\n        (\\\"chat_memory_a1b2c3d4\\\", \\\"chat_memory_a1b2c3d4\\\"),\\n        (\\\"My-KB!\\\", \\\"my-kb_\\\"),\\n        (\\\"  Docs 2024  \\\", \\\"docs_2024\\\"),\\n        (\\\"_leading\\\", \\\"leading\\\"),\\n        (\\\"\\\", \\\"kb\\\"),\\n        (\\\"..\\\", \\\"kb\\\"),\\n    ],\\n)\\ndef test_derive_index_name_table(kb_name: str, expected: str) -> None:\\n    assert derive_index_name(kb_name) == expected\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"config_value\\\", \\\"expected\\\"),\\n    [\\n        (None, \\\"vector_field\\\"),\\n        (\\\"\\\", \\\"vector_field\\\"),\\n        (\\\"custom_vec\\\", \\\"custom_vec\\\"),\\n    ],\\n)\\ndef test_vector_field_resolution_table(tmp_path: Path, config_value: str | None, expected: str) -> None:\\n    \\\"\\\"\\\"Empty / missing config falls back to the default; truthy wins.\\\"\\\"\\\"\\n    cfg: dict = {\\\"index_name\\\": \\\"test_index\\\"}\\n    if config_value is not None:\\n        cfg[\\\"vector_field\\\"] = config_value\\n    backend = _make_backend(tmp_path, backend_config=cfg)\\n    fake_wrapper = MagicMock(name=\\\"OpenSearchVectorSearch\\\")\\n    with (\\n        patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n        patch(\\n            \\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\",\\n            fake_wrapper,\\n        ),\\n    ):\\n        _ = backend.vector_store\\n\\n    assert fake_wrapper.call_args.kwargs[\\\"vector_field\\\"] == expected\\n\\n\\nclass TestOpenSearchIterDocumentsEmbeddings:\\n    \\\"\\\"\\\"``iter_documents`` must return stored embeddings from the write field.\\n\\n    The ``include_embeddings`` retrieval path gathers these vectors via\\n    ``iter_documents`` and joins them back onto the search results. LangChain\\n    stores them under ``vector_field`` (see module docstring); reading any\\n    other field yields ``embedding=None`` and the Knowledge component surfaces\\n    ``_embeddings: None`` for every chunk \u2014 the bug this guards. The\\n    ``_source`` shapes below mirror real upload-ingested OpenSearch documents:\\n    ``{text, metadata, vector_field}``, with a doc-level ``_id`` (a UUID)\\n    intentionally distinct from any metadata ``_id`` (a content hash).\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_iter_documents_reads_embeddings_from_vector_field(self, tmp_path: Path) -> None:\\n        backend = _make_backend(tmp_path)\\n        upload_vec = [0.1, 0.2, 0.3]\\n        identifier_vec = [0.4, 0.5, 0.6]\\n        # Two real-world shapes: an upload-ingested chunk (no ``_id`` in\\n        # metadata, joined downstream on content) and an identifier-column\\n        # chunk (``_id`` present, joined on id).\\n        fake_hits = [\\n            {\\n                \\\"_id\\\": \\\"0d73456e-4a65-4edd-9d6e-0dbf0f7d1063\\\",\\n                \\\"_source\\\": {\\n                    \\\"text\\\": \\\"upload chunk\\\",\\n                    \\\"metadata\\\": {\\\"file_name\\\": \\\"a.txt\\\", \\\"chunk_index\\\": 0},\\n                    \\\"vector_field\\\": upload_vec,\\n                },\\n            },\\n            {\\n                \\\"_id\\\": \\\"1f84567a-1111-2222-3333-444455556666\\\",\\n                \\\"_source\\\": {\\n                    \\\"text\\\": \\\"identifier chunk\\\",\\n                    \\\"metadata\\\": {\\\"id\\\": \\\"1\\\", \\\"category\\\": \\\"geo\\\", \\\"_id\\\": \\\"6b86b273ff34\\\"},\\n                    \\\"vector_field\\\": identifier_vec,\\n                },\\n            },\\n        ]\\n\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", MagicMock()),\\n            patch(\\\"opensearchpy.helpers.scan\\\", return_value=(hit for hit in fake_hits)),\\n        ):\\n            _ = backend.vector_store  # resolves _os_* fields from defaults\\n            batches = [batch async for batch in backend.iter_documents(include_embeddings=True)]\\n\\n        docs = [doc for batch in batches for doc in batch]\\n        assert len(docs) == 2\\n        by_content = {doc.content: doc for doc in docs}\\n        # Upload-style chunk: embedding populated, no _id (content-keyed join).\\n        assert by_content[\\\"upload chunk\\\"].embedding == upload_vec\\n        assert \\\"_id\\\" not in by_content[\\\"upload chunk\\\"].metadata\\n        # Identifier-style chunk: embedding populated, _id preserved for the join.\\n        assert by_content[\\\"identifier chunk\\\"].embedding == identifier_vec\\n        assert by_content[\\\"identifier chunk\\\"].metadata.get(\\\"_id\\\") == \\\"6b86b273ff34\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_iter_documents_falls_back_when_config_names_unwritten_field(self, tmp_path: Path) -> None:\\n        # The real-world failure: the DB-providers UI persists\\n        # ``backend_config.vector_field = \\\"chunk_embedding\\\"``, but LangChain\\n        # ignores that and writes embeddings under ``vector_field``. Reading the\\n        # configured name alone returns None for every chunk (the reported bug);\\n        # the fallback to LangChain's field must still surface the vector.\\n        backend = _make_backend(\\n            tmp_path,\\n            backend_config={\\\"index_name\\\": \\\"test_index\\\", \\\"vector_field\\\": \\\"chunk_embedding\\\"},\\n        )\\n        embedding = [0.7, 0.8, 0.9]\\n        fake_hits = [\\n            {\\n                \\\"_id\\\": \\\"doc-uuid\\\",\\n                \\\"_source\\\": {\\n                    \\\"text\\\": \\\"legacy-config chunk\\\",\\n                    \\\"metadata\\\": {\\\"file_name\\\": \\\"a.txt\\\"},\\n                    \\\"vector_field\\\": embedding,  # where LangChain actually wrote it\\n                },\\n            },\\n        ]\\n\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", MagicMock()),\\n            patch(\\\"opensearchpy.helpers.scan\\\", return_value=(hit for hit in fake_hits)),\\n        ):\\n            _ = backend.vector_store\\n            # The configured (never-written) field is what the backend stashes\u2026\\n            assert backend._os_vector_field == \\\"chunk_embedding\\\"\\n            batches = [batch async for batch in backend.iter_documents(include_embeddings=True)]\\n\\n        docs = [doc for batch in batches for doc in batch]\\n        # \u2026yet the embedding still comes back via the LangChain-default fallback.\\n        assert docs[0].embedding == embedding\\n\\n    @pytest.mark.asyncio\\n    async def test_iter_documents_prefers_configured_field_when_present(self, tmp_path: Path) -> None:\\n        # An externally-populated index that genuinely stores vectors under the\\n        # configured field must be read from that field, not the fallback.\\n        backend = _make_backend(\\n            tmp_path,\\n            backend_config={\\\"index_name\\\": \\\"test_index\\\", \\\"vector_field\\\": \\\"embedding\\\"},\\n        )\\n        configured_vec = [1.0, 1.1, 1.2]\\n        fake_hits = [\\n            {\\\"_id\\\": \\\"x\\\", \\\"_source\\\": {\\\"text\\\": \\\"c\\\", \\\"metadata\\\": {\\\"k\\\": \\\"v\\\"}, \\\"embedding\\\": configured_vec}},\\n        ]\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", MagicMock()),\\n            patch(\\\"opensearchpy.helpers.scan\\\", return_value=(hit for hit in fake_hits)),\\n        ):\\n            _ = backend.vector_store\\n            batches = [batch async for batch in backend.iter_documents(include_embeddings=True)]\\n\\n        docs = [doc for batch in batches for doc in batch]\\n        assert docs[0].embedding == configured_vec\\n\\n    @pytest.mark.asyncio\\n    async def test_iter_documents_excludes_real_vector_field_when_not_requested(self, tmp_path: Path) -> None:\\n        # When embeddings aren't requested, the scan excludes the vector field\\n        # to keep scroll payloads small (count()/iter() never need it). The\\n        # exclusion must target the real write field, else large vectors keep\\n        # streaming on every call.\\n        backend = _make_backend(tmp_path)\\n        fake_hits = [{\\\"_id\\\": \\\"x\\\", \\\"_source\\\": {\\\"text\\\": \\\"c\\\", \\\"metadata\\\": {\\\"k\\\": \\\"v\\\"}}}]\\n        captured: dict = {}\\n\\n        def _fake_scan(_client, **kwargs):\\n            captured.update(kwargs)\\n            return (hit for hit in fake_hits)\\n\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", MagicMock()),\\n            patch(\\\"opensearchpy.helpers.scan\\\", side_effect=_fake_scan),\\n        ):\\n            _ = backend.vector_store\\n            batches = [batch async for batch in backend.iter_documents(include_embeddings=False)]\\n\\n        docs = [doc for batch in batches for doc in batch]\\n        assert docs[0].embedding is None\\n        assert captured.get(\\\"_source_excludes\\\") == [\\\"vector_field\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_iter_documents_excludes_both_fields_for_legacy_config(self, tmp_path: Path) -> None:\\n        # With a legacy ``chunk_embedding`` config the scan must exclude both\\n        # the configured name and LangChain's real field, else the (large)\\n        # ``vector_field`` vector keeps streaming on every count()/iter().\\n        backend = _make_backend(\\n            tmp_path,\\n            backend_config={\\\"index_name\\\": \\\"test_index\\\", \\\"vector_field\\\": \\\"chunk_embedding\\\"},\\n        )\\n        fake_hits = [{\\\"_id\\\": \\\"x\\\", \\\"_source\\\": {\\\"text\\\": \\\"c\\\", \\\"metadata\\\": {\\\"k\\\": \\\"v\\\"}}}]\\n        captured: dict = {}\\n\\n        def _fake_scan(_client, **kwargs):\\n            captured.update(kwargs)\\n            return (hit for hit in fake_hits)\\n\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=MagicMock()),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\", MagicMock()),\\n            patch(\\\"opensearchpy.helpers.scan\\\", side_effect=_fake_scan),\\n        ):\\n            _ = backend.vector_store\\n            _ = [batch async for batch in backend.iter_documents(include_embeddings=False)]\\n\\n        assert captured.get(\\\"_source_excludes\\\") == [\\\"chunk_embedding\\\", \\\"vector_field\\\"]\\n\\n\\nclass TestOpenSearchSimilaritySearchFilterHandling:\\n    \\\"\\\"\\\"Pin the ``filter`` kwarg behaviour of ``similarity_search``.\\n\\n    LangChain's ``OpenSearchVectorSearch`` forwards ``filter`` straight into\\n    the k-NN query body. Sending ``\\\"filter\\\": null`` makes OpenSearch reject\\n    the request with ``x_content_parse_exception: [knn] filter doesn't\\n    support values of type: VALUE_NULL``. If the override regresses and\\n    forwards ``filter=None`` (or an empty dict), every KB retrieval against\\n    OpenSearch would fail \u2014 silently looking like 'no results' to any\\n    component that swallows the error downstream. These tests guard the\\n    canonical case Langflow itself relies on at\\n    ``components/files_and_knowledge/retrieval.py``, which never passes a\\n    filter at all.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_filter_none_is_dropped_from_call(self, tmp_path: Path) -> None:\\n        backend = _make_backend(tmp_path)\\n        fake_vs = MagicMock()\\n        fake_vs.asimilarity_search = AsyncMock(return_value=[])\\n        backend._vector_store = fake_vs\\n\\n        await backend.similarity_search(query=\\\"hi\\\", k=3)\\n\\n        kwargs = fake_vs.asimilarity_search.call_args.kwargs\\n        assert kwargs == {\\\"query\\\": \\\"hi\\\", \\\"k\\\": 3}\\n        assert \\\"filter\\\" not in kwargs\\n\\n    @pytest.mark.asyncio\\n    async def test_filter_empty_dict_is_dropped_from_call(self, tmp_path: Path) -> None:\\n        # An empty dict is \\\"no filter requested\\\" \u2014 must not reach OpenSearch\\n        # either, since the k-NN parser also rejects empty objects.\\n        backend = _make_backend(tmp_path)\\n        fake_vs = MagicMock()\\n        fake_vs.asimilarity_search = AsyncMock(return_value=[])\\n        backend._vector_store = fake_vs\\n\\n        await backend.similarity_search(query=\\\"hi\\\", k=3, filter={})\\n\\n        assert \\\"filter\\\" not in fake_vs.asimilarity_search.call_args.kwargs\\n\\n    @pytest.mark.asyncio\\n    async def test_flat_filter_is_translated_to_bool_dsl(self, tmp_path: Path) -> None:\\n        # Callers hand the backend the portable flat ``{key: value}`` shape\\n        # (the same contract Chroma reads as ``$eq``). The backend must\\n        # translate it into OpenSearch bool DSL \u2014 LangChain injects a\\n        # non-empty ``filter`` into the k-NN query and a flat dict would be\\n        # rejected / silently match nothing. Regressing this breaks the\\n        # default session-filtered Memory Base retrieval path.\\n        backend = _make_backend(tmp_path)\\n        fake_vs = MagicMock()\\n        fake_vs.asimilarity_search = AsyncMock(return_value=[])\\n        backend._vector_store = fake_vs\\n\\n        await backend.similarity_search(query=\\\"hi\\\", k=3, filter={\\\"session_id\\\": \\\"s1\\\"})\\n\\n        forwarded = fake_vs.asimilarity_search.call_args.kwargs[\\\"filter\\\"]\\n        assert forwarded == {\\n            \\\"bool\\\": {\\n                \\\"must\\\": [\\n                    {\\n                        \\\"bool\\\": {\\n                            \\\"should\\\": [\\n                                {\\\"match\\\": {\\\"session_id\\\": \\\"s1\\\"}},\\n                                {\\\"match\\\": {\\\"metadata.session_id\\\": \\\"s1\\\"}},\\n                            ],\\n                            \\\"minimum_should_match\\\": 1,\\n                        }\\n                    }\\n                ]\\n            }\\n        }\\n        # The retrieval filter and the delete rollback path must produce the\\n        # exact same translation so they can never drift.\\n        assert forwarded == backend._translate_where({\\\"session_id\\\": \\\"s1\\\"})\\n\\n    @pytest.mark.asyncio\\n    async def test_with_scores_routes_to_score_method_and_drops_none_filter(self, tmp_path: Path) -> None:\\n        # When the caller asks for scores we use ``asimilarity_search_with_score``;\\n        # the filter handling must apply identically on that branch.\\n        backend = _make_backend(tmp_path)\\n        fake_vs = MagicMock()\\n        fake_vs.asimilarity_search_with_score = AsyncMock(return_value=[])\\n        backend._vector_store = fake_vs\\n\\n        await backend.similarity_search(query=\\\"hi\\\", k=2, with_scores=True)\\n\\n        kwargs = fake_vs.asimilarity_search_with_score.call_args.kwargs\\n        assert kwargs == {\\\"query\\\": \\\"hi\\\", \\\"k\\\": 2}\\n        assert \\\"filter\\\" not in kwargs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_postgres_backend.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dac28d90f8a303f5747e4285cf83faea8ae767667610c15bf50e3c7e4b2c8d71\",\"content\":\"\\\"\\\"\\\"Live pgVector integration tests for ``PostgresBackend``.\\n\\nGated on an explicit opt-in plus a reachable pgvector database: set\\n``LANGFLOW_RUN_PGVECTOR_INTEGRATION_TESTS=1`` and ``PGVECTOR_CONNECTION_STRING``\\n(and install the pgvector extra) to exercise the real add / search / count /\\niter / delete path against Postgres; they skip cleanly otherwise.\\n\\nThe database-free unit tests for this backend live next to the code, in\\n``src/lfx/tests/unit/base/knowledge_bases/test_postgres_backend.py``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nimport uuid\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.base.knowledge_bases.backends import create_backend\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\n# --------------------------------------------------------------------------\\n# Integration: requires a reachable pgvector database.\\n# --------------------------------------------------------------------------\\n\\n\\ndef _require_live_pgvector() -> str:\\n    if os.getenv(\\\"LANGFLOW_RUN_PGVECTOR_INTEGRATION_TESTS\\\") != \\\"1\\\":\\n        pytest.skip(\\\"Set LANGFLOW_RUN_PGVECTOR_INTEGRATION_TESTS=1 to run live pgvector tests\\\")\\n    conn = os.getenv(\\\"PGVECTOR_CONNECTION_STRING\\\")\\n    if not conn:\\n        pytest.skip(\\\"PGVECTOR_CONNECTION_STRING not set \u2014 skipping live pgvector integration test\\\")\\n    try:\\n        import pgvector  # noqa: F401\\n        from pgvector.sqlalchemy import Vector  # noqa: F401\\n    except (ImportError, RuntimeError):\\n        pytest.skip(\\\"pgvector client package not installed \u2014 install the pgvector extra\\\")\\n    return conn\\n\\n\\n@pytest.fixture\\ndef fake_embeddings():\\n    from langchain_core.embeddings import DeterministicFakeEmbedding\\n\\n    return DeterministicFakeEmbedding(size=16)\\n\\n\\n@pytest.mark.api_key_required\\nclass TestPostgresBackendLive:\\n    \\\"\\\"\\\"Exercises the real vector path against a pgvector database when available.\\\"\\\"\\\"\\n\\n    async def test_full_lifecycle(self, tmp_path: Path, fake_embeddings) -> None:\\n        _require_live_pgvector()\\n        from langchain_core.documents import Document\\n\\n        kb_name = f\\\"kb_it_{uuid.uuid4().hex[:8]}\\\"\\n        backend = create_backend(\\n            \\\"postgres\\\",\\n            kb_name=kb_name,\\n            kb_path=tmp_path,\\n            backend_config={},\\n            embedding_function=fake_embeddings,\\n            user_id=uuid.uuid4(),\\n        )\\n        try:\\n            await backend.ensure_ready()\\n            tc = await backend.test_connection()\\n            if not tc.ok:\\n                pytest.skip(f\\\"pgvector not reachable: {tc.message}\\\")\\n\\n            await backend.add_documents(\\n                [\\n                    Document(page_content=\\\"cats are great\\\", metadata={\\\"topic\\\": \\\"cats\\\"}),\\n                    Document(page_content=\\\"dogs are loyal\\\", metadata={\\\"topic\\\": \\\"dogs\\\"}),\\n                ]\\n            )\\n            assert await backend.count() == 2\\n\\n            results = await backend.similarity_search(\\\"feline\\\", k=1, with_scores=True)\\n            assert len(results) == 1  # inherited base similarity_search path\\n\\n            streamed = 0\\n            async for batch in backend.iter_documents(batch_size=1):\\n                streamed += len(batch)\\n            assert streamed == 2\\n\\n            await backend.delete_by({\\\"topic\\\": \\\"dogs\\\"})\\n            assert await backend.count() == 1\\n        finally:\\n            with contextlib.suppress(Exception):\\n                await backend.delete_collection()\\n            await backend.teardown()\\n\\n    async def test_hnsw_index_created_on_ingest(self, tmp_path: Path, fake_embeddings) -> None:\\n        _require_live_pgvector()\\n        from langchain_core.documents import Document\\n        from sqlalchemy import text\\n\\n        backend = create_backend(\\n            \\\"postgres\\\",\\n            kb_name=f\\\"kb_idx_{uuid.uuid4().hex[:8]}\\\",\\n            kb_path=tmp_path,\\n            backend_config={},\\n            embedding_function=fake_embeddings,\\n            user_id=uuid.uuid4(),\\n        )\\n        try:\\n            await backend.ensure_ready()\\n            tc = await backend.test_connection()\\n            if not tc.ok:\\n                pytest.skip(f\\\"pgvector not reachable: {tc.message}\\\")\\n\\n            await backend.add_documents([Document(page_content=\\\"hello\\\", metadata={})])\\n\\n            engine = backend._ensure_async_engine()\\n            async with engine.connect() as conn:\\n                index_defs = (\\n                    (\\n                        await conn.execute(\\n                            text(\\\"SELECT indexdef FROM pg_indexes WHERE tablename = :name\\\"),\\n                            {\\\"name\\\": backend.table_name},\\n                        )\\n                    )\\n                    .scalars()\\n                    .all()\\n                )\\n            # A 16-dim table (well under the HNSW ceiling) must carry an HNSW index.\\n            assert any(\\\"hnsw\\\" in definition.lower() for definition in index_defs), index_defs\\n        finally:\\n            with contextlib.suppress(Exception):\\n                await backend.delete_collection()\\n            await backend.teardown()\\n\\n    async def test_similarity_search_plan_uses_hnsw_index(self, tmp_path: Path, fake_embeddings) -> None:\\n        _require_live_pgvector()\\n        from langchain_core.documents import Document\\n        from sqlalchemy import text\\n\\n        backend = create_backend(\\n            \\\"postgres\\\",\\n            kb_name=f\\\"kb_plan_{uuid.uuid4().hex[:8]}\\\",\\n            kb_path=tmp_path,\\n            backend_config={},\\n            embedding_function=fake_embeddings,\\n            user_id=uuid.uuid4(),\\n        )\\n        try:\\n            await backend.ensure_ready()\\n            tc = await backend.test_connection()\\n            if not tc.ok:\\n                pytest.skip(f\\\"pgvector not reachable: {tc.message}\\\")\\n\\n            await backend.add_documents([Document(page_content=f\\\"doc {i}\\\", metadata={}) for i in range(50)])\\n\\n            query_vector = await fake_embeddings.aembed_query(\\\"doc 1\\\")\\n            literal = \\\"[\\\" + \\\",\\\".join(str(v) for v in query_vector) + \\\"]\\\"\\n            engine = backend._ensure_async_engine()\\n            async with engine.begin() as conn:\\n                # Force the planner to prefer the ANN index for this tiny table so\\n                # the assertion is about \\\"is the index usable\\\", not planner cost.\\n                await conn.execute(text(\\\"SET LOCAL enable_seqscan = off\\\"))\\n                plan_rows = (\\n                    (\\n                        await conn.execute(\\n                            text(\\n                                f'EXPLAIN SELECT id FROM \\\"{backend.table_name}\\\" '  # noqa: S608 \u2014 validated name\\n                                f\\\"ORDER BY embedding <=> '{literal}'::vector LIMIT 5\\\"\\n                            )\\n                        )\\n                    )\\n                    .scalars()\\n                    .all()\\n                )\\n            plan = \\\"\\\\n\\\".join(plan_rows)\\n            assert f\\\"{backend.table_name}_hnsw\\\" in plan, plan\\n        finally:\\n            with contextlib.suppress(Exception):\\n                await backend.delete_collection()\\n            await backend.teardown()\\n\\n    async def test_mixed_embedding_dimensions_coexist(self, tmp_path: Path) -> None:\\n        _require_live_pgvector()\\n        from langchain_core.documents import Document\\n        from langchain_core.embeddings import DeterministicFakeEmbedding\\n\\n        # Two KBs on the same deployment using different embedding dimensions.\\n        # The shared-table layout could not do this; per-collection typed tables can.\\n        small = create_backend(\\n            \\\"postgres\\\",\\n            kb_name=f\\\"kb_small_{uuid.uuid4().hex[:8]}\\\",\\n            kb_path=tmp_path,\\n            backend_config={},\\n            embedding_function=DeterministicFakeEmbedding(size=8),\\n            user_id=uuid.uuid4(),\\n        )\\n        large = create_backend(\\n            \\\"postgres\\\",\\n            kb_name=f\\\"kb_large_{uuid.uuid4().hex[:8]}\\\",\\n            kb_path=tmp_path,\\n            backend_config={},\\n            embedding_function=DeterministicFakeEmbedding(size=32),\\n            user_id=uuid.uuid4(),\\n        )\\n        try:\\n            await small.ensure_ready()\\n            tc = await small.test_connection()\\n            if not tc.ok:\\n                pytest.skip(f\\\"pgvector not reachable: {tc.message}\\\")\\n\\n            assert small.table_name != large.table_name\\n            await small.add_documents([Document(page_content=\\\"a\\\", metadata={})])\\n            await large.add_documents([Document(page_content=\\\"b\\\", metadata={})])\\n\\n            assert await small.count() == 1\\n            assert await large.count() == 1\\n            assert len(await small.similarity_search(\\\"a\\\", k=1)) == 1\\n            assert len(await large.similarity_search(\\\"b\\\", k=1)) == 1\\n        finally:\\n            for backend in (small, large):\\n                with contextlib.suppress(Exception):\\n                    await backend.delete_collection()\\n                await backend.teardown()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_test_connection.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c1b2d338a035cacf589ea7ee746fa5460d9839b7ff44a5833ecf2cdc6ecccf08\",\"content\":\"\\\"\\\"\\\"Unit tests for ``BaseVectorStoreBackend.test_connection`` and overrides.\\n\\nExercises the default implementation (via Chroma + a stub backend),\\nthe Chroma-specific path-writability check, and the OpenSearch\\n``cluster.info`` ping with each error class mapped to the\\nappropriate user-facing message.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom typing import TYPE_CHECKING, Any\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.knowledge_bases.backends import (\\n    BackendType,\\n    ChromaBackend,\\n    OpenSearchBackend,\\n    TestConnectionResult,\\n)\\nfrom lfx.base.knowledge_bases.backends.base import BaseVectorStoreBackend\\n\\npytestmark = pytest.mark.usefixtures(\\\"fake_opensearchpy\\\")\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\nclass _StubBackend(BaseVectorStoreBackend):\\n    \\\"\\\"\\\"Minimal backend whose ``_build_vector_store`` is controllable.\\\"\\\"\\\"\\n\\n    backend_type = BackendType.CHROMA  # arbitrary; not exercised here\\n\\n    def __init__(self, *, kb_path: Path, build_error: Exception | None = None) -> None:\\n        super().__init__(kb_name=\\\"stub_kb\\\", kb_path=kb_path)\\n        self._build_error = build_error\\n\\n    def _build_vector_store(self) -> Any:\\n        if self._build_error is not None:\\n            raise self._build_error\\n        return MagicMock(name=\\\"vector_store\\\")\\n\\n\\nclass TestDefaultTestConnection:\\n    \\\"\\\"\\\"Default impl on ``BaseVectorStoreBackend``.\\n\\n    Exercised via a stub backend so we can drive the success and failure\\n    paths without depending on any concrete vector-store library.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_ok_when_build_succeeds(self, tmp_path: Path) -> None:\\n        backend = _StubBackend(kb_path=tmp_path)\\n        result = await backend.test_connection()\\n        assert isinstance(result, TestConnectionResult)\\n        assert result.ok is True\\n        assert result.message\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_failure_when_build_raises(self, tmp_path: Path) -> None:\\n        backend = _StubBackend(kb_path=tmp_path, build_error=RuntimeError(\\\"boom\\\"))\\n        result = await backend.test_connection()\\n        assert result.ok is False\\n        assert \\\"boom\\\" in result.message\\n        assert result.details.get(\\\"type\\\") == \\\"RuntimeError\\\"\\n\\n\\nclass TestChromaTestConnection:\\n    \\\"\\\"\\\"Chroma override verifies the kb_path is writable + client opens.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_ok_for_writable_path(self, tmp_path: Path) -> None:\\n        kb_path = tmp_path / \\\"kb_chroma_ok\\\"\\n        backend = ChromaBackend(kb_name=\\\"kb_chroma_ok\\\", kb_path=kb_path)\\n        try:\\n            result = await backend.test_connection()\\n        finally:\\n            await backend.teardown()\\n        assert result.ok is True\\n        assert \\\"Chroma\\\" in result.message\\n        assert result.details.get(\\\"path\\\") == str(kb_path)\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_failure_for_unwritable_path(self, tmp_path: Path) -> None:\\n        # Drop a read-only parent directory so mkdir cannot create the\\n        # KB subdirectory inside it. ``chmod`` semantics differ on\\n        # Windows; gate the test on POSIX where 0o500 reliably blocks\\n        # writes for the current user.\\n        if os.name != \\\"posix\\\":\\n            pytest.skip(\\\"Permission semantics rely on POSIX chmod.\\\")\\n        parent = tmp_path / \\\"ro_parent\\\"\\n        parent.mkdir()\\n        parent.chmod(0o500)\\n        kb_path = parent / \\\"kb_chroma_fail\\\"\\n        backend = ChromaBackend(kb_name=\\\"kb_chroma_fail\\\", kb_path=kb_path)\\n        try:\\n            result = await backend.test_connection()\\n        finally:\\n            await backend.teardown()\\n            # Restore permissions so pytest's tmp_path cleanup succeeds.\\n            parent.chmod(0o700)\\n        assert result.ok is False\\n        assert \\\"not writable\\\" in result.message\\n        assert result.details.get(\\\"type\\\") in {\\\"PermissionError\\\", \\\"OSError\\\"}\\n\\n\\nclass TestOpenSearchTestConnection:\\n    \\\"\\\"\\\"OpenSearch override pings ``cluster.info`` and maps errors.\\\"\\\"\\\"\\n\\n    def _make_backend(\\n        self,\\n        kb_path: Path,\\n        *,\\n        url: str = \\\"https://example.local:9200\\\",\\n        username: str | None = \\\"admin\\\",\\n        password: str | None = \\\"secret\\\",  # noqa: S107 \u2014 test fixture\\n    ) -> OpenSearchBackend:\\n        backend = OpenSearchBackend(\\n            kb_name=\\\"kb_os_test\\\",\\n            kb_path=kb_path,\\n            backend_config={\\\"index_name\\\": \\\"test_index\\\"},\\n        )\\n        # Pre-populate resolved secrets so ``ensure_ready`` is a no-op.\\n        backend._resolved_url = url\\n        backend._resolved_username = username\\n        backend._resolved_password = password\\n        backend._secrets_resolved = True\\n        return backend\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_ok_when_cluster_info_succeeds(self, tmp_path: Path) -> None:\\n        backend = self._make_backend(tmp_path)\\n        fake_client = MagicMock()\\n        fake_client.info.return_value = {\\n            \\\"cluster_name\\\": \\\"my-cluster\\\",\\n            \\\"version\\\": {\\\"number\\\": \\\"2.11.0\\\"},\\n        }\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=fake_client),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\"),\\n        ):\\n            result = await backend.test_connection()\\n        assert result.ok is True\\n        assert \\\"my-cluster\\\" in result.message\\n        assert result.details.get(\\\"cluster_name\\\") == \\\"my-cluster\\\"\\n        assert result.details.get(\\\"version\\\") == \\\"2.11.0\\\"\\n        fake_client.info.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_auth_message_on_authentication_exception(self, tmp_path: Path) -> None:\\n        from opensearchpy.exceptions import AuthenticationException\\n\\n        backend = self._make_backend(tmp_path)\\n        fake_client = MagicMock()\\n        fake_client.info.side_effect = AuthenticationException(401, \\\"auth failed\\\", {})\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=fake_client),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\"),\\n        ):\\n            result = await backend.test_connection()\\n        assert result.ok is False\\n        assert result.details.get(\\\"type\\\") == \\\"AuthenticationException\\\"\\n        assert \\\"Authentication failed\\\" in result.message\\n\\n    @pytest.mark.asyncio\\n    async def test_treats_authorization_exception_as_reachable(self, tmp_path: Path) -> None:\\n        # A 403 on client.info (GET /) means the account lacks cluster:monitor/main,\\n        # but the cluster is reachable and the credentials authenticated. KB\\n        # create/ingest uses index-scoped permissions granted separately, so a\\n        # least-privilege account must still pass the liveness check.\\n        from opensearchpy.exceptions import AuthorizationException\\n\\n        backend = self._make_backend(tmp_path)\\n        fake_client = MagicMock()\\n        fake_client.info.side_effect = AuthorizationException(403, \\\"forbidden\\\", {})\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=fake_client),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\"),\\n        ):\\n            result = await backend.test_connection()\\n        assert result.ok is True\\n        assert result.details.get(\\\"type\\\") == \\\"AuthorizationException\\\"\\n        assert result.details.get(\\\"reachable\\\") is True\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_connection_message_on_connection_error(self, tmp_path: Path) -> None:\\n        from opensearchpy.exceptions import ConnectionError as OSConnectionError\\n\\n        backend = self._make_backend(tmp_path)\\n        fake_client = MagicMock()\\n        fake_client.info.side_effect = OSConnectionError(\\\"N/A\\\", \\\"refused\\\", Exception(\\\"refused\\\"))\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=fake_client),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\"),\\n        ):\\n            result = await backend.test_connection()\\n        assert result.ok is False\\n        assert result.details.get(\\\"type\\\") == \\\"ConnectionError\\\"\\n        assert \\\"Could not reach the cluster\\\" in result.message\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_ssl_message_on_ssl_error(self, tmp_path: Path) -> None:\\n        from opensearchpy.exceptions import SSLError as OSSSLError\\n\\n        backend = self._make_backend(tmp_path)\\n        fake_client = MagicMock()\\n        fake_client.info.side_effect = OSSSLError(\\\"N/A\\\", \\\"ssl bad\\\", Exception(\\\"ssl bad\\\"))\\n        with (\\n            patch(\\\"opensearchpy.OpenSearch\\\", return_value=fake_client),\\n            patch(\\\"langchain_community.vectorstores.OpenSearchVectorSearch\\\"),\\n        ):\\n            result = await backend.test_connection()\\n        assert result.ok is False\\n        assert result.details.get(\\\"type\\\") == \\\"SSLError\\\"\\n        assert \\\"TLS handshake failed\\\" in result.message\\n\\n    @pytest.mark.asyncio\\n    async def test_returns_failure_when_url_secret_missing(self, tmp_path: Path) -> None:\\n        # Force ensure_ready to fail by leaving the resolved URL unset.\\n        backend = OpenSearchBackend(\\n            kb_name=\\\"kb_os_missing_url\\\",\\n            kb_path=tmp_path,\\n            backend_config={\\\"index_name\\\": \\\"idx\\\"},\\n        )\\n        # ``_resolve_secrets`` raises ValueError when the URL variable is\\n        # not configured; do not pre-populate ``_secrets_resolved`` so\\n        # the resolution path actually runs.\\n        result = await backend.test_connection()\\n        assert result.ok is False\\n        # Either ConfigError (mapped from ValueError) or the type of the\\n        # failure raised inside variable_service \u2014 both are acceptable\\n        # so long as ``ok`` is False and there is a user-readable message.\\n        assert result.message\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/knowledge_bases/test_vector_store_backends.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a96e12be9ee6209d644c8a0878df16636f4d7fd82abf352629c0c7ca042e6ef\",\"content\":\"\\\"\\\"\\\"Stub-state tests for the disabled DB-connector backends.\\n\\nThe Astra / MongoDB backends ship as stubs in this phase (see each module's\\ndocstring under ``lfx.base.knowledge_bases.backends``). Postgres (pgvector) is\\nnow a real, registered backend and is covered by ``test_postgres_backend.py``.\\nThese tests pin the \\\"intentionally disabled\\\" contract so accidental\\nre-registration or silent re-introduction of partial implementations fails\\nloudly:\\n\\n* the classes still import (preserves enum + type compatibility),\\n* the registry does NOT bind them (``create_backend('astra')`` raises),\\n* directly instantiated stubs raise ``NotImplementedError`` from\\n  ``_build_vector_store`` instead of half-working.\\n\\nWhen a backend is re-enabled, restore its real test module alongside\\nthe implementation.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.base.knowledge_bases.backends import (\\n    AstraBackend,\\n    BackendType,\\n    MongoDBBackend,\\n    create_backend,\\n    registered_backends,\\n)\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n_STUBBED_BACKENDS = (\\n    (BackendType.ASTRA, AstraBackend),\\n    (BackendType.MONGODB, MongoDBBackend),\\n)\\n\\n\\nclass TestStubbedBackendsNotRegistered:\\n    \\\"\\\"\\\"Stubbed backends are intentionally absent from ``registered_backends()``.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"backend_type\\\", \\\"_backend_class\\\"),\\n        _STUBBED_BACKENDS,\\n        ids=lambda v: v.value if isinstance(v, BackendType) else \\\"cls\\\",\\n    )\\n    def test_not_in_registry(self, backend_type, _backend_class):\\n        assert backend_type not in registered_backends()\\n\\n    @pytest.mark.parametrize(\\n        (\\\"backend_type\\\", \\\"_backend_class\\\"),\\n        _STUBBED_BACKENDS,\\n        ids=lambda v: v.value if isinstance(v, BackendType) else \\\"cls\\\",\\n    )\\n    def test_create_backend_raises(self, backend_type, _backend_class, tmp_path: Path):\\n        with pytest.raises(ValueError, match=\\\"not registered\\\"):\\n            create_backend(backend_type, kb_name=\\\"kb\\\", kb_path=tmp_path)\\n\\n\\nclass TestStubbedBackendDirectInstantiation:\\n    \\\"\\\"\\\"Bypassing the registry still surfaces a clear ``NotImplementedError``.\\n\\n    These guards matter because some legacy call sites historically\\n    constructed backends directly. With the implementation gutted, the\\n    stub must fail loudly rather than e.g. silently returning ``None``.\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"_backend_type\\\", \\\"backend_class\\\"),\\n        _STUBBED_BACKENDS,\\n        ids=lambda v: v.value if isinstance(v, BackendType) else v.__name__,\\n    )\\n    def test_build_vector_store_raises(self, _backend_type, backend_class, tmp_path: Path):\\n        backend = backend_class(kb_name=\\\"kb\\\", kb_path=tmp_path, backend_config={})\\n        with pytest.raises(NotImplementedError, match=\\\"not available in this build\\\"):\\n            backend._build_vector_store()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/tools/test_run_flow.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6604bee5069461c453613675b1431592de33ad4f3ddf2f92dcf6e3f777d8dcf6\",\"content\":\"from contextlib import asynccontextmanager\\nfrom unittest.mock import AsyncMock, MagicMock, Mock, PropertyMock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom lfx.base.tools.run_flow import RunFlowBaseComponent\\nfrom lfx.exceptions.tweaks import TweakRefusedError\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.graph.vertex.base import Vertex\\nfrom lfx.interface.components import component_cache\\nfrom lfx.processing.process import process_tweaks_on_graph\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\nfrom lfx.services.cache.utils import CacheMiss\\nfrom lfx.template.field.base import Output\\nfrom lfx.utils.flow_validation import CustomComponentValidationError\\n\\n\\n@asynccontextmanager\\nasync def _authorized_target_scope(**_kwargs):\\n    \\\"\\\"\\\"Unit-test seam; target-scope behavior has dedicated DB-backed coverage.\\\"\\\"\\\"\\n    yield\\n\\n\\n@pytest.fixture\\ndef mock_shared_cache():\\n    \\\"\\\"\\\"Mock the shared component cache service.\\\"\\\"\\\"\\n    with patch(\\\"lfx.base.tools.run_flow.get_shared_component_cache_service\\\") as mock_get_cache:\\n        mock_cache = MagicMock()\\n        mock_cache.get = AsyncMock()\\n        mock_cache.set = AsyncMock()\\n        mock_cache.delete = AsyncMock()\\n        mock_get_cache.return_value = mock_cache\\n        yield mock_cache\\n\\n\\nclass TestRunFlowBaseComponentInitialization:\\n    \\\"\\\"\\\"Test RunFlowBaseComponent initialization.\\\"\\\"\\\"\\n\\n    def test_init_creates_cache_service(self):\\n        \\\"\\\"\\\"Test that __init__ creates the shared component cache service.\\\"\\\"\\\"\\n        with patch(\\\"lfx.base.tools.run_flow.get_shared_component_cache_service\\\") as mock_get_cache:\\n            mock_cache = MagicMock()\\n            mock_get_cache.return_value = mock_cache\\n\\n            component = RunFlowBaseComponent()\\n\\n            assert hasattr(component, \\\"_shared_component_cache\\\")\\n            assert component._shared_component_cache is not None\\n            assert component._shared_component_cache == mock_cache\\n\\n    def test_init_creates_cache_dispatcher(self):\\n        \\\"\\\"\\\"Test that __init__ creates the cache flow dispatcher.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        assert hasattr(component, \\\"_cache_flow_dispatcher\\\")\\n        assert isinstance(component._cache_flow_dispatcher, dict)\\n        assert \\\"get\\\" in component._cache_flow_dispatcher\\n        assert \\\"set\\\" in component._cache_flow_dispatcher\\n        assert \\\"delete\\\" in component._cache_flow_dispatcher\\n        assert \\\"_build_key\\\" in component._cache_flow_dispatcher\\n        assert \\\"_build_graph\\\" in component._cache_flow_dispatcher\\n\\n    def test_init_sets_last_run_outputs_to_none(self):\\n        \\\"\\\"\\\"Test that __init__ sets _last_run_outputs to None.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        assert hasattr(component, \\\"_last_run_outputs\\\")\\n        assert component._last_run_outputs is None\\n\\n    def test_init_sets_add_tool_output_flag(self):\\n        \\\"\\\"\\\"Test that __init__ sets add_tool_output to True.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        assert component.add_tool_output is True\\n\\n\\nclass TestRunFlowBaseComponentFlowRetrieval:\\n    \\\"\\\"\\\"Test flow retrieval methods.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def _target_scope(self):\\n        with patch(\\n            \\\"lfx.base.tools.run_flow.scoped_model_provider_policy_for_target_flow\\\",\\n            _authorized_target_scope,\\n        ):\\n            yield\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_with_id(self):\\n        \\\"\\\"\\\"Test getting a flow by ID.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n        expected_flow = Data(data={\\\"name\\\": \\\"test_flow\\\"})\\n\\n        with patch(\\\"lfx.base.tools.run_flow.get_flow_by_id_or_name\\\", new_callable=AsyncMock) as mock_get:\\n            mock_get.return_value = expected_flow\\n\\n            result = await component.get_flow(flow_id_selected=flow_id)\\n\\n            assert result == expected_flow\\n            mock_get.assert_called_once_with(\\n                user_id=component._user_id,\\n                flow_id=flow_id,\\n                flow_name=None,\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_with_name(self):\\n        \\\"\\\"\\\"Test getting a flow by name.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        flow_name = \\\"test_flow\\\"\\n        expected_flow = Data(data={\\\"name\\\": flow_name})\\n\\n        with patch(\\\"lfx.base.tools.run_flow.get_flow_by_id_or_name\\\", new_callable=AsyncMock) as mock_get:\\n            mock_get.return_value = expected_flow\\n\\n            result = await component.get_flow(flow_name_selected=flow_name)\\n\\n            assert result == expected_flow\\n            mock_get.assert_called_once_with(\\n                user_id=component._user_id,\\n                flow_id=None,\\n                flow_name=flow_name,\\n            )\\n\\n    @pytest.mark.asyncio\\n    async def test_get_flow_returns_empty_data_when_none(self):\\n        \\\"\\\"\\\"Test that get_flow returns empty Data when flow is not found.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n\\n        with patch(\\\"lfx.base.tools.run_flow.get_flow_by_id_or_name\\\", new_callable=AsyncMock) as mock_get:\\n            mock_get.return_value = None\\n\\n            result = await component.get_flow(flow_id_selected=str(uuid4()))\\n\\n            assert isinstance(result, Data)\\n            assert result.data == {}\\n\\n    @pytest.mark.asyncio\\n    async def test_get_graph_raises_error_without_id_or_name(self):\\n        \\\"\\\"\\\"Test that get_graph raises ValueError when neither ID nor name is provided.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Flow name or id is required\\\"):\\n            await component.get_graph()\\n\\n    @pytest.mark.asyncio\\n    async def test_get_graph_uses_cache_when_available_and_up_to_date(self):\\n        \\\"\\\"\\\"Test that get_graph returns cached graph when available and up-to-date.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = True\\n        flow_id = str(uuid4())\\n        updated_at = \\\"2024-01-01T00:00:00Z\\\"\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.flow_id = flow_id\\n        mock_graph.updated_at = updated_at\\n\\n        with (\\n            patch.object(component, \\\"_flow_cache_call\\\") as mock_cache_call,\\n            patch.object(component, \\\"_is_cached_flow_up_to_date\\\") as mock_is_up_to_date,\\n        ):\\n            mock_cache_call.return_value = mock_graph\\n            mock_is_up_to_date.return_value = True\\n\\n            result = await component.get_graph(flow_id_selected=flow_id, updated_at=updated_at)\\n\\n            assert result == mock_graph\\n            mock_cache_call.assert_called_once_with(\\\"get\\\", flow_id=flow_id)\\n            mock_is_up_to_date.assert_called_once_with(mock_graph, updated_at)\\n\\n    @pytest.mark.asyncio\\n    async def test_get_graph_fetches_and_caches_when_not_cached(self):\\n        \\\"\\\"\\\"Test that get_graph fetches flow and caches it when not in cache.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = True\\n        flow_name = \\\"test_flow\\\"\\n        flow_id = str(uuid4())\\n\\n        flow_data = Data(data={\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"description\\\": \\\"Test flow\\\"})\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = []\\n\\n        with (\\n            patch.object(component, \\\"_flow_cache_call\\\") as mock_cache_call,\\n            patch.object(component, \\\"get_flow\\\", new_callable=AsyncMock) as mock_get_flow,\\n            patch(\\\"lfx.base.tools.run_flow.Graph.from_payload\\\") as mock_from_payload,\\n        ):\\n            mock_cache_call.return_value = None  # Not in cache\\n            mock_get_flow.return_value = flow_data\\n            mock_from_payload.return_value = mock_graph\\n\\n            result = await component.get_graph(flow_name_selected=flow_name, flow_id_selected=flow_id)\\n\\n            assert result == mock_graph\\n            mock_get_flow.assert_called_once_with(flow_name_selected=flow_name, flow_id_selected=flow_id)\\n            mock_from_payload.assert_called_once()\\n            # Verify cache set was called\\n            assert mock_cache_call.call_count == 2  # get and set\\n\\n    @pytest.mark.asyncio\\n    async def test_get_graph_deletes_stale_cache_and_refetches(self):\\n        \\\"\\\"\\\"Test that get_graph deletes stale cached graph and fetches fresh one.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = True\\n        flow_id = str(uuid4())\\n        old_updated_at = \\\"2024-01-01T00:00:00Z\\\"\\n        new_updated_at = \\\"2024-01-02T00:00:00Z\\\"\\n\\n        stale_graph = MagicMock(spec=Graph)\\n        stale_graph.flow_id = flow_id\\n        stale_graph.updated_at = old_updated_at\\n\\n        flow_data = Data(\\n            data={\\\"data\\\": {\\\"nodes\\\": [], \\\"edges\\\": []}, \\\"description\\\": \\\"Test flow\\\", \\\"updated_at\\\": new_updated_at}\\n        )\\n\\n        fresh_graph = MagicMock(spec=Graph)\\n        fresh_graph.updated_at = new_updated_at\\n        fresh_graph.vertices = []\\n\\n        with (\\n            patch.object(component, \\\"_flow_cache_call\\\") as mock_cache_call,\\n            patch.object(component, \\\"_is_cached_flow_up_to_date\\\") as mock_is_up_to_date,\\n            patch.object(component, \\\"get_flow\\\", new_callable=AsyncMock) as mock_get_flow,\\n            patch(\\\"lfx.base.tools.run_flow.Graph.from_payload\\\") as mock_from_payload,\\n        ):\\n            # First call returns stale graph, second call is delete, third call is set\\n            mock_cache_call.side_effect = [stale_graph, None, None]\\n            mock_is_up_to_date.return_value = False  # Cache is stale\\n            mock_get_flow.return_value = flow_data\\n            mock_from_payload.return_value = fresh_graph\\n\\n            result = await component.get_graph(flow_id_selected=flow_id, updated_at=new_updated_at)\\n\\n            assert result == fresh_graph\\n            # Should have called cache \\\"get\\\", \\\"delete\\\", and \\\"set\\\"\\n            assert mock_cache_call.call_count == 3\\n\\n    @pytest.mark.asyncio\\n    async def test_get_graph_blocks_custom_components_when_disabled(self, monkeypatch):\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = False\\n        blocked_flow = Data(\\n            data={\\n                \\\"data\\\": {\\n                    \\\"nodes\\\": [\\n                        {\\n                            \\\"id\\\": \\\"node-1\\\",\\n                            \\\"data\\\": {\\n                                \\\"id\\\": \\\"node-1\\\",\\n                                \\\"type\\\": \\\"TotallyCustom\\\",\\n                                \\\"node\\\": {\\n                                    \\\"display_name\\\": \\\"Blocked Node\\\",\\n                                    \\\"template\\\": {\\n                                        \\\"code\\\": {\\\"value\\\": \\\"print('blocked')\\\"},\\n                                    },\\n                                },\\n                            },\\n                        }\\n                    ],\\n                    \\\"edges\\\": [],\\n                },\\n                \\\"description\\\": \\\"Blocked flow\\\",\\n            }\\n        )\\n\\n        monkeypatch.setattr(\\n            \\\"lfx.services.deps.get_settings_service\\\",\\n            lambda: MagicMock(settings=MagicMock(allow_custom_components=False)),\\n        )\\n        monkeypatch.setattr(component_cache, \\\"type_to_current_hash\\\", {\\\"ChatInput\\\": \\\"known-hash\\\"})\\n        monkeypatch.setattr(component_cache, \\\"all_types_dict\\\", None)\\n\\n        with patch.object(component, \\\"get_flow\\\", new_callable=AsyncMock) as mock_get_flow:\\n            mock_get_flow.return_value = blocked_flow\\n            with pytest.raises(CustomComponentValidationError, match=\\\"custom components are not allowed\\\"):\\n                await component.get_graph(flow_name_selected=\\\"blocked-flow\\\", flow_id_selected=str(uuid4()))\\n\\n\\nclass TestRunFlowBaseComponentFlowCaching:\\n    \\\"\\\"\\\"Test flow caching methods.\\\"\\\"\\\"\\n\\n    def test_build_flow_cache_key_with_flow_id(self):\\n        \\\"\\\"\\\"Test building cache key with flow ID.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        flow_id = str(uuid4())\\n\\n        key = component._build_flow_cache_key(flow_id=flow_id)\\n\\n        assert f\\\"run_flow:{component._user_id}:{flow_id}\\\" == key\\n\\n    @patch.object(RunFlowBaseComponent, \\\"user_id\\\", new_callable=PropertyMock, return_value=None)\\n    def test_build_flow_cache_key_without_user_id_raises_error(self, mock_user_id):  # noqa: ARG002\\n        \\\"\\\"\\\"Test that building cache key without user_id raises ValueError.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Flow ID and user ID are required\\\"):\\n            component._build_flow_cache_key(flow_id=str(uuid4()))\\n\\n    def test_build_flow_cache_key_without_flow_id_raises_error(self):\\n        \\\"\\\"\\\"Test that building cache key without flow_id raises ValueError.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n\\n        with pytest.raises(ValueError, match=\\\"Flow ID and user ID are required\\\"):\\n            component._build_flow_cache_key(flow_id=None)\\n\\n    def test_flow_cache_call_returns_none_when_cache_disabled(self):\\n        \\\"\\\"\\\"Test that _flow_cache_call returns None when cache_flow is False.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component.cache_flow = False\\n\\n        result = component._flow_cache_call(\\\"get\\\", flow_name=\\\"test\\\")\\n\\n        assert result is None\\n\\n    def test_flow_cache_call_returns_none_when_cache_service_unavailable(self):\\n        \\\"\\\"\\\"Test that _flow_cache_call returns None when cache service is None.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component.cache_flow = True\\n        component._shared_component_cache = None\\n\\n        result = component._flow_cache_call(\\\"get\\\", flow_name=\\\"test\\\")\\n\\n        assert result is None\\n\\n    def test_flow_cache_call_raises_error_for_unknown_action(self):\\n        \\\"\\\"\\\"Test that _flow_cache_call raises ValueError for unknown action.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component.cache_flow = True\\n\\n        with pytest.raises(ValueError, match=\\\"Unknown cache action\\\"):\\n            component._flow_cache_call(\\\"invalid_action\\\")\\n\\n    def test_get_cached_flow_returns_none_on_cache_miss(self):\\n        \\\"\\\"\\\"Test that _get_cached_flow returns None on cache miss.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = True\\n        flow_id = str(uuid4())\\n\\n        mock_cache_miss = MagicMock(spec=CacheMiss)\\n        component._shared_component_cache = MagicMock()\\n        component._shared_component_cache.get = Mock(return_value=mock_cache_miss)\\n\\n        with patch.object(component, \\\"_build_flow_cache_key\\\") as mock_build_key:\\n            mock_build_key.return_value = \\\"test_key\\\"\\n\\n            result = component._get_cached_flow(flow_id=flow_id)\\n\\n            assert result is None\\n\\n    def test_set_cached_flow_stores_graph_data(self):\\n        \\\"\\\"\\\"Test that _set_cached_flow stores graph data in cache.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.cache_flow = True\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.flow_name = \\\"test_flow\\\"\\n        mock_graph.flow_id = str(uuid4())\\n        mock_graph.description = \\\"Test description\\\"\\n        mock_graph.updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n        mock_graph.dump = Mock(return_value={\\\"name\\\": \\\"test_flow\\\"})\\n\\n        component._shared_component_cache = MagicMock()\\n        component._shared_component_cache.set = Mock()\\n\\n        with patch.object(component, \\\"_build_flow_cache_key\\\") as mock_build_key:\\n            mock_build_key.return_value = \\\"test_key\\\"\\n\\n            component._set_cached_flow(flow=mock_graph)\\n\\n            component._shared_component_cache.set.assert_called_once()\\n            args = component._shared_component_cache.set.call_args[0]\\n            assert args[0] == \\\"test_key\\\"\\n            assert \\\"graph_dump\\\" in args[1]\\n            assert \\\"flow_id\\\" in args[1]\\n            assert \\\"user_id\\\" in args[1]\\n\\n    def test_is_cached_flow_up_to_date_returns_true_for_same_timestamp(self):\\n        \\\"\\\"\\\"Test that cached flow is considered up-to-date with same timestamp.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        cached_graph = MagicMock(spec=Graph)\\n        cached_graph.updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        result = component._is_cached_flow_up_to_date(cached_graph, updated_at)\\n\\n        assert result is True\\n\\n    def test_is_cached_flow_up_to_date_returns_true_for_newer_cache(self):\\n        \\\"\\\"\\\"Test that cached flow is considered up-to-date when cache is newer.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        cached_graph = MagicMock(spec=Graph)\\n        cached_graph.updated_at = \\\"2024-01-02T12:00:00Z\\\"\\n\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        result = component._is_cached_flow_up_to_date(cached_graph, updated_at)\\n\\n        assert result is True\\n\\n    def test_is_cached_flow_up_to_date_returns_false_for_older_cache(self):\\n        \\\"\\\"\\\"Test that cached flow is considered stale when cache is older.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        cached_graph = MagicMock(spec=Graph)\\n        cached_graph.updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        updated_at = \\\"2024-01-02T12:00:00Z\\\"\\n\\n        result = component._is_cached_flow_up_to_date(cached_graph, updated_at)\\n\\n        assert result is False\\n\\n    def test_is_cached_flow_up_to_date_returns_false_when_updated_at_missing(self):\\n        \\\"\\\"\\\"Test that cached flow is considered stale when updated_at is None.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        cached_graph = MagicMock(spec=Graph)\\n        cached_graph.updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        result = component._is_cached_flow_up_to_date(cached_graph, None)\\n\\n        assert result is False\\n\\n    def test_is_cached_flow_up_to_date_returns_false_when_cached_timestamp_missing(self):\\n        \\\"\\\"\\\"Test that cached flow is considered stale when cached updated_at is None.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        cached_graph = MagicMock(spec=Graph)\\n        cached_graph.updated_at = None\\n\\n        updated_at = \\\"2024-01-01T12:00:00Z\\\"\\n\\n        result = component._is_cached_flow_up_to_date(cached_graph, updated_at)\\n\\n        assert result is False\\n\\n    def test_parse_timestamp_parses_iso_format(self):\\n        \\\"\\\"\\\"Test parsing ISO format timestamp.\\\"\\\"\\\"\\n        timestamp_str = \\\"2024-01-01T12:34:56Z\\\"\\n\\n        result = RunFlowBaseComponent._parse_timestamp(timestamp_str)\\n\\n        assert result is not None\\n        assert result.year == 2024\\n        assert result.month == 1\\n        assert result.day == 1\\n        assert result.hour == 12\\n        assert result.minute == 34\\n        assert result.second == 56\\n        assert result.microsecond == 0  # Should normalize microseconds\\n\\n    def test_parse_timestamp_parses_iso_with_offset(self):\\n        \\\"\\\"\\\"Test parsing ISO format timestamp with timezone offset.\\\"\\\"\\\"\\n        timestamp_str = \\\"2024-01-01T12:34:56+05:00\\\"\\n\\n        result = RunFlowBaseComponent._parse_timestamp(timestamp_str)\\n\\n        assert result is not None\\n        assert result.year == 2024\\n\\n    def test_parse_timestamp_returns_none_for_none(self):\\n        \\\"\\\"\\\"Test that None input returns None.\\\"\\\"\\\"\\n        result = RunFlowBaseComponent._parse_timestamp(None)\\n\\n        assert result is None\\n\\n    def test_parse_timestamp_returns_none_for_invalid_format(self):\\n        \\\"\\\"\\\"Test that invalid timestamp format returns None.\\\"\\\"\\\"\\n        result = RunFlowBaseComponent._parse_timestamp(\\\"invalid-timestamp\\\")\\n\\n        assert result is None\\n\\n\\nclass TestRunFlowBaseComponentInputOutputHandling:\\n    \\\"\\\"\\\"Test input/output handling methods.\\\"\\\"\\\"\\n\\n    def test_get_ioput_name_creates_unique_name(self):\\n        \\\"\\\"\\\"Test that _get_ioput_name creates unique input/output name.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        vertex_id = \\\"vertex_123\\\"\\n        ioput_name = \\\"input_1\\\"\\n\\n        result = component._get_ioput_name(vertex_id, ioput_name)\\n\\n        assert result == f\\\"{vertex_id}{component.IOPUT_SEP}{ioput_name}\\\"\\n\\n    def test_get_ioput_name_raises_error_without_vertex_id(self):\\n        \\\"\\\"\\\"Test that _get_ioput_name raises ValueError without vertex_id.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Vertex ID and input/output name are required\\\"):\\n            component._get_ioput_name(\\\"\\\", \\\"input_1\\\")\\n\\n    def test_get_ioput_name_raises_error_without_ioput_name(self):\\n        \\\"\\\"\\\"Test that _get_ioput_name raises ValueError without ioput_name.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Vertex ID and input/output name are required\\\"):\\n            component._get_ioput_name(\\\"vertex_123\\\", \\\"\\\")\\n\\n    def test_extract_ioputs_from_keyed_values(self):\\n        \\\"\\\"\\\"Test extracting ioputs from keyed values.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        values = {\\n            \\\"vertex1~param1\\\": \\\"value1\\\",\\n            \\\"vertex1~param2\\\": \\\"value2\\\",\\n            \\\"vertex2~param1\\\": \\\"value3\\\",\\n            \\\"invalid_key\\\": \\\"should_be_ignored\\\",\\n        }\\n\\n        ioputs = component._extract_ioputs_from_keyed_values(values)\\n\\n        assert \\\"vertex1\\\" in ioputs\\n        assert ioputs[\\\"vertex1\\\"][\\\"param1\\\"] == \\\"value1\\\"\\n        assert ioputs[\\\"vertex1\\\"][\\\"param2\\\"] == \\\"value2\\\"\\n        assert \\\"vertex2\\\" in ioputs\\n        assert ioputs[\\\"vertex2\\\"][\\\"param1\\\"] == \\\"value3\\\"\\n        assert \\\"invalid_key\\\" not in ioputs\\n\\n    def test_build_inputs_from_ioputs(self):\\n        \\\"\\\"\\\"Test building inputs from ioputs.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        ioputs = {\\n            \\\"vertex1\\\": {\\\"input_value\\\": \\\"test_input\\\", \\\"type\\\": \\\"chat\\\"},\\n            \\\"vertex2\\\": {\\\"input_value\\\": \\\"another_input\\\"},\\n            \\\"vertex3\\\": {\\\"other_param\\\": \\\"value\\\"},  # Should be skipped\\n        }\\n\\n        inputs = component._build_inputs_from_ioputs(ioputs)\\n\\n        assert len(inputs) == 2\\n        assert inputs[0][\\\"components\\\"] == [\\\"vertex1\\\"]\\n        assert inputs[0][\\\"input_value\\\"] == \\\"test_input\\\"\\n        assert inputs[0][\\\"type\\\"] == \\\"chat\\\"\\n        assert inputs[1][\\\"components\\\"] == [\\\"vertex2\\\"]\\n        assert inputs[1][\\\"input_value\\\"] == \\\"another_input\\\"\\n\\n    def test_build_inputs_from_ioputs_handles_data_object(self):\\n        \\\"\\\"\\\"Test that _build_inputs_from_ioputs handles Data objects in input_value.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        data_obj = MagicMock(spec=Data)\\n        data_obj.get_text.return_value = \\\"extracted_text\\\"\\n\\n        ioputs = {\\\"vertex1\\\": {\\\"input_value\\\": data_obj}}\\n\\n        inputs = component._build_inputs_from_ioputs(ioputs)\\n\\n        assert len(inputs) == 1\\n        assert inputs[0][\\\"input_value\\\"] == \\\"extracted_text\\\"\\n        data_obj.get_text.assert_called_once()\\n\\n    def test_format_flow_outputs_creates_output_objects(self):\\n        \\\"\\\"\\\"Test that _format_flow_outputs creates Output objects from graph.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        mock_vertex = MagicMock()\\n        mock_vertex.id = \\\"vertex_123\\\"\\n        mock_vertex.is_output = True\\n        mock_vertex.outputs = [\\n            {\\\"name\\\": \\\"output1\\\", \\\"display_name\\\": \\\"Output 1\\\"},\\n            {\\\"name\\\": \\\"output2\\\", \\\"display_name\\\": \\\"Output 2\\\"},\\n        ]\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = [mock_vertex]\\n        mock_graph.successor_map = {}\\n\\n        outputs = component._format_flow_outputs(mock_graph)\\n\\n        assert len(outputs) == 2\\n        assert all(isinstance(output, Output) for output in outputs)\\n        assert outputs[0].name == f\\\"vertex_123{component.IOPUT_SEP}output1\\\"\\n        # The method name is dynamically generated with sanitized vertex and output names\\n        assert outputs[0].method == \\\"_resolve_flow_output__vertex_123__output1\\\"\\n        assert outputs[1].name == f\\\"vertex_123{component.IOPUT_SEP}output2\\\"\\n        assert outputs[1].method == \\\"_resolve_flow_output__vertex_123__output2\\\"\\n\\n    def test_format_flow_outputs_skips_vertices_with_successors(self):\\n        \\\"\\\"\\\"Test that _format_flow_outputs skips vertices with outgoing edges.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        mock_vertex = MagicMock()\\n        mock_vertex.id = \\\"vertex_123\\\"\\n        mock_vertex.is_output = True\\n        mock_vertex.outputs = [{\\\"name\\\": \\\"output1\\\"}]\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.vertices = [mock_vertex]\\n        # Simulate successor map with outgoing edge\\n        mock_graph.successor_map = {\\\"vertex_123\\\": [\\\"some_other_vertex\\\"]}\\n\\n        outputs = component._format_flow_outputs(mock_graph)\\n\\n        assert len(outputs) == 0\\n\\n    def test_delete_fields_with_list(self):\\n        \\\"\\\"\\\"Test deleting fields from build_config with list.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\", \\\"field3\\\": \\\"value3\\\"})\\n\\n        component.delete_fields(build_config, [\\\"field1\\\", \\\"field3\\\"])\\n\\n        assert \\\"field1\\\" not in build_config\\n        assert \\\"field2\\\" in build_config\\n        assert \\\"field3\\\" not in build_config\\n\\n    def test_delete_fields_with_dict(self):\\n        \\\"\\\"\\\"Test deleting fields from build_config with dict.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        build_config = dotdict({\\\"field1\\\": \\\"value1\\\", \\\"field2\\\": \\\"value2\\\"})\\n\\n        component.delete_fields(build_config, {\\\"field1\\\": {}, \\\"field2\\\": {}})\\n\\n        assert \\\"field1\\\" not in build_config\\n        assert \\\"field2\\\" not in build_config\\n\\n    def test_update_input_types_sets_empty_list_for_none(self):\\n        \\\"\\\"\\\"Test that update_input_types sets empty list for None or missing input_types.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        fields = [\\n            dotdict({\\\"name\\\": \\\"field1\\\", \\\"input_types\\\": None}),\\n            dotdict({\\\"name\\\": \\\"field2\\\", \\\"input_types\\\": [\\\"str\\\"]}),\\n            dotdict({\\\"name\\\": \\\"field3\\\"}),  # No input_types key\\n        ]\\n\\n        updated = component.update_input_types(fields)\\n\\n        assert updated[0][\\\"input_types\\\"] == []\\n        assert updated[1][\\\"input_types\\\"] == [\\\"str\\\"]\\n        assert updated[2][\\\"input_types\\\"] == []  # Should be added as empty list\\n\\n    def test_resolve_exposed_input_types_restores_message_for_empty_text_field(self):\\n        \\\"\\\"\\\"Empty input_types on a text field should be restored to [\\\"Message\\\"].\\\"\\\"\\\"\\n        entry = {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": []}\\n\\n        assert RunFlowBaseComponent._resolve_exposed_input_types(entry) == [\\\"Message\\\"]\\n\\n    def test_resolve_exposed_input_types_restores_message_when_missing(self):\\n        \\\"\\\"\\\"Missing input_types on a text field should default to [\\\"Message\\\"].\\\"\\\"\\\"\\n        entry = {\\\"type\\\": \\\"Text\\\"}\\n\\n        assert RunFlowBaseComponent._resolve_exposed_input_types(entry) == [\\\"Message\\\"]\\n\\n    def test_resolve_exposed_input_types_preserves_existing_input_types(self):\\n        \\\"\\\"\\\"Existing input_types must be preserved without modification.\\\"\\\"\\\"\\n        entry = {\\\"type\\\": \\\"str\\\", \\\"input_types\\\": [\\\"Message\\\", \\\"Data\\\"]}\\n\\n        result = RunFlowBaseComponent._resolve_exposed_input_types(entry)\\n\\n        assert result == [\\\"Message\\\", \\\"Data\\\"]\\n        # Returns a copy, not the original list, to avoid accidental shared mutation.\\n        assert result is not entry[\\\"input_types\\\"]\\n\\n    def test_resolve_exposed_input_types_skips_non_text_fields(self):\\n        \\\"\\\"\\\"Non-text fields with empty input_types are left untouched.\\\"\\\"\\\"\\n        entry = {\\\"type\\\": \\\"bool\\\", \\\"input_types\\\": []}\\n\\n        assert RunFlowBaseComponent._resolve_exposed_input_types(entry) == []\\n\\n    def test_get_new_fields_exposes_message_handle_for_chat_input_value(self):\\n        \\\"\\\"\\\"Run Flow must expose a Message handle for ChatInput-style input_value fields.\\n\\n        Regression test for LE-1233: ChatInput sets input_types=[] on its input_value,\\n        which previously propagated to the Run Flow dynamic field and prevented users\\n        from wiring upstream components into the exposed Input Text field.\\n        \\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        chat_input_vertex = MagicMock(spec=Vertex)\\n        chat_input_vertex.id = \\\"ChatInput-abcde\\\"\\n        chat_input_vertex.display_name = \\\"Chat Input\\\"\\n        chat_input_vertex.data = {\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\n                    \\\"input_value\\\": {\\n                        \\\"name\\\": \\\"input_value\\\",\\n                        \\\"display_name\\\": \\\"Input Text\\\",\\n                        \\\"type\\\": \\\"str\\\",\\n                        \\\"input_types\\\": [],\\n                        \\\"advanced\\\": False,\\n                    },\\n                    \\\"should_store_message\\\": {\\n                        \\\"name\\\": \\\"should_store_message\\\",\\n                        \\\"display_name\\\": \\\"Store Messages\\\",\\n                        \\\"type\\\": \\\"bool\\\",\\n                        \\\"input_types\\\": [],\\n                        \\\"advanced\\\": True,\\n                    },\\n                },\\n                \\\"field_order\\\": [\\\"input_value\\\", \\\"should_store_message\\\"],\\n            }\\n        }\\n\\n        new_fields = component.get_new_fields([chat_input_vertex])\\n\\n        input_value_field = next(f for f in new_fields if f[\\\"name\\\"].endswith(\\\"~input_value\\\"))\\n        bool_field = next(f for f in new_fields if f[\\\"name\\\"].endswith(\\\"~should_store_message\\\"))\\n\\n        assert input_value_field[\\\"input_types\\\"] == [\\\"Message\\\"], (\\n            \\\"Text-typed exposed inputs must receive a Message handle so upstream components can be wired in (LE-1233).\\\"\\n        )\\n        # Bool fields don't expose a Message handle \u2014 handle visibility is driven by `type`.\\n        assert bool_field[\\\"input_types\\\"] == []\\n\\n\\nclass TestRunFlowBaseComponentOutputMethods:\\n    \\\"\\\"\\\"Test output methods.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_resolve_flow_output_finds_correct_output(self):\\n        \\\"\\\"\\\"Test that _resolve_flow_output finds the correct output.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.session_id = None\\n        component.flow_tweak_data = {}\\n\\n        vertex_id = \\\"vertex_123\\\"\\n        output_name = \\\"output1\\\"\\n        expected_value = \\\"test_value\\\"\\n\\n        mock_result = MagicMock()\\n        mock_result.component_id = vertex_id\\n        mock_result.results = {output_name: expected_value}\\n\\n        mock_run_output = MagicMock()\\n        mock_run_output.outputs = [mock_result]\\n\\n        with patch.object(component, \\\"_get_cached_run_outputs\\\", new_callable=AsyncMock) as mock_get:\\n            mock_get.return_value = [mock_run_output]\\n\\n            result = await component._resolve_flow_output(vertex_id=vertex_id, output_name=output_name)\\n\\n            assert result == expected_value\\n\\n\\nclass TestRunFlowBaseComponentToolGeneration:\\n    \\\"\\\"\\\"Test tool generation methods.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_required_data_returns_description_and_fields(self):\\n        \\\"\\\"\\\"Test that get_required_data returns flow description and tool-mode fields.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        component._user_id = str(uuid4())\\n        component.flow_name_selected = \\\"test_flow\\\"\\n        component.flow_id_selected = str(uuid4())\\n\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_graph.description = \\\"Test flow description\\\"\\n        mock_graph.successor_map = {}\\n\\n        mock_vertex = MagicMock()\\n        mock_vertex.id = \\\"vertex_1\\\"\\n        mock_vertex.data = {\\n            \\\"node\\\": {\\n                \\\"template\\\": {\\n                    \\\"input1\\\": {\\\"name\\\": \\\"input1\\\", \\\"display_name\\\": \\\"Input 1\\\", \\\"advanced\\\": False},\\n                },\\n                \\\"field_order\\\": [\\\"input1\\\"],\\n            }\\n        }\\n        mock_graph.vertices = [mock_vertex]\\n\\n        with patch.object(component, \\\"get_graph\\\", new_callable=AsyncMock) as mock_get_graph:\\n            mock_get_graph.return_value = mock_graph\\n\\n            with patch.object(component, \\\"get_new_fields_from_graph\\\") as mock_get_fields:\\n                mock_get_fields.return_value = [dotdict({\\\"name\\\": \\\"input1\\\", \\\"tool_mode\\\": True, \\\"input_types\\\": None})]\\n\\n                description, fields = await component.get_required_data()\\n\\n                assert description == \\\"Test flow description\\\"\\n                assert len(fields) == 1\\n                assert fields[0][\\\"name\\\"] == \\\"input1\\\"\\n\\n\\nclass TestRunFlowBaseComponentTweakData:\\n    \\\"\\\"\\\"Test tweak data building methods.\\\"\\\"\\\"\\n\\n    def test_build_flow_tweak_data_merges_tool_tweaks(self):\\n        \\\"\\\"\\\"Test that _build_flow_tweak_data merges tool tweaks correctly.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n\\n        # Base attributes\\n        component._attributes = {\\n            \\\"vertex1~param1\\\": \\\"value1\\\",\\n            \\\"vertex1~param2\\\": \\\"value2\\\",\\n            \\\"flow_tweak_data\\\": {\\n                \\\"vertex1~param1\\\": \\\"new_value1\\\",  # Should override\\n                \\\"vertex2~param3\\\": \\\"value3\\\",  # Should be added\\n            },\\n        }\\n\\n        tweak_data = component._build_flow_tweak_data()\\n\\n        assert \\\"vertex1\\\" in tweak_data\\n        assert tweak_data[\\\"vertex1\\\"][\\\"param1\\\"] == \\\"new_value1\\\"\\n        assert tweak_data[\\\"vertex1\\\"][\\\"param2\\\"] == \\\"value2\\\"\\n        assert \\\"vertex2\\\" in tweak_data\\n        assert tweak_data[\\\"vertex2\\\"][\\\"param3\\\"] == \\\"value3\\\"\\n\\n\\nclass TestRunFlowBaseComponentUpdateOutputs:\\n    \\\"\\\"\\\"Test update_outputs method.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_update_outputs_with_flow_name_selected(self):\\n        \\\"\\\"\\\"Test update_outputs when flow_name_selected is changed.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        frontend_node = {\\n            \\\"template\\\": {\\\"flow_name_selected\\\": {\\\"selected_metadata\\\": {\\\"id\\\": \\\"flow_id\\\", \\\"updated_at\\\": \\\"timestamp\\\"}}}\\n        }\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_output = MagicMock(spec=Output)\\n        mock_output.model_dump.return_value = {\\\"name\\\": \\\"output1\\\"}\\n\\n        with (\\n            patch.object(component, \\\"get_graph\\\", new_callable=AsyncMock) as mock_get_graph,\\n            patch.object(component, \\\"_format_flow_outputs\\\") as mock_format_outputs,\\n            patch.object(component, \\\"_sync_flow_outputs\\\") as mock_sync_outputs,\\n        ):\\n            mock_get_graph.return_value = mock_graph\\n            mock_format_outputs.return_value = [mock_output]\\n\\n            result = await component.update_outputs(frontend_node, \\\"flow_name_selected\\\", \\\"new_flow\\\")\\n\\n            assert result[\\\"outputs\\\"] == [{\\\"name\\\": \\\"output1\\\"}]\\n            mock_get_graph.assert_called_once()\\n            mock_format_outputs.assert_called_once_with(mock_graph)\\n            mock_sync_outputs.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_outputs_with_tool_mode_false(self):\\n        \\\"\\\"\\\"Test update_outputs when tool_mode is set to False.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        frontend_node = {\\n            \\\"template\\\": {\\n                \\\"flow_name_selected\\\": {\\n                    \\\"value\\\": \\\"test_flow\\\",\\n                    \\\"selected_metadata\\\": {\\\"id\\\": \\\"flow_id\\\", \\\"updated_at\\\": \\\"timestamp\\\"},\\n                }\\n            }\\n        }\\n        mock_graph = MagicMock(spec=Graph)\\n        mock_output = MagicMock(spec=Output)\\n        mock_output.model_dump.return_value = {\\\"name\\\": \\\"output1\\\"}\\n\\n        with (\\n            patch.object(component, \\\"get_graph\\\", new_callable=AsyncMock) as mock_get_graph,\\n            patch.object(component, \\\"_format_flow_outputs\\\") as mock_format_outputs,\\n            patch.object(component, \\\"_sync_flow_outputs\\\"),\\n        ):\\n            mock_get_graph.return_value = mock_graph\\n            mock_format_outputs.return_value = [mock_output]\\n\\n            result = await component.update_outputs(frontend_node, \\\"tool_mode\\\", field_value=False)\\n\\n            assert result[\\\"outputs\\\"] == [{\\\"name\\\": \\\"output1\\\"}]\\n            mock_get_graph.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_outputs_ignored_fields(self):\\n        \\\"\\\"\\\"Test update_outputs with fields that should be ignored.\\\"\\\"\\\"\\n        component = RunFlowBaseComponent()\\n        frontend_node = {}\\n\\n        result = await component.update_outputs(frontend_node, \\\"other_field\\\", \\\"value\\\")\\n\\n        assert result == frontend_node\\n\\n\\nclass TestRunFlowBaseComponentTweaks:\\n    \\\"\\\"\\\"Test tweak processing methods.\\\"\\\"\\\"\\n\\n    def _graph_with(self, *vertices):\\n        graph = MagicMock(spec=Graph)\\n        graph.vertices = list(vertices)\\n        return graph\\n\\n    def _vertex(self, vertex_id, template, node_type):\\n        vertex = MagicMock(spec=Vertex)\\n        vertex.id = vertex_id\\n        vertex.data = {\\\"type\\\": node_type, \\\"node\\\": {\\\"template\\\": template}}\\n        vertex.params = {}\\n        vertex.load_from_db_fields = []\\n        return vertex\\n\\n    def test_process_tweaks_on_graph_applies_declared_fields(self):\\n        \\\"\\\"\\\"An ordinary tweak reaches the vertex; unknown keys and ids are skipped.\\n\\n        The component no longer owns a private copy of this logic. It calls the\\n        shared helper so the graph path enforces the same floor as the sync path.\\n        \\\"\\\"\\\"\\n        vertex1 = self._vertex(\\\"vertex1\\\", {\\\"param\\\": {\\\"type\\\": \\\"str\\\"}}, \\\"TextInput\\\")\\n        vertex2 = self._vertex(\\\"vertex2\\\", {\\\"param\\\": {\\\"type\\\": \\\"str\\\"}}, \\\"TextInput\\\")\\n        graph = self._graph_with(vertex1, vertex2)\\n\\n        tweaks = {\\n            \\\"vertex1\\\": {\\\"param\\\": \\\"value\\\", \\\"undeclared\\\": \\\"ignored\\\"},\\n            \\\"vertex3\\\": {\\\"param\\\": \\\"ignored\\\"},  # Not in graph\\n        }\\n\\n        process_tweaks_on_graph(graph, tweaks)\\n\\n        vertex1.update_raw_params.assert_called_once()\\n        assert vertex1.update_raw_params.call_args[0][0] == {\\\"param\\\": \\\"value\\\"}\\n        vertex2.update_raw_params.assert_not_called()\\n\\n    def test_process_tweaks_on_graph_refuses_protected_fields(self):\\n        \\\"\\\"\\\"A protected field is refused, and the refusal applies nothing at all.\\n\\n        ``function_code`` on a code-execution component is sandbox-widening. The\\n        accepted sibling must not be written either: this graph is cached and\\n        reused, so a partial write would survive into later runs.\\n        \\\"\\\"\\\"\\n        vertex1 = self._vertex(\\n            \\\"vertex1\\\",\\n            {\\n                \\\"param\\\": {\\\"type\\\": \\\"str\\\"},\\n                \\\"code\\\": {\\\"type\\\": \\\"code\\\"},\\n                \\\"function_code\\\": {\\\"type\\\": \\\"str\\\"},\\n            },\\n            \\\"PythonFunction\\\",\\n        )\\n        graph = self._graph_with(vertex1)\\n\\n        tweaks = {\\n            \\\"vertex1\\\": {\\n                \\\"param\\\": \\\"value\\\",\\n                \\\"code\\\": \\\"ignored\\\",\\n                \\\"function_code\\\": \\\"def run():\\\\n    return __import__('os').system('id')\\\",\\n            }\\n        }\\n\\n        with pytest.raises(TweakRefusedError) as exc_info:\\n            process_tweaks_on_graph(graph, tweaks)\\n\\n        assert set(exc_info.value.refused) == {\\\"code\\\", \\\"function_code\\\"}\\n        vertex1.update_raw_params.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/tools/test_run_flow_error_surface.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e08d3ec3f81f5d011a8b53f909f7e53870a5aa44964e46447f2e00190fe77bdd\",\"content\":\"\\\"\\\"\\\"The Run Flow component must surface the nested-HITL rejection verbatim.\\n\\n``_run_flow_with_cached_graph`` wraps every failure as ``RuntimeError(\\\"Error running\\nflow: <name>\\\") from None`` \u2014 with a flow named \\\"HITL\\\" the user sees \\\"Error running\\nflow: HITL\\\" and the deliberate guard explanation (move the approval to the parent\\nflow) is swallowed. The guard's ValueError is a user-facing message and must pass\\nthrough unchanged; unexpected errors keep the generic wrapper.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom contextlib import asynccontextmanager\\n\\nimport pytest\\nfrom lfx.base.tools.run_flow import RunFlowBaseComponent\\nfrom lfx.components.flow_controls.human_input import HumanInput\\nfrom lfx.components.input_output import ChatInput, ChatOutput\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.run.hitl import NESTED_HITL_UNSUPPORTED\\n\\n\\ndef _node(component) -> dict:\\n    frontend = component.to_frontend_node()\\n    return {\\\"id\\\": frontend[\\\"id\\\"], \\\"data\\\": frontend[\\\"data\\\"]}\\n\\n\\ndef _edge(source: str, target: str, handle: str, field: str = \\\"input_value\\\") -> dict:\\n    return {\\n        \\\"source\\\": source,\\n        \\\"target\\\": target,\\n        \\\"id\\\": f\\\"{source}-{handle}-{target}\\\",\\n        \\\"data\\\": {\\n            \\\"sourceHandle\\\": {\\\"dataType\\\": \\\"x\\\", \\\"id\\\": source, \\\"name\\\": handle, \\\"output_types\\\": [\\\"Message\\\"]},\\n            \\\"targetHandle\\\": {\\\"fieldName\\\": field, \\\"id\\\": target, \\\"inputTypes\\\": [\\\"Message\\\"], \\\"type\\\": \\\"str\\\"},\\n        },\\n    }\\n\\n\\ndef _pausing_graph() -> Graph:\\n    graph = Graph.from_payload(\\n        {\\n            \\\"nodes\\\": [\\n                _node(ChatInput(_id=\\\"chat_input\\\")),\\n                _node(HumanInput(_id=\\\"hitl1\\\")),\\n                _node(ChatOutput(_id=\\\"co_approve\\\")),\\n            ],\\n            \\\"edges\\\": [\\n                _edge(\\\"chat_input\\\", \\\"hitl1\\\", \\\"message\\\", field=\\\"prompt\\\"),\\n                _edge(\\\"hitl1\\\", \\\"co_approve\\\", \\\"branch_approve\\\"),\\n            ],\\n        },\\n        flow_id=\\\"sub\\\",\\n    )\\n    graph.prepare()\\n    return graph\\n\\n\\nclass _StubbedRunFlow(RunFlowBaseComponent):\\n    async def get_graph(self, **_kwargs) -> Graph:\\n        return _pausing_graph()\\n\\n    def _build_flow_tweak_data(self) -> dict:\\n        return {}\\n\\n    def _build_inputs(self, _tweaks) -> dict:\\n        return {\\\"input_value\\\": \\\"hi\\\"}\\n\\n\\n@asynccontextmanager\\nasync def _authorized_target_scope(**_kwargs):\\n    yield object()\\n\\n\\nasync def test_nested_hitl_rejection_is_surfaced_verbatim(monkeypatch):\\n    monkeypatch.setattr(\\n        \\\"langflow.helpers.flow.scoped_model_provider_policy_for_target_flow\\\",\\n        _authorized_target_scope,\\n    )\\n    component = _StubbedRunFlow()\\n    component.flow_name_selected = \\\"HITL\\\"\\n    component.flow_id_selected = \\\"sub\\\"\\n    component.session_id = \\\"s1\\\"\\n\\n    with pytest.raises(ValueError, match=\\\"parent flow\\\") as excinfo:\\n        await component._run_flow_with_cached_graph(user_id=\\\"u1\\\")\\n\\n    assert str(excinfo.value) == NESTED_HITL_UNSUPPORTED\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_directory_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f7dbdc79abe8abc723a9ec4384a2dddb5503fd2c0d16c45f4ae823bc7c5505dd\",\"content\":\"import tempfile\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, Mock, patch\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.directory import DirectoryComponent\\nfrom lfx.schema import Data, DataFrame\\nfrom lfx.services.deps import get_settings_service\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestDirectoryComponent(ComponentTestBaseWithoutClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return DirectoryComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Return the default kwargs for the component.\\\"\\\"\\\"\\n        default_root = tmp_path / \\\"default-root\\\"\\n        default_root.mkdir()\\n        monkeypatch.setattr(get_settings_service().settings, \\\"directory_component_allowed_roots\\\", [str(default_root)])\\n        return {\\n            \\\"path\\\": str(default_root),\\n            \\\"recursive\\\": True,\\n            \\\"use_multithreading\\\": False,\\n            \\\"silent_errors\\\": False,\\n            \\\"types\\\": [\\\"txt\\\"],\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return an empty list since this component doesn't have version-specific files.\\\"\\\"\\\"\\n        return [\\n            {\\\"version\\\": \\\"1.0.19\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"Directory\\\"},\\n            {\\\"version\\\": \\\"1.1.0\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"directory\\\"},\\n            {\\\"version\\\": \\\"1.1.1\\\", \\\"module\\\": \\\"data\\\", \\\"file_name\\\": \\\"directory\\\"},\\n        ]\\n\\n    @patch(\\\"lfx.components.data.directory.parallel_load_data\\\")\\n    @patch(\\\"lfx.components.data.directory.retrieve_file_paths\\\")\\n    @patch(\\\"lfx.components.data.DirectoryComponent.resolve_path\\\")\\n    def test_directory_component_build_with_multithreading(\\n        self, mock_resolve_path, mock_retrieve_file_paths, mock_parallel_load_data\\n    ):\\n        # Arrange\\n        directory_component = DirectoryComponent()\\n        path = Path(__file__).resolve().parent\\n        depth = 1\\n        max_concurrency = 2\\n        load_hidden = False\\n        recursive = True\\n        silent_errors = False\\n        use_multithreading = True\\n\\n        mock_resolve_path.return_value = str(path)\\n        mock_retrieve_file_paths.return_value = [str(p) for p in path.iterdir() if p.suffix == \\\".py\\\"]\\n        mock_parallel_load_data.return_value = [Mock()]\\n\\n        # Act\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": str(path),\\n                \\\"depth\\\": depth,\\n                \\\"max_concurrency\\\": max_concurrency,\\n                \\\"load_hidden\\\": load_hidden,\\n                \\\"recursive\\\": recursive,\\n                \\\"silent_errors\\\": silent_errors,\\n                \\\"use_multithreading\\\": use_multithreading,\\n                \\\"types\\\": [\\\"py\\\"],  # Add file types without dots\\n            }\\n        )\\n        directory_component.load_directory()\\n\\n        # Assert\\n        mock_resolve_path.assert_called_once_with(str(path))\\n        mock_retrieve_file_paths.assert_called_once_with(\\n            mock_resolve_path.return_value,\\n            depth=depth,\\n            recursive=recursive,\\n            types=[\\\"py\\\"],\\n            load_hidden=load_hidden,\\n        )\\n        mock_parallel_load_data.assert_called_once_with(\\n            mock_retrieve_file_paths.return_value,\\n            max_concurrency=max_concurrency,\\n            silent_errors=silent_errors,\\n        )\\n\\n    def test_directory_blocked_outside_storage_when_restricted(self, tmp_path):\\n        \\\"\\\"\\\"Restricted mode blocks reading directories outside the storage dir; inside still works.\\\"\\\"\\\"\\n        settings_mock = MagicMock()\\n        settings_mock.settings.restrict_local_file_access = True\\n        settings_mock.settings.config_dir = str(tmp_path)\\n        outside = tmp_path.parent / f\\\"{tmp_path.name}-outside\\\"\\n        outside.mkdir()\\n        settings_mock.settings.directory_component_allowed_roots = [str(tmp_path), str(outside)]\\n\\n        # A directory inside the storage dir is allowed.\\n        inside = tmp_path / \\\"flow-id\\\"\\n        inside.mkdir()\\n        (inside / \\\"ok.txt\\\").write_text(\\\"ok\\\", encoding=\\\"utf-8\\\")\\n\\n        with (\\n            patch(\\\"lfx.components.files_and_knowledge.directory.get_settings_service\\\", return_value=settings_mock),\\n            patch(\\\"lfx.utils.file_path_security.get_settings_service\\\", return_value=settings_mock),\\n        ):\\n            allowed = DirectoryComponent()\\n            allowed._user_id = \\\"flow-id\\\"\\n            allowed.set_attributes(\\n                {\\\"path\\\": str(inside), \\\"use_multithreading\\\": False, \\\"silent_errors\\\": False, \\\"types\\\": [\\\"txt\\\"]}\\n            )\\n            results = allowed.load_directory()\\n            assert len(results) == 1\\n\\n            # A configured/allowed root outside the storage dir is still blocked in restricted mode.\\n            blocked = DirectoryComponent()\\n            blocked._user_id = \\\"flow-id\\\"\\n            blocked.set_attributes(\\n                {\\\"path\\\": str(outside), \\\"use_multithreading\\\": False, \\\"silent_errors\\\": False, \\\"types\\\": [\\\"txt\\\"]}\\n            )\\n            with pytest.raises(ValueError, match=\\\"outside the authenticated user's storage scope\\\"):\\n                blocked.load_directory()\\n\\n    def test_directory_without_mocks(self, monkeypatch):\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            (Path(temp_dir) / \\\"test.txt\\\").write_text(\\\"test\\\", encoding=\\\"utf-8\\\")\\n            # also add a json file\\n            (Path(temp_dir) / \\\"test.json\\\").write_text('{\\\"test\\\": \\\"test\\\"}', encoding=\\\"utf-8\\\")\\n\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                    \\\"types\\\": [\\\"txt\\\", \\\"json\\\"],\\n                }\\n            )\\n            results = directory_component.load_directory()\\n            assert len(results) == 2\\n            values = [\\\"test\\\", '{\\\"test\\\":\\\"test\\\"}']\\n            assert all(result.text in values for result in results), [\\n                (len(result.text), len(val)) for result, val in zip(results, values, strict=True)\\n            ]\\n\\n        # in ../docs/docs/components there are many mdx files\\n        # check if the directory component can load them\\n        # just check if the number of results is the same as the number of files\\n        directory_component = DirectoryComponent()\\n        docs_path = Path(__file__).parent.parent.parent.parent.parent.parent.parent / \\\"docs\\\" / \\\"docs\\\" / \\\"Components\\\"\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": str(docs_path),\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"md\\\", \\\"json\\\"],\\n            }\\n        )\\n        results = directory_component.load_directory()\\n        docs_files = list(docs_path.glob(\\\"*.md\\\")) + list(docs_path.glob(\\\"*.json\\\"))\\n        assert len(results) == len(docs_files)\\n\\n    def test_directory_as_dataframe(self, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent's as_dataframe method.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create test files with different content\\n            files_content = {\\n                \\\"file1.txt\\\": \\\"content1\\\",\\n                \\\"file2.json\\\": '{\\\"key\\\": \\\"content2\\\"}',\\n                \\\"file3.md\\\": \\\"# content3\\\",\\n            }\\n\\n            for filename, content in files_content.items():\\n                (Path(temp_dir) / filename).write_text(content, encoding=\\\"utf-8\\\")\\n\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"types\\\": [\\\"txt\\\", \\\"json\\\", \\\"md\\\"],\\n                    \\\"silent_errors\\\": False,\\n                }\\n            )\\n\\n            # Test as_dataframe\\n            data_frame = directory_component.as_dataframe()\\n\\n            # Verify DataFrame structure\\n            assert isinstance(data_frame, DataFrame), \\\"Expected DataFrame instance\\\"\\n            assert len(data_frame) == 3, f\\\"Expected DataFrame with 3 rows, got {len(data_frame)}\\\"\\n\\n            # Check column names\\n            expected_columns = [\\\"text\\\", \\\"file_path\\\"]\\n            actual_columns = list(data_frame.columns)\\n            assert set(expected_columns).issubset(set(actual_columns)), (\\n                f\\\"Missing required columns. Expected at least {expected_columns}, got {actual_columns}\\\"\\n            )\\n\\n            # Verify content matches input files\\n            texts = data_frame[\\\"text\\\"].tolist()\\n            # For JSON files, the content is parsed and re-serialized\\n            expected_content = {\\n                \\\"file1.txt\\\": \\\"content1\\\",\\n                \\\"file2.json\\\": '{\\\"key\\\":\\\"content2\\\"}',  # JSON is re-serialized without spaces\\n                \\\"file3.md\\\": \\\"# content3\\\",\\n            }\\n            missing_content = [content for content in expected_content.values() if content not in texts]\\n            assert not missing_content, f\\\"Missing expected content in DataFrame: {missing_content}\\\"\\n\\n            # Verify file paths are correct\\n            file_paths = data_frame[\\\"file_path\\\"].tolist()\\n            expected_paths = [str(Path(temp_dir) / filename) for filename in files_content]\\n            missing_paths = [path for path in expected_paths if not any(path in fp for fp in file_paths)]\\n            assert not missing_paths, f\\\"Missing expected file paths in DataFrame: {missing_paths}\\\"\\n\\n    def test_directory_with_depth(self, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent with different depth settings.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create a nested directory structure\\n            base_dir = Path(temp_dir)\\n            (base_dir / \\\"level1\\\").mkdir()\\n            (base_dir / \\\"level1\\\" / \\\"level2\\\").mkdir()\\n\\n            # Create files at different levels\\n            (base_dir / \\\"root.txt\\\").write_text(\\\"root\\\", encoding=\\\"utf-8\\\")\\n            (base_dir / \\\"level1\\\" / \\\"level1.txt\\\").write_text(\\\"level1\\\", encoding=\\\"utf-8\\\")\\n            (base_dir / \\\"level1\\\" / \\\"level2\\\" / \\\"level2.txt\\\").write_text(\\\"level2\\\", encoding=\\\"utf-8\\\")\\n\\n            # Test non-recursive (only root)\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"recursive\\\": False,  # Set recursive to False to get only root files\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                    \\\"types\\\": [\\\"txt\\\"],\\n                }\\n            )\\n            results_root = directory_component.load_directory()\\n            assert len(results_root) == 1, (\\n                \\\"With recursive=False, expected 1 file (root.txt), \\\"\\n                f\\\"got {len(results_root)} files: {[d.data['file_path'] for d in results_root]}\\\"\\n            )\\n            assert results_root[0].text == \\\"root\\\", f\\\"Expected root file content 'root', got '{results_root[0].text}'\\\"\\n\\n            # Test recursive with all files\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"recursive\\\": True,\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                    \\\"types\\\": [\\\"txt\\\"],\\n                }\\n            )\\n            results_all = directory_component.load_directory()\\n            assert len(results_all) == 3, (\\n                \\\"With recursive=True, expected 3 files (all files), \\\"\\n                f\\\"got {len(results_all)} files: {[d.data['file_path'] for d in results_all]}\\\"\\n            )\\n            texts = sorted([r.text for r in results_all])\\n            expected_texts = sorted([\\\"root\\\", \\\"level1\\\", \\\"level2\\\"])\\n            assert texts == expected_texts, f\\\"Expected texts {expected_texts}, got {texts}\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"file_types\\\", \\\"expected_count\\\"),\\n        [\\n            ([\\\"txt\\\"], 1),\\n            ([\\\"json\\\"], 1),\\n            ([\\\"txt\\\", \\\"json\\\"], 2),\\n        ],\\n    )\\n    def test_directory_with_types(self, file_types, expected_count, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent with different file type filters (parameterized).\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create files with different extensions\\n            (Path(temp_dir) / \\\"test.txt\\\").write_text(\\\"text content\\\", encoding=\\\"utf-8\\\")\\n            (Path(temp_dir) / \\\"test.json\\\").write_text('{\\\"key\\\": \\\"value\\\"}', encoding=\\\"utf-8\\\")\\n            (Path(temp_dir) / \\\"test.exe\\\").write_text(\\\"test\\\", encoding=\\\"utf-8\\\")\\n\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"types\\\": file_types,\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                }\\n            )\\n            results = directory_component.load_directory()\\n\\n            # Verify number of loaded files\\n            assert len(results) == expected_count, (\\n                f\\\"Expected {expected_count} results for file types {file_types}, got {len(results)}\\\"\\n            )\\n            # Optionally, check the file extension in each result\\n            for r in results:\\n                # e.g., verify that the extension is indeed in file_types\\n                file_ext = Path(r.data[\\\"file_path\\\"]).suffix.lstrip(\\\".\\\")\\n                assert file_ext in file_types, f\\\"Unexpected file extension: {file_ext}\\\"\\n\\n    def test_directory_rejects_parent_traversal_before_loading_files(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Reject traversal before it can enumerate and load files outside the working root.\\\"\\\"\\\"\\n        workspace = tmp_path / \\\"workspace\\\"\\n        outside = tmp_path / \\\"tmp\\\"\\n        workspace.mkdir()\\n        outside.mkdir()\\n        (outside / \\\"poc_langflow_001.txt\\\").write_text(\\\"outside secret\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(workspace)\\n\\n        directory_component = DirectoryComponent()\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": \\\"../tmp\\\",\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Directory path escapes the allowed root\\\"):\\n            directory_component.load_directory()\\n\\n    def test_directory_rejects_absolute_path_outside_allowed_root(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Reject absolute paths outside the working root before file content is loaded.\\\"\\\"\\\"\\n        workspace = tmp_path / \\\"workspace\\\"\\n        outside = tmp_path / \\\"tmp\\\"\\n        workspace.mkdir()\\n        outside.mkdir()\\n        (outside / \\\"poc_langflow_002.txt\\\").write_text(\\\"outside secret\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(workspace)\\n\\n        directory_component = DirectoryComponent()\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": str(outside),\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Directory path escapes the allowed root\\\"):\\n            directory_component.load_directory()\\n\\n    def test_directory_loads_configured_absolute_allowed_root(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Operator-configured roots can be loaded by absolute path.\\\"\\\"\\\"\\n        workspace = tmp_path / \\\"workspace\\\"\\n        shared = tmp_path / \\\"shared\\\"\\n        workspace.mkdir()\\n        shared.mkdir()\\n        (shared / \\\"allowed.txt\\\").write_text(\\\"configured content\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(workspace)\\n        monkeypatch.setattr(get_settings_service().settings, \\\"directory_component_allowed_roots\\\", [str(shared)])\\n\\n        directory_component = DirectoryComponent()\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": str(shared),\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        results = directory_component.load_directory()\\n\\n        assert [result.text for result in results] == [\\\"configured content\\\"]\\n\\n    def test_directory_allows_drive_absolute_path_inside_allowed_root(self, tmp_path, monkeypatch):\\n        r\\\"\\\"\\\"A Windows drive/UNC path inside a configured allowed root must not be blanket-rejected.\\n\\n        On Windows a drive-absolute path (``D:\\\\\\\\shared\\\\\\\\docs``) or a UNC path\\n        (``\\\\\\\\\\\\\\\\server\\\\\\\\share``) used to be rejected by the drive pre-check before the\\n        containment check ran, breaking the documented allowed-roots escape hatch. The\\n        drive component alone must no longer reject the path; canonicalization plus the\\n        ``_allowed_roots()`` containment check decide access. POSIX runners cannot\\n        canonicalize Windows paths, so ``resolve_path``/``_allowed_roots`` are stubbed to\\n        the resolution a Windows host would produce.\\n        \\\"\\\"\\\"\\n        shared = tmp_path / \\\"shared\\\"\\n        docs = shared / \\\"docs\\\"\\n        docs.mkdir(parents=True)\\n        (docs / \\\"allowed.txt\\\").write_text(\\\"drive content\\\", encoding=\\\"utf-8\\\")\\n\\n        directory_component = DirectoryComponent()\\n        # Simulate the Windows host resolving ``D:\\\\shared\\\\docs`` to the configured root.\\n        monkeypatch.setattr(directory_component, \\\"resolve_path\\\", lambda _path: str(docs))\\n        monkeypatch.setattr(directory_component, \\\"_allowed_roots\\\", lambda: [shared])\\n\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": \\\"D:\\\\\\\\shared\\\\\\\\docs\\\",\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        results = directory_component.load_directory()\\n\\n        assert [result.text for result in results] == [\\\"drive content\\\"]\\n\\n    def test_directory_rejects_drive_absolute_path_outside_allowed_root(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"A Windows drive path outside every allowed root must still be rejected by containment.\\\"\\\"\\\"\\n        shared = tmp_path / \\\"shared\\\"\\n        outside = tmp_path / \\\"outside\\\"\\n        shared.mkdir()\\n        outside.mkdir()\\n        (outside / \\\"secret.txt\\\").write_text(\\\"outside secret\\\", encoding=\\\"utf-8\\\")\\n\\n        directory_component = DirectoryComponent()\\n        # The drive path canonicalizes outside any configured root.\\n        monkeypatch.setattr(directory_component, \\\"resolve_path\\\", lambda _path: str(outside))\\n        monkeypatch.setattr(directory_component, \\\"_allowed_roots\\\", lambda: [shared])\\n\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": \\\"D:\\\\\\\\outside\\\",\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Directory path escapes the allowed root\\\"):\\n            directory_component.load_directory()\\n\\n    def test_directory_rejects_windows_parent_traversal(self):\\n        \\\"\\\"\\\"A Windows-style parent reference is still rejected by the pre-check.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Directory path escapes the allowed root\\\"):\\n            directory_component._resolve_directory_path(\\\"D:\\\\\\\\shared\\\\\\\\..\\\\\\\\secret\\\")\\n\\n    def test_directory_loads_relative_path_inside_allowed_root(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Legitimate relative paths inside the working root still load normally.\\\"\\\"\\\"\\n        workspace = tmp_path / \\\"workspace\\\"\\n        docs = workspace / \\\"docs\\\"\\n        docs.mkdir(parents=True)\\n        (docs / \\\"allowed.txt\\\").write_text(\\\"allowed content\\\", encoding=\\\"utf-8\\\")\\n        monkeypatch.chdir(workspace)\\n\\n        directory_component = DirectoryComponent()\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": \\\"docs\\\",\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        results = directory_component.load_directory()\\n\\n        assert [result.text for result in results] == [\\\"allowed content\\\"]\\n\\n    def test_directory_does_not_follow_symlinked_file_outside_allowed_root(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Skip files whose canonical path escapes the resolved directory.\\\"\\\"\\\"\\n        workspace = tmp_path / \\\"workspace\\\"\\n        docs = workspace / \\\"docs\\\"\\n        outside = tmp_path / \\\"outside\\\"\\n        docs.mkdir(parents=True)\\n        outside.mkdir()\\n        (docs / \\\"allowed.txt\\\").write_text(\\\"allowed content\\\", encoding=\\\"utf-8\\\")\\n        outside_file = outside / \\\"secret.txt\\\"\\n        outside_file.write_text(\\\"outside secret\\\", encoding=\\\"utf-8\\\")\\n        try:\\n            (docs / \\\"linked-secret.txt\\\").symlink_to(outside_file)\\n        except OSError as exc:\\n            pytest.skip(f\\\"symlink creation unavailable: {exc}\\\")\\n        monkeypatch.chdir(workspace)\\n\\n        directory_component = DirectoryComponent()\\n        directory_component.set_attributes(\\n            {\\n                \\\"path\\\": \\\"docs\\\",\\n                \\\"recursive\\\": False,\\n                \\\"use_multithreading\\\": False,\\n                \\\"silent_errors\\\": False,\\n                \\\"types\\\": [\\\"txt\\\"],\\n            }\\n        )\\n\\n        results = directory_component.load_directory()\\n\\n        assert [result.text for result in results] == [\\\"allowed content\\\"]\\n\\n    def test_directory_invalid_type(self, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent raises error with invalid file type.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create test file\\n            (Path(temp_dir) / \\\"test.exe\\\").write_text(\\\"test\\\", encoding=\\\"utf-8\\\")\\n\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"types\\\": [\\\"exe\\\"],\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                }\\n            )\\n\\n            with pytest.raises(\\n                ValueError, match=r\\\"Invalid file types specified: \\\\['exe'\\\\]\\\\. Valid types are:\\\"\\n            ) as exc_info:\\n                directory_component.load_directory()\\n\\n            assert \\\"Invalid file types specified: ['exe']\\\" in str(exc_info.value)\\n            assert \\\"Valid types are:\\\" in str(exc_info.value)\\n\\n    def test_directory_with_hidden_files(self, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent with hidden files.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create regular and hidden files\\n            (Path(temp_dir) / \\\"regular.txt\\\").write_text(\\\"regular\\\", encoding=\\\"utf-8\\\")\\n            (Path(temp_dir) / \\\".hidden.txt\\\").write_text(\\\"hidden\\\", encoding=\\\"utf-8\\\")\\n\\n            # Test without loading hidden files\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"load_hidden\\\": False,\\n                    \\\"use_multithreading\\\": False,\\n                    \\\"silent_errors\\\": False,\\n                    \\\"types\\\": [\\\"txt\\\"],\\n                }\\n            )\\n            results = directory_component.load_directory()\\n            assert len(results) == 1\\n            assert results[0].text == \\\"regular\\\"\\n\\n            # Test with loading hidden files\\n            directory_component.set_attributes({\\\"load_hidden\\\": True})\\n            results = directory_component.load_directory()\\n            assert len(results) == 2\\n            texts = [r.text for r in results]\\n            assert \\\"regular\\\" in texts\\n            assert \\\"hidden\\\" in texts\\n\\n    @patch(\\\"lfx.components.data.directory.parallel_load_data\\\")\\n    def test_directory_with_multithreading(self, mock_parallel_load, monkeypatch):\\n        \\\"\\\"\\\"Test DirectoryComponent with multithreading enabled.\\\"\\\"\\\"\\n        directory_component = DirectoryComponent()\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, monkeypatch.context() as context:\\n            context.chdir(temp_dir)\\n            # Create test files\\n            (Path(temp_dir) / \\\"test1.txt\\\").write_text(\\\"content1\\\", encoding=\\\"utf-8\\\")\\n            (Path(temp_dir) / \\\"test2.txt\\\").write_text(\\\"content2\\\", encoding=\\\"utf-8\\\")\\n\\n            # Mock parallel_load_data to return some test data\\n            mock_data = [\\n                Data(text=\\\"content1\\\", data={\\\"file_path\\\": str(Path(temp_dir) / \\\"test1.txt\\\")}),\\n                Data(text=\\\"content2\\\", data={\\\"file_path\\\": str(Path(temp_dir) / \\\"test2.txt\\\")}),\\n            ]\\n            mock_parallel_load.return_value = mock_data\\n\\n            # Test with multithreading enabled\\n            directory_component.set_attributes(\\n                {\\n                    \\\"path\\\": str(temp_dir),\\n                    \\\"use_multithreading\\\": True,\\n                    \\\"max_concurrency\\\": 2,\\n                    \\\"types\\\": [\\\"txt\\\"],  # Specify file types to ensure files are found\\n                    \\\"recursive\\\": True,  # Enable recursive search\\n                    \\\"silent_errors\\\": False,\\n                }\\n            )\\n            results = directory_component.load_directory()\\n\\n            # Verify parallel_load_data was called with correct parameters\\n            mock_parallel_load.assert_called_once()\\n            call_args = mock_parallel_load.call_args[1]\\n            assert call_args[\\\"max_concurrency\\\"] == 2, (\\n                f\\\"Expected max_concurrency=2, got {call_args.get('max_concurrency')}\\\"\\n            )\\n            assert call_args[\\\"silent_errors\\\"] is False, (\\n                f\\\"Expected silent_errors=False, got {call_args.get('silent_errors')}\\\"\\n            )\\n\\n            # Verify results\\n            assert len(results) == 2, (\\n                f\\\"Expected 2 results, got {len(results)}: {[r.data['file_path'] for r in results]}\\\"\\n            )\\n            assert all(isinstance(r, Data) for r in results), (\\n                f\\\"All results should be Data objects, got types: {[type(r) for r in results]}\\\"\\n            )\\n\\n            actual_texts = [r.text for r in results]\\n            expected_texts = [\\\"content1\\\", \\\"content2\\\"]\\n            assert actual_texts == expected_texts, f\\\"Expected texts {expected_texts}, got {actual_texts}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_file_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7d29df1356bd4d44679c3a188c5c69a1c5af4a43484baecfae6883d4c26166cd\",\"content\":\"import asyncio\\nimport json\\nimport subprocess\\nimport tempfile\\nimport threading\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom langflow.io import Output\\nfrom lfx.components.files_and_knowledge import file as file_component_module\\nfrom lfx.components.files_and_knowledge.file import FileComponent\\n\\nfrom tests.base import ComponentTestBaseWithoutClient\\n\\n\\nclass TestFileComponentFrontendMetadata:\\n    def test_file_types_are_serialized_for_frontend(self):\\n        component = FileComponent()\\n\\n        frontend_node = component.to_frontend_node()\\n        path_template = frontend_node[\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"path\\\"]\\n\\n        assert path_template[\\\"fileTypes\\\"][:3] == [\\\"csv\\\", \\\"json\\\", \\\"pdf\\\"]\\n        assert \\\"zip\\\" in path_template[\\\"fileTypes\\\"]\\n\\n\\nclass TestFileComponentDynamicOutputs:\\n    def test_update_outputs_single_csv_file(self):\\n        \\\"\\\"\\\"Test single CSV file shows structured + raw outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"test.csv\\\"]}}}\\n\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [\\\"test.csv\\\"])\\n\\n        assert len(result[\\\"outputs\\\"]) == 3\\n        output_names = [output.name for output in result[\\\"outputs\\\"]]\\n        assert \\\"dataframe\\\" in output_names  # Structured content\\n        assert \\\"message\\\" in output_names  # Raw content\\n        assert \\\"path\\\" in output_names  # File path\\n\\n    def test_update_outputs_single_json_file(self):\\n        \\\"\\\"\\\"Test single JSON file shows JSON + raw outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"data.json\\\"]}}}\\n\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [\\\"data.json\\\"])\\n\\n        assert len(result[\\\"outputs\\\"]) == 3\\n        output_names = [output.name for output in result[\\\"outputs\\\"]]\\n        assert \\\"json\\\" in output_names  # JSON content\\n        assert \\\"message\\\" in output_names  # Raw content\\n        assert \\\"path\\\" in output_names  # File path\\n\\n    async def test_update_outputs_multiple_files_preserves_raw_content(self):\\n        \\\"\\\"\\\"Test multiple files keep the Message output alongside Files.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"file1.txt\\\", \\\"file2.txt\\\"]}}}\\n\\n        result = await component.run_and_validate_update_outputs(frontend_node, \\\"path\\\", [\\\"file1.txt\\\", \\\"file2.txt\\\"])\\n\\n        assert [\\n            (output[\\\"name\\\"], output[\\\"display_name\\\"], output[\\\"method\\\"], output[\\\"types\\\"]) for output in result[\\\"outputs\\\"]\\n        ] == [\\n            (\\\"dataframe\\\", \\\"Files\\\", \\\"load_files\\\", [\\\"Table\\\"]),\\n            (\\\"message\\\", \\\"Raw Content\\\", \\\"load_files_message\\\", [\\\"Message\\\"]),\\n        ]\\n\\n    @pytest.mark.parametrize(\\n        (\\\"paths\\\", \\\"advanced_mode\\\", \\\"expected_outputs\\\"),\\n        [\\n            (\\n                [\\\"test.csv\\\"],\\n                False,\\n                [\\n                    (\\\"dataframe\\\", [\\\"Table\\\"], \\\"Table\\\"),\\n                    (\\\"message\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                    (\\\"path\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                ],\\n            ),\\n            (\\n                [\\\"data.json\\\"],\\n                False,\\n                [\\n                    (\\\"json\\\", [\\\"JSON\\\"], \\\"JSON\\\"),\\n                    (\\\"message\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                    (\\\"path\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                ],\\n            ),\\n            (\\n                [\\\"document.txt\\\"],\\n                False,\\n                [(\\\"message\\\", [\\\"Message\\\"], \\\"Message\\\"), (\\\"path\\\", [\\\"Message\\\"], \\\"Message\\\")],\\n            ),\\n            (\\n                [\\\"document.pdf\\\"],\\n                True,\\n                [\\n                    (\\\"advanced_dataframe\\\", [\\\"Table\\\"], \\\"Table\\\"),\\n                    (\\\"advanced_markdown\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                    (\\\"path\\\", [\\\"Message\\\"], \\\"Message\\\"),\\n                ],\\n            ),\\n            (\\n                [\\\"file1.txt\\\", \\\"file2.txt\\\"],\\n                False,\\n                [(\\\"dataframe\\\", [\\\"Table\\\"], \\\"Table\\\"), (\\\"message\\\", [\\\"Message\\\"], \\\"Message\\\")],\\n            ),\\n        ],\\n    )\\n    def test_update_outputs_are_immediately_connectable(self, paths, advanced_mode, expected_outputs):\\n        \\\"\\\"\\\"Dynamic outputs must include their types before frontend validation runs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": paths}, \\\"advanced_mode\\\": {\\\"value\\\": advanced_mode}},\\n        }\\n\\n        result = component.update_outputs(frontend_node, \\\"path\\\", paths)\\n\\n        assert [(output.name, output.types, output.selected) for output in result[\\\"outputs\\\"]] == expected_outputs\\n\\n    def test_update_outputs_empty_path(self):\\n        \\\"\\\"\\\"Test empty path results in no outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": []}}}\\n\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [])\\n\\n        assert len(result[\\\"outputs\\\"]) == 0\\n\\n    def test_update_outputs_non_path_field(self):\\n        \\\"\\\"\\\"Test non-path fields don't affect outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        original_outputs = [Output(display_name=\\\"Test\\\", name=\\\"test\\\", method=\\\"test_method\\\")]\\n        frontend_node = {\\\"outputs\\\": original_outputs, \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"value\\\"]}}}\\n\\n        result = component.update_outputs(frontend_node, \\\"other_field\\\", \\\"value\\\")\\n\\n        assert result[\\\"outputs\\\"] == original_outputs\\n\\n    def test_update_outputs_advanced_mode_enabled_single_pdf(self):\\n        \\\"\\\"\\\"Test advanced mode enabled for single PDF shows advanced outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\n                \\\"path\\\": {\\\"file_path\\\": [\\\"document.pdf\\\"]},\\n                \\\"advanced_mode\\\": {\\\"value\\\": True},\\n            },\\n        }\\n\\n        result = component.update_outputs(frontend_node, \\\"advanced_mode\\\", field_value=True)\\n\\n        assert len(result[\\\"outputs\\\"]) == 3\\n        output_names = [output.name for output in result[\\\"outputs\\\"]]\\n        assert \\\"advanced_dataframe\\\" in output_names\\n        assert \\\"advanced_markdown\\\" in output_names\\n        assert \\\"path\\\" in output_names\\n\\n    def test_update_outputs_advanced_mode_disabled(self):\\n        \\\"\\\"\\\"Test advanced mode disabled shows standard outputs.\\\"\\\"\\\"\\n        component = FileComponent()\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\n                \\\"path\\\": {\\\"file_path\\\": [\\\"document.pdf\\\"]},\\n                \\\"advanced_mode\\\": {\\\"value\\\": False},\\n            },\\n        }\\n\\n        result = component.update_outputs(frontend_node, \\\"advanced_mode\\\", field_value=False)\\n\\n        assert len(result[\\\"outputs\\\"]) == 2\\n        output_names = [output.name for output in result[\\\"outputs\\\"]]\\n        assert \\\"message\\\" in output_names\\n        assert \\\"path\\\" in output_names\\n\\n    def test_advanced_mode_not_available_for_csv(self):\\n        \\\"\\\"\\\"Test advanced mode is hidden for CSV files.\\\"\\\"\\\"\\n        component = FileComponent()\\n        build_config = {\\n            \\\"advanced_mode\\\": {\\\"show\\\": True, \\\"value\\\": False},\\n            \\\"pipeline\\\": {\\\"show\\\": False},\\n            \\\"ocr_engine\\\": {\\\"show\\\": False},\\n            \\\"path\\\": {\\\"file_path\\\": [\\\"test.csv\\\"]},\\n        }\\n\\n        result = component.update_build_config(build_config, [\\\"test.csv\\\"], \\\"path\\\")\\n\\n        assert result[\\\"advanced_mode\\\"][\\\"show\\\"] is False\\n        assert result[\\\"advanced_mode\\\"][\\\"value\\\"] is False\\n\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_process_docling_subprocess_success(self, mock_popen):\\n        \\\"\\\"\\\"Test successful Docling execution for a valid path containing shell punctuation.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.markdown = False\\n        file_path = \\\"invoice;final.pdf\\\"\\n\\n        # Mock successful subprocess response\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"structured\\\",\\n            \\\"doc\\\": [\\n                {\\\"page_no\\\": 1, \\\"label\\\": \\\"title\\\", \\\"text\\\": \\\"Test Document\\\", \\\"level\\\": 1},\\n                {\\\"page_no\\\": 1, \\\"label\\\": \\\"paragraph\\\", \\\"text\\\": \\\"Content here\\\", \\\"level\\\": 0},\\n            ],\\n            \\\"meta\\\": {\\\"file_path\\\": file_path},\\n        }\\n        stdout_bytes = json.dumps(mock_result).encode(\\\"utf-8\\\")\\n\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (stdout_bytes, b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(file_path)\\n\\n        assert result is not None\\n        assert result.data[\\\"doc\\\"] == mock_result[\\\"doc\\\"]\\n        assert result.data[\\\"file_path\\\"] == file_path\\n        mock_proc.communicate.assert_called_once()\\n\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_process_docling_subprocess_drains_output_between_heartbeats(self, mock_popen):\\n        component = FileComponent()\\n        component.markdown = False\\n        mock_result = {\\\"ok\\\": True, \\\"mode\\\": \\\"structured\\\", \\\"doc\\\": [], \\\"meta\\\": {\\\"file_path\\\": \\\"test.pdf\\\"}}\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.side_effect = [\\n            subprocess.TimeoutExpired(cmd=\\\"docling\\\", timeout=5),\\n            (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\"),\\n        ]\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(\\\"test.pdf\\\")\\n\\n        assert result is not None\\n        assert result.data[\\\"doc\\\"] == []\\n        assert mock_proc.communicate.call_count == 2\\n        assert mock_proc.communicate.call_args_list[0].kwargs[\\\"input\\\"] is not None\\n        assert mock_proc.communicate.call_args_list[1].kwargs[\\\"input\\\"] is None\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_storage_service\\\")\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    def test_process_files_preserves_local_temp_marker_for_docling_in_s3(self, mock_settings, mock_storage, tmp_path):\\n        \\\"\\\"\\\"Cloud downloads already on disk must not be reinterpreted as S3 keys.\\\"\\\"\\\"\\n        from lfx.base.data.base_file import BaseFileComponent\\n        from lfx.schema.data import Data\\n\\n        mock_settings.return_value.settings.storage_type = \\\"s3\\\"\\n        local_temp_file = tmp_path / \\\"report.pdf\\\"\\n        local_temp_file.write_bytes(b\\\"pdf\\\")\\n        component = FileComponent()\\n        component.advanced_mode = True\\n        component.markdown = False\\n        component.silent_errors = False\\n        base_file = BaseFileComponent.BaseFile(\\n            data=Data(data={\\\"file_path\\\": str(local_temp_file)}),\\n            path=local_temp_file,\\n            delete_after_processing=True,\\n            cleanup_local_file=True,\\n        )\\n        docling_result = Data(data={\\\"doc\\\": [{\\\"text\\\": \\\"processed\\\"}], \\\"file_path\\\": str(local_temp_file)})\\n\\n        with patch.object(component, \\\"_process_docling_subprocess_impl\\\", return_value=docling_result) as mock_process:\\n            result = component.process_files([base_file])\\n\\n        assert result\\n        mock_storage.assert_not_called()\\n        mock_process.assert_called_once_with(str(local_temp_file), str(local_temp_file))\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_storage_service\\\")\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    def test_docling_unmarked_absolute_path_still_requires_s3_key(self, mock_settings, mock_storage, tmp_path):\\n        \\\"\\\"\\\"The local-temp bypass must not weaken validation for ordinary S3 inputs.\\\"\\\"\\\"\\n        mock_settings.return_value.settings.storage_type = \\\"s3\\\"\\n        unmarked_file = tmp_path / \\\"report.pdf\\\"\\n        unmarked_file.write_bytes(b\\\"pdf\\\")\\n        component = FileComponent()\\n\\n        with pytest.raises(ValueError, match=\\\"Invalid S3 path format\\\"):\\n            component._process_docling_in_subprocess(str(unmarked_file))\\n\\n        mock_storage.assert_not_called()\\n\\n    def test_dynamic_outputs_have_tool_mode_enabled(self):\\n        \\\"\\\"\\\"Test that all dynamically created outputs have tool_mode=True.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        # Test single CSV file\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"test.csv\\\"]}}}\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [\\\"test.csv\\\"])\\n        for output in result[\\\"outputs\\\"]:\\n            assert output.tool_mode is True, f\\\"Output {output.name} should have tool_mode=True\\\"\\n\\n        # Test single JSON file\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"data.json\\\"]}}}\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [\\\"data.json\\\"])\\n        for output in result[\\\"outputs\\\"]:\\n            assert output.tool_mode is True, f\\\"Output {output.name} should have tool_mode=True\\\"\\n\\n        # Test multiple files\\n        frontend_node = {\\\"outputs\\\": [], \\\"template\\\": {\\\"path\\\": {\\\"file_path\\\": [\\\"file1.txt\\\", \\\"file2.txt\\\"]}}}\\n        result = component.update_outputs(frontend_node, \\\"path\\\", [\\\"file1.txt\\\", \\\"file2.txt\\\"])\\n        for output in result[\\\"outputs\\\"]:\\n            assert output.tool_mode is True, f\\\"Output {output.name} should have tool_mode=True\\\"\\n\\n        # Test advanced mode enabled\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\n                \\\"path\\\": {\\\"file_path\\\": [\\\"document.pdf\\\"]},\\n                \\\"advanced_mode\\\": {\\\"value\\\": True},\\n            },\\n        }\\n        result = component.update_outputs(frontend_node, \\\"advanced_mode\\\", field_value=True)\\n        for output in result[\\\"outputs\\\"]:\\n            assert output.tool_mode is True, f\\\"Output {output.name} should have tool_mode=True\\\"\\n\\n        # Test advanced mode disabled\\n        frontend_node = {\\n            \\\"outputs\\\": [],\\n            \\\"template\\\": {\\n                \\\"path\\\": {\\\"file_path\\\": [\\\"document.pdf\\\"]},\\n                \\\"advanced_mode\\\": {\\\"value\\\": False},\\n            },\\n        }\\n        result = component.update_outputs(frontend_node, \\\"advanced_mode\\\", field_value=False)\\n        for output in result[\\\"outputs\\\"]:\\n            assert output.tool_mode is True, f\\\"Output {output.name} should have tool_mode=True\\\"\\n\\n    def test_file_path_str_input_exists_for_tool_mode(self):\\n        \\\"\\\"\\\"Test that file_path_str input exists for tool mode.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        # Find the file_path_str input\\n        file_path_str_input = None\\n        for input_field in component.inputs:\\n            if input_field.name == \\\"file_path_str\\\":\\n                file_path_str_input = input_field\\n                break\\n\\n        assert file_path_str_input is not None, \\\"file_path_str input should exist\\\"\\n        assert file_path_str_input.tool_mode is True, \\\"file_path_str should have tool_mode=True\\\"\\n\\n        # Check that the path FileInput has tool_mode=False\\n        path_input = None\\n        for input_field in component.inputs:\\n            if input_field.name == \\\"path\\\":\\n                path_input = input_field\\n                break\\n\\n        assert path_input is not None, \\\"path input should exist\\\"\\n        assert path_input.tool_mode is False, \\\"path FileInput should have tool_mode=False\\\"\\n\\n    def test_read_file_using_file_path_str(self, tmp_path):\\n        \\\"\\\"\\\"Test reading a file using file_path_str parameter (tool mode).\\\"\\\"\\\"\\n        # Create a test file\\n        test_file = tmp_path / \\\"test.txt\\\"\\n        test_content = \\\"Hello from tool mode!\\\"\\n        test_file.write_text(test_content)\\n\\n        # Create component and set file_path_str\\n        component = FileComponent()\\n        component.file_path_str = str(test_file)\\n\\n        # Load the file\\n        result = component.load_files_message()\\n\\n        assert result.text == test_content, f\\\"Expected '{test_content}', got '{result.text}'\\\"\\n\\n    def test_read_file_using_path_when_file_path_str_not_provided(self, tmp_path):\\n        \\\"\\\"\\\"Test that component falls back to uploaded file when file_path_str is not provided.\\n\\n        This simulates the scenario where a file is uploaded via UI and then the Agent\\n        calls the component as a tool without providing file_path_str.\\n        When a file is uploaded via UI, the FileInput populates the file_path attribute.\\n        \\\"\\\"\\\"\\n        # Create a test file\\n        test_file = tmp_path / \\\"test_from_ui.txt\\\"\\n        test_content = \\\"Hello from uploaded file!\\\"\\n        test_file.write_text(test_content)\\n\\n        # Create component and simulate uploaded file\\n        component = FileComponent()\\n        # When user uploads file via UI, the FileInput sets the path attribute\\n        # which populates the file_path list (from FileMixin)\\n        component.path = str(test_file)  # Simulate FileInput value\\n\\n        # DO NOT set file_path_str (simulating Agent calling tool without this parameter)\\n        # component.file_path_str should be None or empty\\n\\n        # Load the file - should use path since file_path_str is not provided\\n        result = component.load_files_message()\\n\\n        assert result.text == test_content, f\\\"Expected '{test_content}', got '{result.text}'\\\"\\n\\n    def test_file_path_str_takes_priority_over_path(self, tmp_path):\\n        \\\"\\\"\\\"Test that file_path_str takes priority when both are provided.\\\"\\\"\\\"\\n        # Create two test files\\n        file1 = tmp_path / \\\"file1.txt\\\"\\n        file1.write_text(\\\"Content from path\\\")\\n\\n        file2 = tmp_path / \\\"file2.txt\\\"\\n        file2.write_text(\\\"Content from file_path_str\\\")\\n\\n        # Create component with both inputs set\\n        component = FileComponent()\\n        component.path = str(file1)  # Uploaded file via UI\\n        component.file_path_str = str(file2)  # Provided by Agent tool call\\n\\n        # Load the file - should use file_path_str (priority)\\n        result = component.load_files_message()\\n\\n        assert result.text == \\\"Content from file_path_str\\\", \\\"file_path_str should take priority over path\\\"\\n\\n\\nclass TestFileComponentToolMode(ComponentTestBaseWithoutClient):\\n    \\\"\\\"\\\"Tests for the tool mode functionality of FileComponent.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def component_class(self):\\n        return FileComponent\\n\\n    @pytest.fixture\\n    def default_kwargs(self):\\n        return {}\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        return []\\n\\n    def test_get_tool_description_without_files(self):\\n        \\\"\\\"\\\"Test tool description when no files are uploaded.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = None\\n\\n        description = component.get_tool_description()\\n\\n        assert description == \\\"Loads and returns the content from uploaded files.\\\"\\n\\n    def test_get_tool_description_with_single_file(self):\\n        \\\"\\\"\\\"Test tool description includes single file name.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/document.pdf\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"document.pdf\\\" in description\\n        assert \\\"Available files:\\\" in description\\n\\n    def test_get_tool_description_with_multiple_files(self):\\n        \\\"\\\"\\\"Test tool description includes all file names.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\n            \\\"flow123/report.pdf\\\",\\n            \\\"flow123/data.csv\\\",\\n            \\\"flow123/notes.txt\\\",\\n        ]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"report.pdf\\\" in description\\n        assert \\\"data.csv\\\" in description\\n        assert \\\"notes.txt\\\" in description\\n        assert \\\"Available files:\\\" in description\\n\\n    def test_get_tool_description_with_empty_list(self):\\n        \\\"\\\"\\\"Test tool description with empty file list.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = []\\n\\n        description = component.get_tool_description()\\n\\n        assert description == \\\"Loads and returns the content from uploaded files.\\\"\\n\\n    def test_description_property_returns_dynamic_description(self):\\n        \\\"\\\"\\\"Test that description property returns dynamic description.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/test.pdf\\\"]\\n\\n        # Access via property\\n        description = component.description\\n\\n        assert \\\"test.pdf\\\" in description\\n\\n    # ==================== Edge Cases: File Names ====================\\n\\n    def test_get_tool_description_filename_with_spaces(self):\\n        \\\"\\\"\\\"Test handling of filenames with spaces.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/my document with spaces.pdf\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"my document with spaces.pdf\\\" in description\\n\\n    def test_get_tool_description_filename_with_comma(self):\\n        \\\"\\\"\\\"Test handling of filenames with commas.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/file,with,commas.txt\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"file,with,commas.txt\\\" in description\\n\\n    def test_get_tool_description_filename_with_multiple_dots(self):\\n        \\\"\\\"\\\"Test handling of filenames with multiple dots.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/file.name.with.dots.pdf\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"file.name.with.dots.pdf\\\" in description\\n\\n    def test_get_tool_description_filename_with_special_characters(self):\\n        \\\"\\\"\\\"Test handling of filenames with special characters.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\n            \\\"flow123/file-with-dashes.pdf\\\",\\n            \\\"flow123/file_with_underscores.txt\\\",\\n            \\\"flow123/file (with) parentheses.doc\\\",\\n        ]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"file-with-dashes.pdf\\\" in description\\n        assert \\\"file_with_underscores.txt\\\" in description\\n        assert \\\"file (with) parentheses.doc\\\" in description\\n\\n    def test_get_tool_description_filename_with_unicode(self):\\n        \\\"\\\"\\\"Test handling of filenames with unicode characters.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\n            \\\"flow123/\u6587\u6863.pdf\\\",\\n            \\\"flow123/\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.txt\\\",\\n            \\\"flow123/arquivo_portugu\u00eas.pdf\\\",\\n        ]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"\u6587\u6863.pdf\\\" in description\\n        assert \\\"\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442.txt\\\" in description\\n        assert \\\"arquivo_portugu\u00eas.pdf\\\" in description\\n\\n    def test_get_tool_description_filename_with_numbers(self):\\n        \\\"\\\"\\\"Test handling of filenames with numbers.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\n            \\\"flow123/report_2024_01_15.pdf\\\",\\n            \\\"flow123/v1.2.3_release_notes.txt\\\",\\n        ]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"report_2024_01_15.pdf\\\" in description\\n        assert \\\"v1.2.3_release_notes.txt\\\" in description\\n\\n    def test_get_tool_description_very_long_filename(self):\\n        \\\"\\\"\\\"Test handling of very long filenames.\\\"\\\"\\\"\\n        component = FileComponent()\\n        long_name = \\\"a\\\" * 200 + \\\".pdf\\\"\\n        component._attributes[\\\"path\\\"] = [f\\\"flow123/{long_name}\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert long_name in description\\n\\n    def test_get_tool_description_filters_empty_paths(self):\\n        \\\"\\\"\\\"Test that empty paths are filtered out.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/valid.pdf\\\", \\\"\\\", None, \\\"flow123/another.txt\\\"]\\n\\n        description = component.get_tool_description()\\n\\n        assert \\\"valid.pdf\\\" in description\\n        assert \\\"another.txt\\\" in description\\n        # Should not crash or include empty entries\\n\\n    # ==================== _get_tools() Tests ====================\\n\\n    @pytest.mark.asyncio\\n    async def test_get_tools_returns_tool_without_parameters(self):\\n        \\\"\\\"\\\"Test that _get_tools() creates a tool without file_path_str parameter.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/test.pdf\\\"]\\n\\n        tools = await component._get_tools()\\n\\n        assert len(tools) == 1\\n        tool = tools[0]\\n        assert tool.name == \\\"load_files_message\\\"\\n\\n        # Check that args_schema has no required fields (empty schema)\\n        schema = tool.args_schema.model_json_schema()\\n        properties = schema.get(\\\"properties\\\", {})\\n        assert len(properties) == 0, f\\\"Tool should have no parameters, but has: {properties}\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_get_tools_description_includes_filenames(self):\\n        \\\"\\\"\\\"Test that tool description includes uploaded filenames.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/important_document.pdf\\\"]\\n\\n        tools = await component._get_tools()\\n\\n        assert len(tools) == 1\\n        tool = tools[0]\\n        assert \\\"important_document.pdf\\\" in tool.description\\n\\n    @pytest.mark.asyncio\\n    async def test_get_tools_works_with_no_files(self):\\n        \\\"\\\"\\\"Test that _get_tools() works even when no files are uploaded.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = None\\n\\n        tools = await component._get_tools()\\n\\n        assert len(tools) == 1\\n        tool = tools[0]\\n        assert tool.name == \\\"load_files_message\\\"\\n        assert \\\"Loads and returns the content from uploaded files\\\" in tool.description\\n\\n    @pytest.mark.asyncio\\n    async def test_get_tools_metadata(self):\\n        \\\"\\\"\\\"Test that tool has correct metadata.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"flow123/test.pdf\\\"]\\n\\n        tools = await component._get_tools()\\n\\n        tool = tools[0]\\n        assert tool.metadata[\\\"display_name\\\"] == \\\"Read File\\\"\\n        assert \\\"test.pdf\\\" in tool.metadata[\\\"display_description\\\"]\\n\\n    @pytest.mark.asyncio\\n    async def test_tool_execution_reads_uploaded_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that the tool correctly reads the uploaded file when executed.\\\"\\\"\\\"\\n        # Create a test file\\n        test_file = tmp_path / \\\"test_content.txt\\\"\\n        test_content = \\\"This is the file content for tool test.\\\"\\n        test_file.write_text(test_content)\\n\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [str(test_file)]\\n        component.path = [str(test_file)]\\n\\n        tools = await component._get_tools()\\n        tool = tools[0]\\n\\n        # Execute the tool (it should read the file without any arguments)\\n        result = await tool.coroutine()\\n\\n        assert test_content in result\\n\\n    @pytest.mark.parametrize(\\n        (\\\"advanced_mode\\\", \\\"loader_name\\\"),\\n        [(False, \\\"load_files_message\\\"), (True, \\\"load_files_markdown\\\")],\\n    )\\n    @pytest.mark.asyncio\\n    async def test_tool_execution_offloads_sync_loader(\\n        self, monkeypatch, component_class, default_kwargs, advanced_mode, loader_name\\n    ):\\n        \\\"\\\"\\\"Both synchronous loaders must run outside the event-loop thread (issue #14380).\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        component.advanced_mode = advanced_mode\\n        event_loop_thread = threading.current_thread()\\n        loader_thread = None\\n\\n        def fake_loader(_component):\\n            nonlocal loader_thread\\n            loader_thread = threading.current_thread()\\n            return \\\"file contents\\\"\\n\\n        monkeypatch.setattr(component_class, loader_name, fake_loader)\\n\\n        tool = (await component._get_tools())[0]\\n        result = await tool.coroutine()\\n\\n        assert result == \\\"file contents\\\"\\n        assert loader_thread is not None\\n        assert loader_thread is not event_loop_thread\\n\\n    @pytest.mark.asyncio\\n    async def test_cancelled_standard_loader_holds_bounded_admission_slot(self, monkeypatch, component_class):\\n        \\\"\\\"\\\"A cancelled sync loader keeps its slot until its worker really exits.\\\"\\\"\\\"\\n        load_limiter = asyncio.Semaphore(1)\\n        monkeypatch.setattr(file_component_module, \\\"_get_file_tool_limiter\\\", lambda: load_limiter)\\n\\n        first_started = threading.Event()\\n        release_first = threading.Event()\\n        first_finished = threading.Event()\\n        second_started = threading.Event()\\n        call_lock = threading.Lock()\\n        call_count = 0\\n\\n        def fake_loader(_component):\\n            nonlocal call_count\\n            with call_lock:\\n                call_count += 1\\n                current_call = call_count\\n            if current_call == 1:\\n                first_started.set()\\n                assert release_first.wait(timeout=2), \\\"Cancelled standard loader was not released by the test\\\"\\n                first_finished.set()\\n                return \\\"first file\\\"\\n            second_started.set()\\n            return \\\"second file\\\"\\n\\n        monkeypatch.setattr(component_class, \\\"load_files_message\\\", fake_loader)\\n        first_tool = (await component_class()._get_tools())[0]\\n        second_tool = (await component_class()._get_tools())[0]\\n        first_task = asyncio.create_task(first_tool.coroutine())\\n        assert await asyncio.to_thread(first_started.wait, 1), \\\"Standard loader did not start\\\"\\n\\n        first_task.cancel()\\n        second_task = asyncio.create_task(second_tool.coroutine())\\n        try:\\n            assert not await asyncio.to_thread(second_started.wait, 0.1), (\\n                \\\"A second loader started before the cancelled worker released its admission slot\\\"\\n            )\\n        finally:\\n            release_first.set()\\n\\n        with pytest.raises(asyncio.CancelledError):\\n            await first_task\\n        assert first_finished.is_set()\\n        assert await asyncio.wait_for(second_task, timeout=2) == \\\"second file\\\"\\n        assert second_started.is_set()\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"subprocess.Popen\\\")\\n    async def test_tool_cancellation_kills_and_reaps_docling_subprocess(self, mock_popen, monkeypatch, component_class):\\n        component = component_class()\\n        component.advanced_mode = True\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"None\\\"\\n\\n        started = threading.Event()\\n        allow_poll = threading.Event()\\n        stopped = threading.Event()\\n        released = threading.Event()\\n        reaped = threading.Event()\\n        finished = threading.Event()\\n        communicate_calls = 0\\n        mock_proc = MagicMock()\\n\\n        def communicate(*args, **kwargs):  # noqa: ARG001\\n            nonlocal communicate_calls\\n            communicate_calls += 1\\n            if communicate_calls == 1:\\n                started.set()\\n                assert allow_poll.wait(timeout=2), \\\"Docling cancellation checkpoint was not released\\\"\\n                raise subprocess.TimeoutExpired(cmd=\\\"docling\\\", timeout=5)\\n            if stopped.is_set():\\n                reaped.set()\\n                return b\\\"\\\", b\\\"\\\"\\n            assert released.wait(timeout=2), \\\"Abandoned Docling subprocess was not released by the test\\\"\\n            return b\\\"\\\", b\\\"\\\"\\n\\n        mock_proc.communicate.side_effect = communicate\\n        mock_proc.kill.side_effect = stopped.set\\n        mock_proc.terminate.side_effect = stopped.set\\n        mock_popen.return_value = mock_proc\\n\\n        def fake_loader(file_component):\\n            try:\\n                return file_component._process_docling_subprocess_impl(\\\"test.pdf\\\", \\\"test.pdf\\\")\\n            finally:\\n                finished.set()\\n\\n        monkeypatch.setattr(component_class, \\\"load_files_markdown\\\", fake_loader)\\n\\n        tool = (await component._get_tools())[0]\\n        task = asyncio.create_task(tool.coroutine())\\n        assert await asyncio.to_thread(started.wait, 1), \\\"Docling subprocess did not start\\\"\\n\\n        task.cancel()\\n        await asyncio.sleep(0.01)\\n        allow_poll.set()\\n        try:\\n            with pytest.raises(asyncio.CancelledError):\\n                await task\\n            assert stopped.is_set(), \\\"Docling subprocess was not stopped after tool cancellation\\\"\\n            assert reaped.is_set(), \\\"Docling subprocess was not reaped after tool cancellation\\\"\\n            assert finished.is_set(), \\\"Loader worker did not finish cancellation cleanup\\\"\\n        finally:\\n            released.set()\\n            await asyncio.to_thread(finished.wait, 2)\\n\\n    # ==================== Error Handling Tests ====================\\n\\n    @pytest.mark.asyncio\\n    async def test_tool_execution_handles_missing_file(self):\\n        \\\"\\\"\\\"Test that tool handles missing file gracefully.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = [\\\"/nonexistent/path/file.txt\\\"]\\n        component.path = [\\\"/nonexistent/path/file.txt\\\"]\\n\\n        tools = await component._get_tools()\\n        tool = tools[0]\\n\\n        # Execute the tool - should return error message, not crash\\n        result = await tool.coroutine()\\n\\n        assert \\\"Error\\\" in result or \\\"not found\\\" in result.lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_tool_execution_handles_empty_file_list(self):\\n        \\\"\\\"\\\"Test that tool handles empty file list.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component._attributes[\\\"path\\\"] = []\\n        component.path = []\\n\\n        tools = await component._get_tools()\\n        tool = tools[0]\\n\\n        # Execute the tool - should handle gracefully\\n        result = await tool.coroutine()\\n\\n        # Should return an error or empty result, not crash\\n        assert result is not None\\n\\n    def test_add_tool_output_is_enabled(self):\\n        \\\"\\\"\\\"Test that add_tool_output is True for FileComponent.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        assert hasattr(component, \\\"add_tool_output\\\")\\n        # Note: add_tool_output is a class attribute\\n        assert FileComponent.add_tool_output is True\\n\\n    # ==================== Integration Tests ====================\\n\\n    def test_file_path_str_input_has_tool_mode_true(self):\\n        \\\"\\\"\\\"Verify file_path_str input has tool_mode=True for Toolset toggle.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        file_path_str_input = None\\n        for input_field in component.inputs:\\n            if input_field.name == \\\"file_path_str\\\":\\n                file_path_str_input = input_field\\n                break\\n\\n        assert file_path_str_input is not None\\n        assert file_path_str_input.tool_mode is True\\n\\n    def test_output_has_tool_mode_true(self):\\n        \\\"\\\"\\\"Verify the main output has tool_mode=True.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        # Check static outputs\\n        for output in component.outputs:\\n            if output.name == \\\"message\\\":\\n                assert output.tool_mode is True\\n                break\\n        else:\\n            pytest.fail(\\\"Output 'message' not found in component outputs\\\")\\n\\n    # ==================== Cloud Storage Temp File Cleanup Tests ====================\\n\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_s3_client\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.validate_aws_credentials\\\")\\n    def test_s3_temp_file_cleanup_on_download_failure(\\n        self,\\n        mock_validate,  # noqa: ARG002\\n        mock_create_client,\\n        monkeypatch,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"Test that temp file is cleaned up when S3 download fails.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_access_key_id\\\": \\\"test_key\\\",\\n                \\\"aws_secret_access_key\\\": \\\"test_secret\\\",\\n                \\\"bucket_name\\\": \\\"test-bucket\\\",\\n                \\\"s3_file_key\\\": \\\"test-file.txt\\\",\\n            }\\n        )\\n\\n        # Mock S3 client to raise an exception during download\\n        mock_s3_client = MagicMock()\\n        mock_s3_client.download_fileobj.side_effect = Exception(\\\"S3 download failed\\\")\\n        mock_create_client.return_value = mock_s3_client\\n\\n        # Route the component's temp file into the directory we actually assert on.\\n        temp_dir = tmp_path / \\\"component-tmp\\\"\\n        temp_dir.mkdir()\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(temp_dir))\\n\\n        # Attempt to read from S3 - should fail and clean up temp file\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from S3\\\"):\\n            component._read_from_aws_s3()\\n\\n        # Verify no temp files are left behind\\n        leftovers = list(temp_dir.iterdir())\\n        assert leftovers == [], f\\\"Temp files not cleaned up: {leftovers}\\\"\\n\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_s3_client\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.validate_aws_credentials\\\")\\n    def test_s3_download_uses_explicit_local_cleanup(self, mock_validate, mock_create_client):  # noqa: ARG002\\n        \\\"\\\"\\\"Successful AWS downloads must remain eligible for local temp cleanup.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_access_key_id\\\": \\\"test_key\\\",\\n                \\\"aws_secret_access_key\\\": \\\"test_secret\\\",\\n                \\\"bucket_name\\\": \\\"test-bucket\\\",\\n                \\\"s3_file_key\\\": \\\"test-file.txt\\\",\\n            }\\n        )\\n        mock_s3_client = MagicMock()\\n        mock_s3_client.download_fileobj.side_effect = lambda _bucket, _key, target: target.write(b\\\"SAFE_CANARY\\\")\\n        mock_create_client.return_value = mock_s3_client\\n\\n        base_file = component._read_from_aws_s3()[0]\\n\\n        assert base_file.cleanup_local_file is True\\n        assert base_file.path.read_bytes() == b\\\"SAFE_CANARY\\\"\\n        component._delete_after_processing(base_file)\\n        assert not base_file.path.exists()\\n\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_google_drive_service\\\")\\n    @pytest.mark.usefixtures(\\\"fake_googleapiclient\\\")\\n    def test_google_drive_temp_file_cleanup_on_download_failure(self, mock_create_service, monkeypatch, tmp_path):\\n        \\\"\\\"\\\"Test that temp file is cleaned up when Google Drive download fails.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Google Drive\\\"}],\\n                \\\"service_account_key\\\": '{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}',\\n                \\\"file_id\\\": \\\"test-file-id\\\",\\n            }\\n        )\\n\\n        # Mock Google Drive service\\n        mock_drive_service = MagicMock()\\n        # Metadata call succeeds\\n        mock_drive_service.files().get().execute.return_value = {\\\"name\\\": \\\"test-file.txt\\\"}\\n        # Media download fails\\n        mock_drive_service.files().get_media.side_effect = Exception(\\\"Drive download failed\\\")\\n        mock_create_service.return_value = mock_drive_service\\n\\n        # Route the component's temp file into the directory we actually assert on, so the\\n        # check cannot race other tests writing into the shared system temp directory.\\n        temp_dir = tmp_path / \\\"component-tmp\\\"\\n        temp_dir.mkdir()\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(temp_dir))\\n\\n        # Attempt to read from Google Drive - should fail and clean up temp file\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from Google Drive\\\"):\\n            component._read_from_google_drive()\\n\\n        # Verify no temp files are left behind\\n        leftovers = list(temp_dir.iterdir())\\n        assert leftovers == [], f\\\"Temp files not cleaned up: {leftovers}\\\"\\n\\n    @staticmethod\\n    def _apply_windows_unlink_semantics(monkeypatch):\\n        \\\"\\\"\\\"Emulate Windows deletion semantics for `Path.unlink`.\\n\\n        On Windows, deleting a file whose handle is still open raises PermissionError.\\n\\n        POSIX allows that deletion, so without this the cleanup assertions pass on Linux/macOS\\n        CI regardless of whether cleanup happens before or after the file handle is closed.\\n\\n        Only `Path.unlink` is patched: if the component ever switches to `os.unlink` or\\n        `os.remove`, these tests go vacuous and must be updated to patch that instead.\\n        `monkeypatch` undoes both patches at teardown, so there is nothing to unwind here.\\n        \\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        handles = []\\n        real_ntf = tempfile.NamedTemporaryFile\\n        real_unlink = Path.unlink\\n\\n        def tracking_ntf(*args, **kwargs):\\n            handle = real_ntf(*args, **kwargs)\\n            handles.append(handle)\\n            return handle\\n\\n        def windows_unlink(self, *args, **kwargs):\\n            if any(handle.name == str(self) and not handle.closed for handle in handles):\\n                msg = \\\"The process cannot access the file because it is being used by another process\\\"\\n                raise PermissionError(32, msg)\\n            return real_unlink(self, *args, **kwargs)\\n\\n        monkeypatch.setattr(tempfile, \\\"NamedTemporaryFile\\\", tracking_ntf)\\n        monkeypatch.setattr(Path, \\\"unlink\\\", windows_unlink)\\n\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_s3_client\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.validate_aws_credentials\\\")\\n    def test_s3_failed_download_closes_handle_before_cleanup(\\n        self,\\n        mock_validate,  # noqa: ARG002\\n        mock_create_client,\\n        monkeypatch,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"A failed S3 download must close its temp file before deleting it.\\n\\n        Fails if the cleanup moves back inside the `NamedTemporaryFile` context.\\n        \\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"AWS\\\"}],\\n                \\\"aws_access_key_id\\\": \\\"test_key\\\",\\n                \\\"aws_secret_access_key\\\": \\\"test_secret\\\",\\n                \\\"bucket_name\\\": \\\"test-bucket\\\",\\n                \\\"s3_file_key\\\": \\\"test-file.txt\\\",\\n            }\\n        )\\n        mock_s3_client = MagicMock()\\n        mock_s3_client.download_fileobj.side_effect = Exception(\\\"S3 download failed\\\")\\n        mock_create_client.return_value = mock_s3_client\\n        temp_dir = tmp_path / \\\"component-tmp\\\"\\n        temp_dir.mkdir()\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(temp_dir))\\n\\n        self._apply_windows_unlink_semantics(monkeypatch)\\n\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from S3\\\"):\\n            component._read_from_aws_s3()\\n\\n        leftovers = list(temp_dir.iterdir())\\n        assert leftovers == [], f\\\"Partial download left behind under Windows delete semantics: {leftovers}\\\"\\n\\n    @patch(\\\"googleapiclient.http.MediaIoBaseDownload\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_google_drive_service\\\")\\n    def test_google_drive_failed_download_closes_handle_before_cleanup(\\n        self, mock_create_service, mock_downloader_class, monkeypatch, tmp_path\\n    ):\\n        \\\"\\\"\\\"A failed Google Drive download must close its temp file before deleting it.\\n\\n        The download fails mid-stream, after a chunk has been written, so the temp file holds\\n        partial content. Fails if the cleanup moves back inside the `NamedTemporaryFile` context.\\n        \\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Google Drive\\\"}],\\n                \\\"service_account_key\\\": '{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}',\\n                \\\"file_id\\\": \\\"test-file-id\\\",\\n            }\\n        )\\n        mock_drive_service = MagicMock()\\n        mock_drive_service.files().get().execute.return_value = {\\\"name\\\": \\\"test-file.txt\\\"}\\n        mock_create_service.return_value = mock_drive_service\\n\\n        def make_downloader(fd, _request):\\n            downloader = MagicMock()\\n\\n            def next_chunk():\\n                fd.write(b\\\"partial chunk\\\")\\n                msg = \\\"Drive download failed\\\"\\n                raise OSError(msg)\\n\\n            downloader.next_chunk.side_effect = next_chunk\\n            return downloader\\n\\n        mock_downloader_class.side_effect = make_downloader\\n        temp_dir = tmp_path / \\\"component-tmp\\\"\\n        temp_dir.mkdir()\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(temp_dir))\\n\\n        self._apply_windows_unlink_semantics(monkeypatch)\\n\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from Google Drive\\\"):\\n            component._read_from_google_drive()\\n\\n        leftovers = list(temp_dir.iterdir())\\n        assert leftovers == [], f\\\"Partial download left behind under Windows delete semantics: {leftovers}\\\"\\n\\n    @pytest.fixture\\n    def temp_file_close_failure(self, monkeypatch, tmp_path):\\n        \\\"\\\"\\\"Record real temp files and emulate a closing flush failure after releasing the handle.\\\"\\\"\\\"\\n        monkeypatch.setattr(tempfile, \\\"tempdir\\\", str(tmp_path))\\n        self._apply_windows_unlink_semantics(monkeypatch)\\n        real_ntf = tempfile.NamedTemporaryFile\\n        handles = []\\n        close_error = OSError(\\\"Temporary file flush failed during close\\\")\\n\\n        def failing_close_ntf(*args, **kwargs):\\n            \\\"\\\"\\\"Make the real context manager encounter an error when it closes its file.\\\"\\\"\\\"\\n            handle = real_ntf(*args, **kwargs)\\n            handles.append(handle)\\n            real_close = handle.file.close\\n\\n            def close_with_error():\\n                \\\"\\\"\\\"Release the handle before raising, as a buffered-file flush failure does.\\\"\\\"\\\"\\n                if not handle.file.closed:\\n                    real_close()\\n                    raise close_error\\n\\n            monkeypatch.setattr(handle.file, \\\"close\\\", close_with_error)\\n            return handle\\n\\n        monkeypatch.setattr(tempfile, \\\"NamedTemporaryFile\\\", failing_close_ntf)\\n        return handles, close_error\\n\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_s3_client\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.validate_aws_credentials\\\")\\n    def test_s3_temp_file_cleanup_on_close_failure(\\n        self,\\n        mock_validate,  # noqa: ARG002\\n        mock_create_client,\\n        temp_file_close_failure,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"A closing flush failure must remove the S3 download and preserve its cause.\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        component = FileComponent()\\n        component.set_attributes({\\\"bucket_name\\\": \\\"test-bucket\\\", \\\"s3_file_key\\\": \\\"test-file.txt\\\"})\\n        mock_create_client.return_value.download_fileobj.side_effect = lambda _bucket, _key, fd: fd.write(b\\\"download\\\")\\n        handles, close_error = temp_file_close_failure\\n\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from S3\\\") as exc_info:\\n            component._read_from_aws_s3()\\n\\n        assert exc_info.value.__cause__ is close_error\\n        assert len(handles) == 1\\n        assert handles[0].closed\\n        assert not Path(handles[0].name).exists()\\n        assert list(tmp_path.iterdir()) == []\\n        mock_create_client.return_value.download_fileobj.assert_called_once()\\n\\n    @patch(\\\"googleapiclient.http.MediaIoBaseDownload\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_google_drive_service\\\")\\n    def test_google_drive_temp_file_cleanup_on_close_failure(\\n        self, mock_create_service, mock_downloader_class, temp_file_close_failure, tmp_path\\n    ):\\n        \\\"\\\"\\\"A closing flush failure must remove the Drive download and preserve its cause.\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"service_account_key\\\": '{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}',\\n                \\\"file_id\\\": \\\"test-file-id\\\",\\n            }\\n        )\\n        mock_create_service.return_value.files().get().execute.return_value = {\\\"name\\\": \\\"test-file.txt\\\"}\\n\\n        def make_downloader(fd, _request):\\n            \\\"\\\"\\\"Write a successful download so only the closing flush fails.\\\"\\\"\\\"\\n            downloader = MagicMock()\\n\\n            def next_chunk():\\n                \\\"\\\"\\\"Write content and report the download as complete.\\\"\\\"\\\"\\n                fd.write(b\\\"download\\\")\\n                return None, True\\n\\n            downloader.next_chunk.side_effect = next_chunk\\n            return downloader\\n\\n        mock_downloader_class.side_effect = make_downloader\\n        handles, close_error = temp_file_close_failure\\n\\n        with pytest.raises(RuntimeError, match=\\\"Failed to download file from Google Drive\\\") as exc_info:\\n            component._read_from_google_drive()\\n\\n        assert exc_info.value.__cause__ is close_error\\n        assert len(handles) == 1\\n        assert handles[0].closed\\n        assert not Path(handles[0].name).exists()\\n        assert list(tmp_path.iterdir()) == []\\n        mock_downloader_class.assert_called_once()\\n\\n    @patch(\\\"googleapiclient.http.MediaIoBaseDownload\\\")\\n    @patch(\\\"lfx.base.data.cloud_storage_utils.create_google_drive_service\\\")\\n    def test_google_drive_download_uses_explicit_local_cleanup(self, mock_create_service, mock_downloader_class):\\n        \\\"\\\"\\\"Successful Drive downloads must remain eligible for local temp cleanup.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.set_attributes(\\n            {\\n                \\\"storage_location\\\": [{\\\"name\\\": \\\"Google Drive\\\"}],\\n                \\\"service_account_key\\\": '{\\\"type\\\": \\\"service_account\\\", \\\"project_id\\\": \\\"test\\\"}',\\n                \\\"file_id\\\": \\\"test-file-id\\\",\\n            }\\n        )\\n        mock_drive_service = MagicMock()\\n        mock_drive_service.files().get().execute.return_value = {\\\"name\\\": \\\"test-file.txt\\\"}\\n        mock_create_service.return_value = mock_drive_service\\n        mock_downloader_class.return_value.next_chunk.return_value = (None, True)\\n\\n        base_file = component._read_from_google_drive()[0]\\n\\n        assert base_file.cleanup_local_file is True\\n        assert base_file.path.exists()\\n        component._delete_after_processing(base_file)\\n        assert not base_file.path.exists()\\n\\n\\nclass TestFileComponentCloudEnvironment:\\n    \\\"\\\"\\\"Test FileComponent behavior in cloud environments.\\\"\\\"\\\"\\n\\n    def test_advanced_mode_disabled_in_cloud(self, monkeypatch):\\n        \\\"\\\"\\\"Test that advanced_mode and all Docling fields are disabled when ASTRA_CLOUD_DISABLE_COMPONENT is set.\\\"\\\"\\\"\\n        # Set the environment variable to simulate cloud environment\\n        monkeypatch.setenv(\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\", \\\"true\\\")\\n\\n        component = FileComponent()\\n        build_config = {\\n            \\\"advanced_mode\\\": {\\\"show\\\": True, \\\"value\\\": False},\\n            \\\"pipeline\\\": {\\\"show\\\": False},\\n            \\\"ocr_engine\\\": {\\\"show\\\": False},\\n            \\\"doc_key\\\": {\\\"show\\\": False},\\n            \\\"md_image_placeholder\\\": {\\\"show\\\": False},\\n            \\\"md_page_break_placeholder\\\": {\\\"show\\\": False},\\n            \\\"path\\\": {\\\"file_path\\\": [\\\"document.pdf\\\"]},\\n        }\\n\\n        result = component.update_build_config(build_config, [\\\"document.pdf\\\"], \\\"path\\\")\\n\\n        # In cloud, advanced_mode should be hidden regardless of file type\\n        assert result[\\\"advanced_mode\\\"][\\\"show\\\"] is False, \\\"advanced_mode should be hidden in cloud\\\"\\n        assert result[\\\"advanced_mode\\\"][\\\"value\\\"] is False, \\\"advanced_mode value should be False in cloud\\\"\\n        # All related fields should be hidden\\n        assert result[\\\"pipeline\\\"][\\\"show\\\"] is False\\n        assert result[\\\"ocr_engine\\\"][\\\"show\\\"] is False\\n        assert result[\\\"ocr_engine\\\"][\\\"value\\\"] == \\\"None\\\"\\n        assert result[\\\"doc_key\\\"][\\\"show\\\"] is False\\n        assert result[\\\"md_image_placeholder\\\"][\\\"show\\\"] is False\\n        assert result[\\\"md_page_break_placeholder\\\"][\\\"show\\\"] is False\\n\\n    def test_advanced_mode_toggle_disabled_in_cloud(self, monkeypatch):\\n        \\\"\\\"\\\"Test that toggling advanced_mode in cloud doesn't show Docling fields.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\", \\\"true\\\")\\n\\n        component = FileComponent()\\n        build_config = {\\n            \\\"advanced_mode\\\": {\\\"show\\\": True, \\\"value\\\": True},\\n            \\\"pipeline\\\": {\\\"show\\\": False},\\n            \\\"ocr_engine\\\": {\\\"show\\\": False},\\n            \\\"doc_key\\\": {\\\"show\\\": False},\\n            \\\"md_image_placeholder\\\": {\\\"show\\\": False},\\n            \\\"md_page_break_placeholder\\\": {\\\"show\\\": False},\\n        }\\n\\n        result = component.update_build_config(build_config, field_value=True, field_name=\\\"advanced_mode\\\")\\n\\n        # Even if advanced_mode is toggled to True, it should be disabled in cloud\\n        assert result[\\\"advanced_mode\\\"][\\\"show\\\"] is False\\n        assert result[\\\"advanced_mode\\\"][\\\"value\\\"] is False\\n        # All Docling fields should remain hidden\\n        assert result[\\\"pipeline\\\"][\\\"show\\\"] is False\\n        assert result[\\\"ocr_engine\\\"][\\\"show\\\"] is False\\n        assert result[\\\"ocr_engine\\\"][\\\"value\\\"] == \\\"None\\\"\\n\\n    def test_pipeline_change_disabled_in_cloud(self, monkeypatch):\\n        \\\"\\\"\\\"Test that changing pipeline in cloud doesn't show OCR engine.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"ASTRA_CLOUD_DISABLE_COMPONENT\\\", \\\"true\\\")\\n\\n        component = FileComponent()\\n        build_config = {\\n            \\\"advanced_mode\\\": {\\\"show\\\": False, \\\"value\\\": False},\\n            \\\"pipeline\\\": {\\\"show\\\": False},\\n            \\\"ocr_engine\\\": {\\\"show\\\": False, \\\"value\\\": \\\"easyocr\\\"},\\n        }\\n\\n        result = component.update_build_config(build_config, \\\"standard\\\", \\\"pipeline\\\")\\n\\n        # Even if pipeline is set to \\\"standard\\\", OCR engine should be disabled in cloud\\n        assert result[\\\"ocr_engine\\\"][\\\"show\\\"] is False\\n        assert result[\\\"ocr_engine\\\"][\\\"value\\\"] == \\\"None\\\"\\n\\n\\nclass TestFileComponentStorageLocation:\\n    \\\"\\\"\\\"Tests for default Local storage and Storage Location in advanced controls.\\\"\\\"\\\"\\n\\n    def test_storage_location_defaults_to_local(self):\\n        \\\"\\\"\\\"Test that storage_location input defaults to Local when component is dropped.\\\"\\\"\\\"\\n        storage_input = next(i for i in FileComponent.inputs if i.name == \\\"storage_location\\\")\\n        assert storage_input.value == [{\\\"name\\\": \\\"Local\\\", \\\"icon\\\": \\\"hard-drive\\\"}]\\n\\n    def test_storage_location_is_advanced(self):\\n        \\\"\\\"\\\"Test that storage_location is in advanced controls.\\\"\\\"\\\"\\n        storage_input = next(i for i in FileComponent.inputs if i.name == \\\"storage_location\\\")\\n        assert storage_input.advanced is True\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_file_component_image_processing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"70a720bdaea820f3a48efbed1b8f506db449b88a8116436b13eb80539c9e1601\",\"content\":\"\\\"\\\"\\\"Tests for FileComponent image processing with Docling.\\n\\nThese tests cover scenarios where:\\n- Images are processed but contain no extractable text (e.g., profile pictures)\\n- Docling returns empty doc_rows\\n- Storage path resolution for uploaded files\\n- Edge cases in error handling\\n\\\"\\\"\\\"\\n\\nimport json\\nfrom pathlib import Path\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.file import FileComponent\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\n\\nclass TestDoclingEmptyTextExtraction:\\n    \\\"\\\"\\\"Tests for handling images/documents with no extractable text.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_process_docling_empty_doc_rows_returns_placeholder(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test that empty doc_rows from Docling creates placeholder data instead of error.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        # Use tmp_path for secure temporary file references\\n        test_file = tmp_path / \\\"profile-pic.png\\\"\\n        test_file.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n\\n        # Mock Docling returning SUCCESS but with empty texts (like a profile picture)\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"structured\\\",\\n            \\\"doc\\\": [],  # Empty - no text extracted from image\\n            \\\"meta\\\": {\\\"file_path\\\": str(test_file)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(str(test_file))\\n\\n        assert result is not None\\n        assert result.data[\\\"doc\\\"] == []\\n        # The subprocess returns the raw result; processing happens in process_files\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_process_files_handles_empty_doc_rows(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test that process_files correctly handles empty doc_rows from Docling.\\\"\\\"\\\"\\n        # Create a test image file\\n        test_image = tmp_path / \\\"test_image.png\\\"\\n        test_image.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)  # Minimal PNG header\\n\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        component = FileComponent()\\n        component.advanced_mode = True\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n        component.silent_errors = False\\n\\n        # Mock Docling returning empty doc rows\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"structured\\\",\\n            \\\"doc\\\": [],\\n            \\\"meta\\\": {\\\"file_path\\\": str(test_image)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        # Create BaseFile mock\\n        from lfx.base.data.base_file import BaseFileComponent\\n\\n        base_file = BaseFileComponent.BaseFile(\\n            data=Data(data={\\\"file_path\\\": str(test_image)}),\\n            path=test_image,\\n            delete_after_processing=False,\\n        )\\n\\n        # Process the file\\n        result = component.process_files([base_file])\\n\\n        # Should return a list with one BaseFile containing placeholder data\\n        assert len(result) == 1\\n        assert result[0].data is not None\\n        assert len(result[0].data) == 1\\n\\n        # Check that placeholder text was created\\n        data_item = result[0].data[0]\\n        assert \\\"text\\\" in data_item.data or \\\"info\\\" in data_item.data\\n\\n    @patch(\\\"lfx.base.data.base_file.get_settings_service\\\")\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_load_files_dataframe_with_empty_text_image(\\n        self, mock_popen, mock_file_settings, mock_base_settings, tmp_path\\n    ):\\n        \\\"\\\"\\\"Test that load_files_dataframe doesn't error on images with no text.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_file_settings.return_value = mock_settings_instance\\n        mock_base_settings.return_value = mock_settings_instance\\n\\n        test_image = tmp_path / \\\"profile.png\\\"\\n        test_image.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.path = [str(test_image)]\\n        component.advanced_mode = True\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n        component.silent_errors = False\\n        component.use_multithreading = False\\n        component.concurrency_multithreading = 1\\n        component.delete_server_file_after_processing = False\\n        component.ignore_unsupported_extensions = True\\n        component.ignore_unspecified_files = False\\n        component.separator = \\\"\\\\n\\\\n\\\"\\n\\n        # Mock successful Docling processing with empty text\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"structured\\\",\\n            \\\"doc\\\": [],\\n            \\\"meta\\\": {\\\"file_path\\\": str(test_image)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        # This should NOT raise an error\\n        result = component.load_files_dataframe()\\n\\n        assert isinstance(result, DataFrame)\\n        # DataFrame should not be empty - it should have placeholder data\\n        assert not result.empty, \\\"DataFrame should contain placeholder data for image without text\\\"\\n\\n    @patch(\\\"lfx.base.data.base_file.get_settings_service\\\")\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_load_files_markdown_with_empty_text_image(\\n        self, mock_popen, mock_file_settings, mock_base_settings, tmp_path\\n    ):\\n        \\\"\\\"\\\"Test that load_files_markdown returns placeholder message for images with no text.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_file_settings.return_value = mock_settings_instance\\n        mock_base_settings.return_value = mock_settings_instance\\n\\n        test_image = tmp_path / \\\"profile.png\\\"\\n        test_image.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.path = [str(test_image)]\\n        component.advanced_mode = True\\n        component.markdown = True\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n        component.silent_errors = False\\n        component.use_multithreading = False\\n        component.concurrency_multithreading = 1\\n        component.delete_server_file_after_processing = False\\n        component.ignore_unsupported_extensions = True\\n        component.ignore_unspecified_files = False\\n        component.separator = \\\"\\\\n\\\\n\\\"\\n\\n        # Mock successful Docling processing with empty text\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"markdown\\\",\\n            \\\"text\\\": \\\"\\\",  # Empty markdown\\n            \\\"meta\\\": {\\\"file_path\\\": str(test_image)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        # This should NOT raise an error\\n        result = component.load_files_markdown()\\n\\n        assert result is not None\\n        assert hasattr(result, \\\"text\\\")\\n        # Should have some placeholder text, not empty\\n\\n\\nclass TestDoclingSubprocessErrors:\\n    \\\"\\\"\\\"Tests for error handling in Docling subprocess.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_docling_conversion_failure(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test handling of Docling conversion failure.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        test_file = tmp_path / \\\"bad_file.xyz\\\"\\n        test_file.write_bytes(b\\\"invalid content\\\")\\n\\n        component = FileComponent()\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n\\n        mock_result = {\\n            \\\"ok\\\": False,\\n            \\\"error\\\": \\\"Docling conversion failed: unsupported format\\\",\\n            \\\"meta\\\": {\\\"file_path\\\": str(test_file)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(str(test_file))\\n\\n        assert result is not None\\n        assert \\\"error\\\" in result.data\\n        assert \\\"Docling conversion failed\\\" in result.data[\\\"error\\\"]\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_docling_subprocess_crash(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test handling of Docling subprocess crash (no output).\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        test_file = tmp_path / \\\"crash.pdf\\\"\\n        test_file.write_bytes(b\\\"%PDF-1.4 test\\\")\\n\\n        component = FileComponent()\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (b\\\"\\\", b\\\"Segmentation fault\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(str(test_file))\\n\\n        assert result is not None\\n        assert \\\"error\\\" in result.data\\n        assert \\\"Segmentation fault\\\" in result.data[\\\"error\\\"] or \\\"no output\\\" in result.data[\\\"error\\\"].lower()\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_docling_invalid_json_output(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test handling of invalid JSON from Docling subprocess.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        test_file = tmp_path / \\\"test.pdf\\\"\\n        test_file.write_bytes(b\\\"%PDF-1.4 test\\\")\\n\\n        component = FileComponent()\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (b\\\"not valid json {{{\\\", b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        result = component._process_docling_in_subprocess(str(test_file))\\n\\n        assert result is not None\\n        assert \\\"error\\\" in result.data\\n        assert \\\"Invalid JSON\\\" in result.data[\\\"error\\\"]\\n\\n\\nclass TestStoragePathResolution:\\n    \\\"\\\"\\\"Tests for storage path resolution (flow_id/filename format).\\\"\\\"\\\"\\n\\n    def test_is_storage_path_format(self):\\n        \\\"\\\"\\\"Test detection of storage path format.\\\"\\\"\\\"\\n        # Test storage path format (flow_id/filename)\\n        storage_path = \\\"b2eff18f-31e6-41e7-89c3-65005504ab69/profile-pic.png\\\"\\n        assert \\\"/\\\" in storage_path\\n        assert not Path(storage_path).is_absolute()\\n\\n        # Test absolute path is not storage format\\n        absolute_path = \\\"/absolute/path/file.png\\\"\\n        assert Path(absolute_path).is_absolute()\\n\\n        # Test simple filename is not storage format\\n        simple_file = \\\"simple_file.png\\\"\\n        assert \\\"/\\\" not in simple_file\\n\\n    @patch(\\\"lfx.custom.custom_component.custom_component.get_storage_service\\\")\\n    @patch(\\\"lfx.base.data.base_file.get_settings_service\\\")\\n    def test_validate_and_resolve_paths_uses_storage_service(self, mock_settings, mock_storage, tmp_path):\\n        \\\"\\\"\\\"Test that storage paths are resolved using storage service.\\n\\n        This test currently fails because the path resolution doesn't properly\\n        use the storage service's get_full_path for paths in flow_id/filename format.\\n        \\\"\\\"\\\"\\n        # Create a test file in a mock storage location\\n        storage_dir = tmp_path / \\\"storage\\\"\\n        flow_dir = storage_dir / \\\"flow123\\\"\\n        flow_dir.mkdir(parents=True)\\n        test_file = flow_dir / \\\"document.pdf\\\"\\n        test_file.write_bytes(b\\\"%PDF-1.4 test\\\")\\n\\n        # Mock settings for local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        # Mock storage service\\n        mock_storage_instance = MagicMock()\\n        mock_storage_instance.build_full_path.return_value = str(test_file)\\n        mock_storage.return_value = mock_storage_instance\\n\\n        # Use FileComponent instead of abstract BaseFileComponent\\n        component = FileComponent()\\n        component.path = [\\\"flow123/document.pdf\\\"]\\n        component.silent_errors = False\\n        component.delete_server_file_after_processing = False\\n        component.ignore_unspecified_files = False\\n\\n        # Should resolve the path using storage service\\n        files = component._validate_and_resolve_paths()\\n\\n        assert len(files) == 1\\n        assert files[0].path == test_file\\n\\n\\nclass TestFileNotFoundHandling:\\n    \\\"\\\"\\\"Tests for handling of missing files.\\\"\\\"\\\"\\n\\n    def test_missing_file_raises_clear_error(self, tmp_path):\\n        \\\"\\\"\\\"Test that missing files raise a clear error message.\\\"\\\"\\\"\\n        # Use FileComponent instead of abstract BaseFileComponent\\n        component = FileComponent()\\n        component.path = [str(tmp_path / \\\"nonexistent_file.txt\\\")]\\n        component.silent_errors = False\\n        component.delete_server_file_after_processing = False\\n        component.ignore_unspecified_files = False\\n\\n        with pytest.raises(ValueError, match=r\\\"[Ff]ile.*not found|[Nn]ot found\\\"):\\n            component._validate_and_resolve_paths()\\n\\n    @pytest.mark.xfail(reason=\\\"Silent mode should skip missing files but currently adds them anyway\\\")\\n    def test_missing_file_silent_mode(self, tmp_path):\\n        \\\"\\\"\\\"Test that missing files are skipped in silent mode.\\n\\n        This test currently fails because silent_errors=True should skip\\n        missing files, but the current implementation still adds them to the list.\\n        \\\"\\\"\\\"\\n        # Use FileComponent instead of abstract BaseFileComponent\\n        component = FileComponent()\\n        component.path = [str(tmp_path / \\\"nonexistent_file.txt\\\")]\\n        component.silent_errors = True\\n        component.delete_server_file_after_processing = False\\n        component.ignore_unspecified_files = False\\n\\n        # Should not raise, should return empty list\\n        files = component._validate_and_resolve_paths()\\n        assert files == []\\n\\n\\nclass TestDataFrameEmptyHandling:\\n    \\\"\\\"\\\"Tests for DataFrame empty state handling.\\\"\\\"\\\"\\n\\n    def test_dataframe_with_empty_dict_is_empty(self):\\n        \\\"\\\"\\\"Test that DataFrame([{}]) is considered empty.\\\"\\\"\\\"\\n        df = DataFrame([{}])\\n        assert df.empty, \\\"DataFrame with single empty dict should be empty\\\"\\n\\n    def test_dataframe_with_placeholder_data_is_not_empty(self):\\n        \\\"\\\"\\\"Test that DataFrame with placeholder data is not empty.\\\"\\\"\\\"\\n        df = DataFrame(\\n            [\\n                {\\n                    \\\"file_path\\\": \\\"/some/path.png\\\",\\n                    \\\"text\\\": \\\"(No text content extracted from image)\\\",\\n                    \\\"info\\\": \\\"Image processed successfully\\\",\\n                }\\n            ]\\n        )\\n        assert not df.empty, \\\"DataFrame with placeholder data should not be empty\\\"\\n        assert \\\"text\\\" in df.columns\\n\\n    def test_dataframe_with_empty_text_is_not_empty(self):\\n        \\\"\\\"\\\"Test that DataFrame with empty string text is not empty.\\\"\\\"\\\"\\n        df = DataFrame(\\n            [\\n                {\\n                    \\\"file_path\\\": \\\"/some/path.png\\\",\\n                    \\\"text\\\": \\\"\\\",\\n                }\\n            ]\\n        )\\n        assert not df.empty, \\\"DataFrame with empty text string should not be empty\\\"\\n\\n\\nclass TestImageFileTypes:\\n    \\\"\\\"\\\"Tests for different image file types.\\\"\\\"\\\"\\n\\n    @pytest.mark.parametrize(\\\"extension\\\", [\\\"png\\\", \\\"jpg\\\", \\\"jpeg\\\", \\\"bmp\\\", \\\"tiff\\\", \\\"webp\\\"])\\n    def test_image_extensions_are_docling_compatible(self, extension):\\n        \\\"\\\"\\\"Test that image extensions are recognized as Docling-compatible.\\\"\\\"\\\"\\n        component = FileComponent()\\n        assert component._is_docling_compatible(f\\\"/path/to/image.{extension}\\\")\\n\\n    @pytest.mark.parametrize(\\\"extension\\\", [\\\"png\\\", \\\"jpg\\\", \\\"jpeg\\\", \\\"bmp\\\", \\\"tiff\\\", \\\"webp\\\"])\\n    def test_image_extensions_require_advanced_mode(self, extension):\\n        \\\"\\\"\\\"Test that image extensions require advanced mode.\\\"\\\"\\\"\\n        component = FileComponent()\\n        # These extensions should be in DOCLING_ONLY_EXTENSIONS\\n        assert extension in component.DOCLING_ONLY_EXTENSIONS or extension in [\\\"jpeg\\\"]\\n\\n\\nclass TestProcessFilesEdgeCases:\\n    \\\"\\\"\\\"Edge case tests for process_files method.\\\"\\\"\\\"\\n\\n    def test_process_files_empty_list_raises_error(self):\\n        \\\"\\\"\\\"Test that processing empty file list raises ValueError.\\\"\\\"\\\"\\n        component = FileComponent()\\n        component.advanced_mode = True\\n\\n        with pytest.raises(ValueError, match=\\\"No files to process\\\"):\\n            component.process_files([])\\n\\n    def test_process_files_docling_only_extension_without_advanced_mode(\\n        self,\\n        tmp_path,\\n    ):\\n        \\\"\\\"\\\"Test that Docling-only extensions require advanced mode.\\\"\\\"\\\"\\n        test_image = tmp_path / \\\"test.png\\\"\\n        test_image.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.advanced_mode = False  # Disabled\\n        component.silent_errors = False\\n\\n        from lfx.base.data.base_file import BaseFileComponent\\n\\n        base_file = BaseFileComponent.BaseFile(\\n            data=Data(data={\\\"file_path\\\": str(test_image)}),\\n            path=test_image,\\n            delete_after_processing=False,\\n        )\\n\\n        with pytest.raises(ValueError, match=r\\\"requires.*Advanced Parser\\\"):\\n            component.process_files([base_file])\\n\\n\\nclass TestLoadFilesHelperValidation:\\n    \\\"\\\"\\\"Tests for load_files_helper validation logic.\\\"\\\"\\\"\\n\\n    def test_load_files_helper_empty_dataframe_raises_error(self):\\n        \\\"\\\"\\\"Test that empty DataFrame raises descriptive error.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        with (\\n            patch.object(component, \\\"load_files\\\", return_value=DataFrame()),\\n            pytest.raises(ValueError, match=\\\"Could not extract content\\\"),\\n        ):\\n            component.load_files_helper()\\n\\n    def test_load_files_helper_with_error_column(self):\\n        \\\"\\\"\\\"Test that error column is checked and raised.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        error_df = DataFrame(\\n            [\\n                {\\n                    \\\"error\\\": \\\"File processing failed\\\",\\n                    \\\"file_path\\\": \\\"/some/path\\\",\\n                }\\n            ]\\n        )\\n\\n        with (\\n            patch.object(component, \\\"load_files\\\", return_value=error_df),\\n            pytest.raises(ValueError, match=\\\"File processing failed\\\"),\\n        ):\\n            component.load_files_helper()\\n\\n    def test_load_files_helper_with_error_and_text(self):\\n        \\\"\\\"\\\"Test that error is not raised if text column exists with error.\\\"\\\"\\\"\\n        component = FileComponent()\\n\\n        # If we have both error and text, should not raise\\n        df_with_both = DataFrame(\\n            [\\n                {\\n                    \\\"error\\\": \\\"Some warning\\\",\\n                    \\\"text\\\": \\\"Actual content\\\",\\n                    \\\"file_path\\\": \\\"/some/path\\\",\\n                }\\n            ]\\n        )\\n\\n        with patch.object(component, \\\"load_files\\\", return_value=df_with_both):\\n            result = component.load_files_helper()\\n            assert not result.empty\\n\\n\\nclass TestImageContentTypeValidation:\\n    \\\"\\\"\\\"Tests for validating that image content matches file extension.\\\"\\\"\\\"\\n\\n    def test_valid_png_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that a valid PNG file passes validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a valid PNG file (minimal PNG header)\\n        png_file = tmp_path / \\\"valid.png\\\"\\n        png_file.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(png_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_valid_jpeg_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that a valid JPEG file passes validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a valid JPEG file (JPEG magic bytes)\\n        jpeg_file = tmp_path / \\\"valid.jpg\\\"\\n        jpeg_file.write_bytes(b\\\"\\\\xff\\\\xd8\\\\xff\\\\xe0\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(jpeg_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_jpeg_saved_as_png_fails(self, tmp_path):\\n        \\\"\\\"\\\"Test that a JPEG file saved with .png extension is rejected.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a JPEG file but with .png extension\\n        mismatched_file = tmp_path / \\\"actually_jpeg.png\\\"\\n        mismatched_file.write_bytes(b\\\"\\\\xff\\\\xd8\\\\xff\\\\xe0\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(mismatched_file))\\n        assert is_valid is False\\n        assert error is not None\\n        assert \\\"JPEG\\\" in error\\n        assert \\\".png\\\" in error\\n\\n    def test_png_saved_as_jpg_fails(self, tmp_path):\\n        \\\"\\\"\\\"Test that a PNG file saved with .jpg extension is rejected.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a PNG file but with .jpg extension\\n        mismatched_file = tmp_path / \\\"actually_png.jpg\\\"\\n        mismatched_file.write_bytes(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(mismatched_file))\\n        assert is_valid is False\\n        assert error is not None\\n        assert \\\"PNG\\\" in error\\n        assert \\\".jpg\\\" in error\\n\\n    def test_non_image_file_passes(self, tmp_path):\\n        \\\"\\\"\\\"Test that non-image files skip validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a text file\\n        text_file = tmp_path / \\\"document.txt\\\"\\n        text_file.write_text(\\\"Hello, world!\\\")\\n\\n        is_valid, error = validate_image_content_type(str(text_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_unrecognized_content_fails(self, tmp_path):\\n        \\\"\\\"\\\"Test that a file with unrecognized content is rejected.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a file with .png extension but random content\\n        # This should fail - it's not a valid image\\n        unknown_file = tmp_path / \\\"unknown.png\\\"\\n        unknown_file.write_bytes(b\\\"this is not a real image at all\\\")\\n\\n        is_valid, error = validate_image_content_type(str(unknown_file))\\n        assert is_valid is False\\n        assert error is not None\\n        assert \\\"not a valid image format\\\" in error\\n\\n    def test_valid_gif_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that a valid GIF file passes validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a valid GIF file\\n        gif_file = tmp_path / \\\"valid.gif\\\"\\n        gif_file.write_bytes(b\\\"GIF89a\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(gif_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_valid_webp_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that a valid WebP file passes validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a valid WebP file (RIFF....WEBP header)\\n        webp_file = tmp_path / \\\"valid.webp\\\"\\n        webp_file.write_bytes(b\\\"RIFF\\\\x00\\\\x00\\\\x00\\\\x00WEBP\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(webp_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_valid_bmp_file(self, tmp_path):\\n        \\\"\\\"\\\"Test that a valid BMP file passes validation.\\\"\\\"\\\"\\n        from lfx.base.data.storage_utils import validate_image_content_type\\n\\n        # Create a valid BMP file\\n        bmp_file = tmp_path / \\\"valid.bmp\\\"\\n        bmp_file.write_bytes(b\\\"BM\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        is_valid, error = validate_image_content_type(str(bmp_file))\\n        assert is_valid is True\\n        assert error is None\\n\\n    def test_process_files_rejects_mismatched_image(self, tmp_path):\\n        \\\"\\\"\\\"Test that process_files rejects images with content/extension mismatch.\\\"\\\"\\\"\\n        # Create a JPEG file but with .png extension\\n        mismatched_file = tmp_path / \\\"fake.png\\\"\\n        mismatched_file.write_bytes(b\\\"\\\\xff\\\\xd8\\\\xff\\\\xe0\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.advanced_mode = True\\n        component.silent_errors = False\\n\\n        from lfx.base.data.base_file import BaseFileComponent\\n\\n        base_file = BaseFileComponent.BaseFile(\\n            data=Data(data={\\\"file_path\\\": str(mismatched_file)}),\\n            path=mismatched_file,\\n            delete_after_processing=False,\\n        )\\n\\n        with pytest.raises(ValueError, match=r\\\"\\\\.png.*JPEG\\\"):\\n            component.process_files([base_file])\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.file.get_settings_service\\\")\\n    @patch(\\\"subprocess.Popen\\\")\\n    def test_process_files_silent_mode_skips_mismatched_image(self, mock_popen, mock_settings, tmp_path):\\n        \\\"\\\"\\\"Test that process_files in silent mode logs but doesn't raise for mismatched images.\\\"\\\"\\\"\\n        # Mock settings service to return local storage\\n        mock_settings_instance = MagicMock()\\n        mock_settings_instance.settings.storage_type = \\\"local\\\"\\n        mock_settings.return_value = mock_settings_instance\\n\\n        # Create a JPEG file but with .png extension\\n        mismatched_file = tmp_path / \\\"fake.png\\\"\\n        mismatched_file.write_bytes(b\\\"\\\\xff\\\\xd8\\\\xff\\\\xe0\\\" + b\\\"\\\\x00\\\" * 100)\\n\\n        component = FileComponent()\\n        component.advanced_mode = True\\n        component.silent_errors = True\\n        component.markdown = False\\n        component.md_image_placeholder = \\\"<!-- image -->\\\"\\n        component.md_page_break_placeholder = \\\"\\\"\\n        component.pipeline = \\\"standard\\\"\\n        component.ocr_engine = \\\"easyocr\\\"\\n        component.use_multithreading = False\\n        component.concurrency_multithreading = 1\\n\\n        # Mock Docling to return success (won't be called if validation fails)\\n        mock_result = {\\n            \\\"ok\\\": True,\\n            \\\"mode\\\": \\\"structured\\\",\\n            \\\"doc\\\": [],\\n            \\\"meta\\\": {\\\"file_path\\\": str(mismatched_file)},\\n        }\\n        mock_proc = MagicMock()\\n        mock_proc.communicate.return_value = (json.dumps(mock_result).encode(\\\"utf-8\\\"), b\\\"\\\")\\n        mock_popen.return_value = mock_proc\\n\\n        from lfx.base.data.base_file import BaseFileComponent\\n\\n        base_file = BaseFileComponent.BaseFile(\\n            data=Data(data={\\\"file_path\\\": str(mismatched_file)}),\\n            path=mismatched_file,\\n            delete_after_processing=False,\\n        )\\n\\n        # Should not raise in silent mode\\n        result = component.process_files([base_file])\\n        # Result may be empty or contain data, but no exception should be raised\\n        assert isinstance(result, list)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_ingestion.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0eee4ae95ef55ff4b7d39cc73df81f10def2316d854664632d280c94a71e36f7\",\"content\":\"import hashlib\\nfrom unittest.mock import MagicMock, patch\\n\\nimport numpy as np\\nimport pytest\\nfrom langflow.schema.data import Data\\nfrom langflow.schema.dataframe import DataFrame\\nfrom langflow.schema.message import Message\\nfrom lfx.base.knowledge_bases import get_knowledge_bases\\nfrom lfx.components.files_and_knowledge import KnowledgeIngestionComponent\\n\\nfrom tests.base import ComponentTestBaseWithClient\\n\\n\\nclass TestKnowledgeIngestionComponent(ComponentTestBaseWithClient):\\n    @pytest.fixture\\n    def component_class(self):\\n        \\\"\\\"\\\"Return the component class to test.\\\"\\\"\\\"\\n        return KnowledgeIngestionComponent\\n\\n    @pytest.fixture(autouse=True)\\n    def mock_knowledge_base_path(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Pin the KB root at a fresh tmp dir for every test.\\n\\n        Local-Chroma path resolution reads ``knowledge_bases_dir`` live via\\n        ``KBStorageHelper.get_root_path``, so the setting is what has to move.\\n        \\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service\\n\\n        monkeypatch.setattr(get_settings_service().settings, \\\"knowledge_bases_dir\\\", str(tmp_path))\\n        with patch(\\\"lfx.components.files_and_knowledge._kb_paths._KNOWLEDGE_BASES_ROOT_PATH\\\", tmp_path):\\n            yield\\n\\n    @pytest.fixture\\n    async def default_kwargs(self, tmp_path, active_user):\\n        \\\"\\\"\\\"Return default kwargs for component instantiation.\\\"\\\"\\\"\\n        # Create a sample DataFrame\\n        data_df = DataFrame(\\n            {\\\"text\\\": [\\\"Sample text 1\\\", \\\"Sample text 2\\\"], \\\"title\\\": [\\\"Title 1\\\", \\\"Title 2\\\"], \\\"category\\\": [\\\"cat1\\\", \\\"cat2\\\"]}\\n        )\\n\\n        # Create column configuration\\n        column_config = [\\n            {\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": True, \\\"identifier\\\": False},\\n            {\\\"column_name\\\": \\\"title\\\", \\\"vectorize\\\": False, \\\"identifier\\\": False},\\n            {\\\"column_name\\\": \\\"category\\\", \\\"vectorize\\\": False, \\\"identifier\\\": True},\\n        ]\\n\\n        # Create knowledge base directory\\n        kb_name = \\\"test_kb\\\"\\n        kb_path = tmp_path / active_user.username / kb_name\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n\\n        # The ``knowledge_base`` row is what makes the KB exist and carries its\\n        # embedding config; the directory above is only where local-Chroma\\n        # vectors would land.\\n        from langflow.api.utils import knowledge_base_service\\n\\n        await knowledge_base_service.create_record(\\n            user_id=active_user.id,\\n            name=kb_name,\\n            model_selection={\\n                \\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n                \\\"provider\\\": \\\"HuggingFace\\\",\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": \\\"HuggingFaceEmbeddings\\\",\\n                    \\\"param_mapping\\\": {\\\"model\\\": \\\"model_name\\\"},\\n                },\\n            },\\n            chunk_size=1000,\\n        )\\n\\n        return {\\n            \\\"knowledge_base\\\": kb_name,\\n            \\\"input_df\\\": data_df,\\n            \\\"column_config\\\": column_config,\\n            \\\"chunk_size\\\": 1000,\\n            \\\"kb_root_path\\\": str(tmp_path),\\n            \\\"api_key\\\": None,\\n            \\\"allow_duplicates\\\": False,\\n            \\\"silent_errors\\\": False,\\n            \\\"_user_id\\\": active_user.id,\\n        }\\n\\n    @pytest.fixture\\n    def file_names_mapping(self):\\n        \\\"\\\"\\\"Return file names mapping for version testing.\\\"\\\"\\\"\\n        # This is a new component, so it doesn't exist in older versions\\n        return []\\n\\n    def test_validate_column_config_valid(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test column configuration validation with valid config.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n\\n        config_list = component._validate_column_config(data_df)\\n\\n        assert len(config_list) == 3\\n        assert config_list[0][\\\"column_name\\\"] == \\\"text\\\"\\n        assert config_list[0][\\\"vectorize\\\"] is True\\n\\n    def test_validate_column_config_invalid_column(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test column configuration validation with invalid column name.\\\"\\\"\\\"\\n        # Modify column config to include non-existent column\\n        invalid_config = [{\\\"column_name\\\": \\\"nonexistent\\\", \\\"vectorize\\\": True, \\\"identifier\\\": False}]\\n        default_kwargs[\\\"column_config\\\"] = invalid_config\\n\\n        # Instantiate the component with the modified config\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n\\n        # Should raise ValueError since column does not exist in DataFrame\\n        with pytest.raises(ValueError, match=\\\"Column 'nonexistent' not found in DataFrame\\\"):\\n            component._validate_column_config(data_df)\\n\\n    @pytest.mark.parametrize(\\\"knowledge_base\\\", [\\\"../../outside\\\", \\\"../victim/secret_kb\\\"])\\n    async def test_kb_path_rejects_paths_outside_the_current_user_directory(\\n        self, component_class, default_kwargs, knowledge_base\\n    ):\\n        from langflow.api.utils import knowledge_base_service\\n\\n        # Path resolution only runs once the backend resolves, so the traversing\\n        # name needs a row for the containment guard to be reachable at all.\\n        await knowledge_base_service.create_record(\\n            user_id=default_kwargs[\\\"_user_id\\\"],\\n            name=knowledge_base,\\n            model_selection={\\\"name\\\": \\\"m\\\", \\\"provider\\\": \\\"HuggingFace\\\"},\\n        )\\n        default_kwargs[\\\"knowledge_base\\\"] = knowledge_base\\n        component = component_class(**default_kwargs)\\n\\n        with pytest.raises(ValueError, match=\\\"KB path escapes root directory\\\"):\\n            await component._kb_path()\\n\\n    def test_new_knowledge_dialog_uses_provider_credentials(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test the create-knowledge dialog no longer exposes a redundant API key override.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        dialog_inputs = component.inputs[0].dialog_inputs[\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"]\\n        embedding_model_input = dialog_inputs[\\\"template\\\"][\\\"02_embedding_model\\\"]\\n        backend_input = dialog_inputs[\\\"template\\\"][\\\"03_knowledge_backend\\\"]\\n\\n        assert dialog_inputs[\\\"field_order\\\"] == [\\\"01_new_kb_name\\\", \\\"02_embedding_model\\\", \\\"03_knowledge_backend\\\"]\\n        assert \\\"03_api_key\\\" not in dialog_inputs[\\\"template\\\"]\\n        assert \\\"configured credentials\\\" in embedding_model_input.info\\n        assert backend_input.field_type.value == \\\"knowledge_backend\\\"\\n        assert backend_input.display_name == \\\"DB Provider\\\"\\n        # Default is empty so the frontend can populate it from the user's\\n        # configured active DB Provider on first render.\\n        assert backend_input.value == {}\\n\\n    def test_build_column_metadata(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test building column metadata.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n        config_list = default_kwargs[\\\"column_config\\\"]\\n\\n        metadata = component._build_column_metadata(config_list, data_df)\\n\\n        assert metadata[\\\"total_columns\\\"] == 3\\n        assert metadata[\\\"mapped_columns\\\"] == 3\\n        assert metadata[\\\"unmapped_columns\\\"] == 0\\n        assert len(metadata[\\\"columns\\\"]) == 3\\n        assert \\\"text\\\" in metadata[\\\"summary\\\"][\\\"vectorized_columns\\\"]\\n        assert \\\"category\\\" in metadata[\\\"summary\\\"][\\\"identifier_columns\\\"]\\n\\n    # Column Configuration cells hold real booleans when toggled, but a typed\\n    # cell (or a flow saved before the cell rendered as a toggle) keeps the raw\\n    # string, so every spelling the table can store must read the same way.\\n    @pytest.mark.parametrize(\\n        (\\\"raw\\\", \\\"expected\\\"),\\n        [\\n            (True, True),\\n            (\\\"True\\\", True),\\n            (\\\"true\\\", True),\\n            (\\\"TRUE\\\", True),\\n            (\\\" true \\\", True),\\n            (\\\"1\\\", True),\\n            (\\\"yes\\\", True),\\n            (False, False),\\n            (\\\"False\\\", False),\\n            (\\\"false\\\", False),\\n            (\\\"0\\\", False),\\n            (\\\"no\\\", False),\\n            (\\\"\\\", False),\\n            (None, False),\\n        ],\\n    )\\n    def test_build_column_metadata_reads_string_flags(self, component_class, default_kwargs, raw, expected):\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n        config_list = [{\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": raw, \\\"identifier\\\": raw}]\\n\\n        metadata = component._build_column_metadata(config_list, data_df)\\n\\n        assert metadata[\\\"columns\\\"] == [{\\\"name\\\": \\\"text\\\", \\\"vectorize\\\": expected, \\\"identifier\\\": expected}]\\n        assert metadata[\\\"summary\\\"] == {\\n            \\\"vectorized_columns\\\": [\\\"text\\\"] if expected else [],\\n            \\\"identifier_columns\\\": [\\\"text\\\"] if expected else [],\\n        }\\n\\n    async def test_typed_vectorize_flag_reaches_the_embedding(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"A Vectorize cell typed as ``\\\"true\\\"`` contributes to page content instead of flat metadata.\\\"\\\"\\\"\\n        data_df = DataFrame(\\n            {\\n                \\\"question\\\": [\\\"What is Langflow?\\\"],\\n                \\\"answer\\\": [\\\"A visual framework for building AI workflows\\\"],\\n                \\\"category\\\": [\\\"general\\\"],\\n                \\\"language\\\": [\\\"en\\\"],\\n            }\\n        )\\n        # The saved-flow shape: untouched cells stay booleans, typed cells are strings.\\n        default_kwargs[\\\"input_df\\\"] = data_df\\n        default_kwargs[\\\"column_config\\\"] = [\\n            {\\\"column_name\\\": \\\"question\\\", \\\"vectorize\\\": True, \\\"identifier\\\": \\\"true\\\"},\\n            {\\\"column_name\\\": \\\"answer\\\", \\\"vectorize\\\": \\\"true\\\", \\\"identifier\\\": \\\"false\\\"},\\n        ]\\n        component = component_class(**default_kwargs)\\n\\n        config_list = component._validate_column_config(data_df)\\n        metadata = component._build_column_metadata(config_list, data_df)\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.Chroma\\\") as mock_chroma:\\n            mock_chroma.return_value.get.return_value = {\\\"metadatas\\\": []}\\n            [data_obj] = await component._convert_df_to_data_objects(data_df, config_list)\\n\\n        assert metadata[\\\"summary\\\"] == {\\n            \\\"vectorized_columns\\\": [\\\"question\\\", \\\"answer\\\"],\\n            \\\"identifier_columns\\\": [\\\"question\\\"],\\n        }\\n        assert data_obj.data[\\\"text\\\"] == \\\"What is Langflow? A visual framework for building AI workflows\\\"\\n        assert \\\"answer\\\" not in data_obj.data\\n        assert data_obj.data[\\\"category\\\"] == \\\"general\\\"\\n        assert data_obj.data[\\\"language\\\"] == \\\"en\\\"\\n        # The identifier column alone keys the row.\\n        assert data_obj.data[\\\"_id\\\"] == hashlib.sha256(b\\\"What is Langflow?\\\").hexdigest()\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_new_kb_record_persists_boolean_column_flags(\\n        self, mock_get_embeddings, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"The KB row stores canonical booleans, so later readers never re-parse typed strings.\\\"\\\"\\\"\\n        from langflow.api.utils import knowledge_base_service\\n\\n        default_kwargs[\\\"column_config\\\"] = [\\n            {\\\"column_name\\\": \\\"question\\\", \\\"vectorize\\\": True, \\\"identifier\\\": \\\"true\\\"},\\n            {\\\"column_name\\\": \\\"answer\\\", \\\"vectorize\\\": \\\"true\\\", \\\"identifier\\\": \\\"false\\\"},\\n        ]\\n        component = component_class(**default_kwargs)\\n        mock_get_embeddings.return_value.embed_query.return_value = [0.1, 0.2, 0.3]\\n        field_value = {\\n            \\\"01_new_kb_name\\\": \\\"typed_flags_kb\\\",\\n            \\\"02_embedding_model\\\": [\\n                {\\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\", \\\"provider\\\": \\\"HuggingFace\\\", \\\"metadata\\\": {}}\\n            ],\\n            \\\"03_knowledge_backend\\\": {\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        }\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": None, \\\"options\\\": [], \\\"dialog_inputs\\\": {}}}\\n\\n        await component.update_build_config(build_config, field_value, \\\"knowledge_base\\\")\\n\\n        record = await knowledge_base_service.get_by_user_and_name(default_kwargs[\\\"_user_id\\\"], \\\"typed_flags_kb\\\")\\n        assert record is not None\\n        assert record.column_config == [\\n            {\\\"column_name\\\": \\\"question\\\", \\\"vectorize\\\": True, \\\"identifier\\\": True},\\n            {\\\"column_name\\\": \\\"answer\\\", \\\"vectorize\\\": True, \\\"identifier\\\": False},\\n        ]\\n        # The component's own input is left untouched.\\n        assert component.column_config[1][\\\"vectorize\\\"] == \\\"true\\\"\\n\\n    async def test_convert_df_to_data_objects(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test converting DataFrame to Data objects.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n        config_list = default_kwargs[\\\"column_config\\\"]\\n\\n        # Mock Chroma to avoid actual vector store operations\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.Chroma\\\") as mock_chroma:\\n            mock_chroma_instance = MagicMock()\\n            mock_chroma_instance.get.return_value = {\\\"metadatas\\\": []}\\n            mock_chroma.return_value = mock_chroma_instance\\n\\n            data_objects = await component._convert_df_to_data_objects(data_df, config_list)\\n\\n        assert len(data_objects) == 2\\n        assert all(isinstance(obj, Data) for obj in data_objects)\\n\\n        # Check first data object\\n        first_obj = data_objects[0]\\n        assert \\\"text\\\" in first_obj.data\\n        assert \\\"title\\\" in first_obj.data\\n        assert \\\"category\\\" in first_obj.data\\n        assert \\\"_id\\\" in first_obj.data\\n\\n    async def test_convert_df_to_data_objects_no_duplicates(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test converting DataFrame to Data objects with duplicate prevention.\\\"\\\"\\\"\\n        default_kwargs[\\\"allow_duplicates\\\"] = False\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n        config_list = default_kwargs[\\\"column_config\\\"]\\n\\n        # Mock Chroma with existing hash\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.Chroma\\\") as mock_chroma:\\n            # Simulate existing document with same hash\\n            existing_hash = \\\"some_existing_hash\\\"\\n            mock_chroma_instance = MagicMock()\\n            mock_chroma_instance.get.return_value = {\\\"metadatas\\\": [{\\\"_id\\\": existing_hash}]}\\n            mock_chroma.return_value = mock_chroma_instance\\n\\n            # Mock hashlib to return the existing hash for first row\\n            with patch(\\\"lfx.components.files_and_knowledge.knowledge.hashlib.sha256\\\") as mock_hash:\\n                mock_hash_obj = MagicMock()\\n                mock_hash_obj.hexdigest.side_effect = [existing_hash, \\\"different_hash\\\"]\\n                mock_hash.return_value = mock_hash_obj\\n\\n                data_objects = await component._convert_df_to_data_objects(data_df, config_list)\\n\\n        # Should only return one object (second row) since first is duplicate\\n        assert len(data_objects) == 1\\n\\n    def test_is_valid_collection_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test collection name validation.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        # Valid names\\n        assert component.is_valid_collection_name(\\\"valid_name\\\") is True\\n        assert component.is_valid_collection_name(\\\"valid-name\\\") is True\\n        assert component.is_valid_collection_name(\\\"ValidName123\\\") is True\\n        assert component.is_valid_collection_name(\\\"docs.v2\\\") is True\\n        assert component.is_valid_collection_name(\\\"a\\\" * 512) is True\\n\\n        # Invalid names\\n        assert component.is_valid_collection_name(\\\"ab\\\") is False  # Too short\\n        assert component.is_valid_collection_name(\\\"a\\\" * 513) is False  # Too long\\n        assert component.is_valid_collection_name(\\\"_invalid\\\") is False  # Starts with underscore\\n        assert component.is_valid_collection_name(\\\"invalid_\\\") is False  # Ends with underscore\\n        assert component.is_valid_collection_name(\\\"invalid@name\\\") is False  # Invalid character\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_build_kb_info_success(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test successful KB info building.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        mock_embedding_fn = MagicMock()\\n        mock_get_embeddings.return_value = mock_embedding_fn\\n\\n        # Mock vector store creation\\n        with patch.object(component, \\\"_create_vector_store\\\"):\\n            result = await component.build_kb_info()\\n\\n        assert isinstance(result, Data)\\n        assert \\\"kb_id\\\" in result.data\\n        assert \\\"kb_name\\\" in result.data\\n        assert \\\"rows\\\" in result.data\\n        assert result.data[\\\"rows\\\"] == 2\\n\\n    async def test_get_knowledge_bases(self, tmp_path, active_user):\\n        \\\"\\\"\\\"Test getting list of knowledge bases.\\\"\\\"\\\"\\n        # Create additional test directories\\n        from langflow.api.utils import knowledge_base_service\\n\\n        # Rows are what the dropdown lists; a bare directory is invisible.\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb1\\\")\\n        await knowledge_base_service.create_record(user_id=active_user.id, name=\\\"kb2\\\")\\n        (tmp_path / active_user.username / \\\"dir_without_row\\\").mkdir(parents=True, exist_ok=True)\\n\\n        kb_list = await get_knowledge_bases(user_id=active_user.id)\\n\\n        assert \\\"test_kb\\\" in kb_list\\n        assert \\\"kb1\\\" in kb_list\\n        assert \\\"kb2\\\" in kb_list\\n        assert \\\"dir_without_row\\\" not in kb_list\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_update_build_config_new_kb(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test updating build config for new knowledge base creation.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": None, \\\"options\\\": [], \\\"dialog_inputs\\\": {}}}\\n\\n        model_selection = [\\n            {\\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\", \\\"provider\\\": \\\"HuggingFace\\\", \\\"metadata\\\": {}}\\n        ]\\n        field_value = {\\n            \\\"01_new_kb_name\\\": \\\"new_test_kb\\\",\\n            \\\"02_embedding_model\\\": model_selection,\\n            \\\"03_knowledge_backend\\\": {\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        }\\n\\n        # Mock embedding validation\\n        mock_embeddings = MagicMock()\\n        mock_embeddings.embed_query.return_value = [0.1, 0.2, 0.3]\\n        mock_get_embeddings.return_value = mock_embeddings\\n\\n        with patch.object(\\n            component,\\n            \\\"_create_knowledge_base_record\\\",\\n            wraps=component._create_knowledge_base_record,\\n        ) as mock_create_record:\\n            result = await component.update_build_config(build_config, field_value, \\\"knowledge_base\\\")\\n\\n        assert result[\\\"knowledge_base\\\"][\\\"value\\\"] == \\\"new_test_kb\\\"\\n        assert \\\"new_test_kb\\\" in result[\\\"knowledge_base\\\"][\\\"options\\\"]\\n        assert \\\"api_key\\\" not in mock_get_embeddings.call_args.kwargs\\n        assert mock_create_record.call_args.kwargs[\\\"backend_type\\\"] == \\\"chroma\\\"\\n        assert mock_create_record.call_args.kwargs[\\\"backend_config\\\"] == {}\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_update_build_config_new_kb_persists_backend_selection(\\n        self, mock_get_embeddings, component_class, default_kwargs\\n    ):\\n        \\\"\\\"\\\"Test creating knowledge from the component dialog preserves the selected backend.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": None, \\\"options\\\": [], \\\"dialog_inputs\\\": {}}}\\n        model_selection = [\\n            {\\\"name\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\", \\\"provider\\\": \\\"HuggingFace\\\", \\\"metadata\\\": {}}\\n        ]\\n        field_value = {\\n            \\\"01_new_kb_name\\\": \\\"opensearch_test_kb\\\",\\n            \\\"02_embedding_model\\\": model_selection,\\n            \\\"03_knowledge_backend\\\": {\\n                \\\"backend_type\\\": \\\"opensearch\\\",\\n                \\\"backend_config\\\": {\\n                    \\\"url_variable\\\": \\\"OPENSEARCH_URL\\\",\\n                    \\\"index_name\\\": \\\"kb-index\\\",\\n                    \\\"vector_field\\\": \\\"embedding\\\",\\n                    \\\"text_field\\\": \\\"content\\\",\\n                },\\n            },\\n        }\\n\\n        mock_embeddings = MagicMock()\\n        mock_embeddings.embed_query.return_value = [0.1, 0.2, 0.3]\\n        mock_get_embeddings.return_value = mock_embeddings\\n\\n        with patch.object(component, \\\"_create_knowledge_base_record\\\") as mock_create_record:\\n            await component.update_build_config(build_config, field_value, \\\"knowledge_base\\\")\\n\\n        assert mock_create_record.call_args.kwargs[\\\"backend_type\\\"] == \\\"opensearch\\\"\\n        assert mock_create_record.call_args.kwargs[\\\"backend_config\\\"][\\\"index_name\\\"] == \\\"kb-index\\\"\\n        assert mock_create_record.call_args.kwargs[\\\"backend_config\\\"][\\\"text_field\\\"] == \\\"content\\\"\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_build_kb_info_with_message_input(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that Message input is accepted and converted to DataFrame.\\\"\\\"\\\"\\n        # Replace the DataFrame input with a Message\\n        default_kwargs[\\\"input_df\\\"] = Message(text=\\\"Sample text 1\\\")\\n        default_kwargs[\\\"column_config\\\"] = [\\n            {\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": True, \\\"identifier\\\": True},\\n        ]\\n        component = component_class(**default_kwargs)\\n\\n        mock_embedding_fn = MagicMock()\\n        mock_get_embeddings.return_value = mock_embedding_fn\\n\\n        with patch.object(component, \\\"_create_vector_store\\\"):\\n            result = await component.build_kb_info()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"rows\\\"] == 1\\n        assert result.data[\\\"kb_name\\\"] == \\\"test_kb\\\"\\n\\n    async def test_update_build_config_invalid_kb_name(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test updating build config with invalid KB name.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        build_config = {\\\"knowledge_base\\\": {\\\"value\\\": None, \\\"options\\\": []}}\\n        field_value = {\\n            \\\"01_new_kb_name\\\": \\\"invalid@name\\\",  # Invalid character\\n            \\\"02_embedding_model\\\": \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n            \\\"03_knowledge_backend\\\": {\\\"backend_type\\\": \\\"chroma\\\", \\\"backend_config\\\": {}},\\n        }\\n\\n        with pytest.raises(ValueError, match=\\\"Chroma naming rules\\\"):\\n            await component.update_build_config(build_config, field_value, \\\"knowledge_base\\\")\\n\\n    @patch(\\\"lfx.components.files_and_knowledge.knowledge.get_embeddings\\\")\\n    async def test_build_kb_info_with_new_format_metadata(self, mock_get_embeddings, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that build_kb_info uses ``model_selection`` straight off the KB row.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n        mock_get_embeddings.return_value = MagicMock()\\n\\n        with patch.object(component, \\\"_create_vector_store\\\"):\\n            result = await component.build_kb_info()\\n\\n        assert isinstance(result, Data)\\n        assert result.data[\\\"rows\\\"] == 2\\n\\n        # Verify get_embeddings was called with the full model_selection from the new-format metadata,\\n        # not a minimal reconstructed dict from the backward-compat path.\\n        call_kwargs = mock_get_embeddings.call_args\\n        passed_model = call_kwargs.kwargs.get(\\\"model\\\") or call_kwargs.args[0]\\n        assert isinstance(passed_model, list)\\n        assert passed_model[0][\\\"name\\\"] == \\\"sentence-transformers/all-MiniLM-L6-v2\\\"\\n        assert passed_model[0][\\\"provider\\\"] == \\\"HuggingFace\\\"\\n\\n    async def test_convert_df_to_data_objects_allow_duplicates(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that allow_duplicates=True returns all rows even when their hashes already exist.\\\"\\\"\\\"\\n        default_kwargs[\\\"allow_duplicates\\\"] = True\\n        component = component_class(**default_kwargs)\\n        data_df = default_kwargs[\\\"input_df\\\"]\\n        config_list = default_kwargs[\\\"column_config\\\"]\\n\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.Chroma\\\") as mock_chroma:\\n            mock_chroma_instance = MagicMock()\\n            # Simulate all rows as already-existing duplicates in the store\\n            mock_chroma_instance.get.return_value = {\\\"metadatas\\\": [{\\\"_id\\\": \\\"hash_1\\\"}, {\\\"_id\\\": \\\"hash_2\\\"}]}\\n            mock_chroma.return_value = mock_chroma_instance\\n\\n            with patch(\\\"lfx.components.files_and_knowledge.knowledge.hashlib.sha256\\\") as mock_hash:\\n                mock_hash_obj = MagicMock()\\n                # Return hashes that match the existing IDs above\\n                mock_hash_obj.hexdigest.side_effect = [\\\"hash_1\\\", \\\"hash_2\\\"]\\n                mock_hash.return_value = mock_hash_obj\\n\\n                data_objects = await component._convert_df_to_data_objects(data_df, config_list)\\n\\n        # All rows should be included \u2014 duplicates are allowed\\n        assert len(data_objects) == 2\\n\\n    async def test_build_kb_info_without_a_kb_row_raises_error(\\n        self, component_class, default_kwargs, tmp_path, active_user\\n    ):\\n        \\\"\\\"\\\"A KB with no ``knowledge_base`` row has no embedding config to ingest with.\\\"\\\"\\\"\\n        (tmp_path / active_user.username / \\\"rowless_kb\\\").mkdir(parents=True, exist_ok=True)\\n        default_kwargs[\\\"knowledge_base\\\"] = \\\"rowless_kb\\\"\\n        component = component_class(**default_kwargs)\\n\\n        with pytest.raises(RuntimeError, match=\\\"No embedding model configuration found\\\"):\\n            await component.build_kb_info()\\n\\n    def test_scalar_notna_with_scalar_values(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test _scalar_notna returns correct results for scalar values.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        assert component._scalar_notna(\\\"hello\\\") is True\\n        assert component._scalar_notna(42) is True\\n        assert component._scalar_notna(0) is True\\n        assert component._scalar_notna(\\\"\\\") is True\\n        assert component._scalar_notna(None) is False\\n        assert component._scalar_notna(float(\\\"nan\\\")) is False\\n\\n    def test_scalar_notna_with_numpy_arrays(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test _scalar_notna handles numpy arrays without raising ambiguous truth value errors.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        # Empty array \u2014 should be falsy (no valid data)\\n        assert not component._scalar_notna(np.array([]))\\n\\n        # Array with valid values \u2014 should be truthy\\n        assert component._scalar_notna(np.array([1, 2, 3]))\\n\\n        # Array containing NaN \u2014 should be falsy (not all values are non-NA)\\n        assert not component._scalar_notna(np.array([1, float(\\\"nan\\\"), 3]))\\n\\n        # Array of strings \u2014 should be truthy\\n        assert component._scalar_notna(np.array([\\\"a\\\", \\\"b\\\"]))\\n\\n    def test_scalar_notna_with_lists(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test _scalar_notna handles plain lists safely.\\\"\\\"\\\"\\n        component = component_class(**default_kwargs)\\n\\n        assert not component._scalar_notna([])\\n        assert component._scalar_notna([1, 2])\\n\\n    async def test_convert_df_to_data_objects_with_array_cells(self, component_class, default_kwargs):\\n        \\\"\\\"\\\"Test that _convert_df_to_data_objects handles DataFrame rows containing numpy arrays.\\n\\n        This reproduces the bug where Split Text output contains metadata columns with\\n        array values, causing 'truth value of an empty array is ambiguous' errors.\\n        \\\"\\\"\\\"\\n        # Build a DataFrame with an array-valued metadata column (mimics Split Text output)\\n        data_df = DataFrame(\\n            {\\n                \\\"text\\\": [\\\"chunk 1\\\", \\\"chunk 2\\\"],\\n                \\\"source\\\": [\\\"file.txt\\\", \\\"file.txt\\\"],\\n                \\\"tags\\\": [np.array([]), np.array([\\\"important\\\"])],\\n            }\\n        )\\n        default_kwargs[\\\"input_df\\\"] = data_df\\n        default_kwargs[\\\"column_config\\\"] = [\\n            {\\\"column_name\\\": \\\"text\\\", \\\"vectorize\\\": True, \\\"identifier\\\": False},\\n            {\\\"column_name\\\": \\\"source\\\", \\\"vectorize\\\": False, \\\"identifier\\\": True},\\n            {\\\"column_name\\\": \\\"tags\\\", \\\"vectorize\\\": False, \\\"identifier\\\": False},\\n        ]\\n        component = component_class(**default_kwargs)\\n        config_list = default_kwargs[\\\"column_config\\\"]\\n\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.Chroma\\\") as mock_chroma:\\n            mock_chroma_instance = MagicMock()\\n            mock_chroma_instance.get.return_value = {\\\"metadatas\\\": []}\\n            mock_chroma.return_value = mock_chroma_instance\\n\\n            # This should NOT raise \\\"truth value of an empty array is ambiguous\\\"\\n            data_objects = await component._convert_df_to_data_objects(data_df, config_list)\\n\\n        assert len(data_objects) == 2\\n        assert all(isinstance(obj, Data) for obj in data_objects)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/components/files_and_knowledge/test_knowledge.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d380fb9a12ead8dbd621d9dad3988b2ba6c7b8a074f55a3001ead74dd10288d\",\"content\":\"\\\"\\\"\\\"Tests for the merged :class:`KnowledgeComponent`.\\n\\nThe existing ``test_ingestion.py`` and ``test_retrieval.py`` exercise the\\ningest and retrieve code paths end-to-end through the backward-compat\\nsubclass shims (``KnowledgeIngestionComponent`` /\\n``KnowledgeBaseComponent``); if those keep passing, the merged component's\\nbehavior on the run path is verified by reuse.\\n\\nThis file covers the *new* surface area introduced by the merge:\\n\\n* the ``mode`` ``TabInput`` exists and defaults to ``MODE_INGEST``;\\n* ``update_build_config`` toggles ``show`` on the ingest / retrieve input\\n  groups in lockstep with the selected mode;\\n* ``update_outputs`` swaps the single visible output between\\n  ``ingest_result`` (Data) and ``retrieve_result`` (DataFrame);\\n* the legacy subclasses pin themselves to the right mode at init time.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock, patch\\n\\nimport pytest\\nfrom lfx.components.files_and_knowledge.ingestion import KnowledgeIngestionComponent\\nfrom lfx.components.files_and_knowledge.knowledge import (\\n    MODE_INGEST,\\n    MODE_RETRIEVE,\\n    KnowledgeComponent,\\n    _is_retrieve_mode,\\n)\\nfrom lfx.components.files_and_knowledge.retrieval import KnowledgeBaseComponent\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\ndef _build_config_from_inputs(component: KnowledgeComponent) -> dict:\\n    \\\"\\\"\\\"Snapshot the component's declared inputs into a build_config-like dict.\\n\\n    The frontend hands ``update_build_config`` a dict keyed by input name\\n    where each value carries ``show`` / ``value`` / ``options`` / etc. This\\n    helper mirrors that shape from the class-level ``inputs`` declaration so\\n    the tests don't need a real frontend session.\\n    \\\"\\\"\\\"\\n    build_config: dict = {}\\n    for inp in component.inputs:\\n        entry = inp.to_dict() if hasattr(inp, \\\"to_dict\\\") else dict(inp.__dict__)\\n        # ``show`` may be omitted when the input default is True; make it\\n        # explicit so the toggle assertions read cleanly.\\n        entry.setdefault(\\\"show\\\", getattr(inp, \\\"show\\\", True))\\n        entry.setdefault(\\\"value\\\", getattr(inp, \\\"value\\\", None))\\n        build_config[inp.name] = entry\\n    return build_config\\n\\n\\ndef _mode_options(component: KnowledgeComponent) -> list[str]:\\n    mode_input = next((i for i in component.inputs if i.name == \\\"mode\\\"), None)\\n    assert mode_input is not None, \\\"KnowledgeComponent must declare a 'mode' input\\\"\\n    return list(mode_input.options or [])\\n\\n\\n# ---------------------------------------------------------------------------\\n# Structural assertions on the merged component\\n# ---------------------------------------------------------------------------\\nclass TestKnowledgeComponentShape:\\n    def test_mode_input_exists_with_expected_options(self) -> None:\\n        component = KnowledgeComponent()\\n        options = _mode_options(component)\\n        assert options == [MODE_INGEST, MODE_RETRIEVE]\\n\\n    def test_default_mode_is_ingest(self) -> None:\\n        component = KnowledgeComponent()\\n        mode_input = next(i for i in component.inputs if i.name == \\\"mode\\\")\\n        assert mode_input.value == MODE_INGEST\\n\\n    def test_mode_config_partition_covers_only_known_fields(self) -> None:\\n        \\\"\\\"\\\"Each mode lists its fields exactly once; defaults never appear in either bucket.\\n\\n        ``mode_config`` must list every mode-specific field exactly once\\n        and never list any of the ``default_keys`` that are always shown.\\n        \\\"\\\"\\\"\\n        component = KnowledgeComponent()\\n        all_input_names = {i.name for i in component.inputs}\\n        partitioned = set(component.mode_config[MODE_INGEST]) | set(component.mode_config[MODE_RETRIEVE])\\n        # No overlap between the two mode buckets.\\n        assert not set(component.mode_config[MODE_INGEST]) & set(component.mode_config[MODE_RETRIEVE])\\n        # No mode bucket lists a default-key field.\\n        assert not partitioned & set(component.default_keys)\\n        # Every name in the buckets is a real declared input.\\n        assert partitioned <= all_input_names\\n\\n    def test_default_keys_are_always_present(self) -> None:\\n        component = KnowledgeComponent()\\n        all_input_names = {i.name for i in component.inputs}\\n        assert set(component.default_keys) <= all_input_names\\n        assert \\\"mode\\\" in component.default_keys\\n        assert \\\"knowledge_base\\\" in component.default_keys\\n\\n    @pytest.mark.parametrize(\\\"name\\\", [\\\"docs.v2\\\", \\\"a\\\" * 100, \\\"a\\\" * 512, \\\"topology+collection\\\"])\\n    def test_collection_name_validation_accepts_shared_contract(self, name: str) -> None:\\n        assert KnowledgeComponent().is_valid_collection_name(name)\\n\\n    @pytest.mark.parametrize(\\n        \\\"name\\\",\\n        [\\\"Q&A docs\\\", \\\"trailing_\\\", \\\"cat\u00e1logo\\\", \\\"a\\\" * 513, \\\"docs..v2\\\", \\\"127.0.0.1\\\"],\\n    )\\n    def test_collection_name_validation_rejects_chroma_incompatible_names(self, name: str) -> None:\\n        assert not KnowledgeComponent().is_valid_collection_name(name)\\n\\n\\n# ---------------------------------------------------------------------------\\n# update_build_config \u2014 input visibility toggling\\n# ---------------------------------------------------------------------------\\nclass TestModeDrivenInputVisibility:\\n    @pytest.fixture(autouse=True)\\n    def _skip_astra_gate(self):\\n        \\\"\\\"\\\"Stub the astra-cloud gate so update_build_config can proceed in tests.\\n\\n        ``update_build_config`` calls the astra-cloud gate as its first\\n        action \u2014 in tests we just need it to be a no-op.\\n        \\\"\\\"\\\"\\n        with patch(\\\"lfx.components.files_and_knowledge.knowledge.raise_error_if_astra_cloud_disable_component\\\") as gate:\\n            gate.return_value = None\\n            yield\\n\\n    async def test_switching_to_retrieve_hides_ingest_fields(self) -> None:\\n        component = KnowledgeComponent()\\n        build_config = _build_config_from_inputs(component)\\n        build_config[\\\"mode\\\"][\\\"value\\\"] = MODE_INGEST\\n\\n        updated = await component.update_build_config(build_config, MODE_RETRIEVE, \\\"mode\\\")\\n\\n        for fname in component.mode_config[MODE_INGEST]:\\n            assert updated[fname][\\\"show\\\"] is False, f\\\"{fname} should be hidden in retrieve mode\\\"\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            assert updated[fname][\\\"show\\\"] is True, f\\\"{fname} should be visible in retrieve mode\\\"\\n        # Default keys remain visible regardless of mode.\\n        for fname in component.default_keys:\\n            assert updated[fname][\\\"show\\\"] is True\\n\\n    async def test_switching_to_ingest_hides_retrieve_fields(self) -> None:\\n        component = KnowledgeComponent()\\n        build_config = _build_config_from_inputs(component)\\n        # Start the build_config in retrieve mode so we can observe the flip.\\n        build_config[\\\"mode\\\"][\\\"value\\\"] = MODE_RETRIEVE\\n        for fname in component.mode_config[MODE_INGEST]:\\n            build_config[fname][\\\"show\\\"] = False\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            build_config[fname][\\\"show\\\"] = True\\n\\n        updated = await component.update_build_config(build_config, MODE_INGEST, \\\"mode\\\")\\n\\n        for fname in component.mode_config[MODE_INGEST]:\\n            assert updated[fname][\\\"show\\\"] is True, f\\\"{fname} should be visible in ingest mode\\\"\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            assert updated[fname][\\\"show\\\"] is False, f\\\"{fname} should be hidden in ingest mode\\\"\\n\\n    async def test_unknown_mode_falls_back_to_ingest_visibility(self) -> None:\\n        \\\"\\\"\\\"Stale flows may carry an unknown mode value \u2014 fall back gracefully.\\\"\\\"\\\"\\n        component = KnowledgeComponent()\\n        build_config = _build_config_from_inputs(component)\\n        build_config[\\\"mode\\\"][\\\"value\\\"] = \\\"bogus-mode-value\\\"\\n\\n        # field_name=None mirrors an initial node render with no triggering field.\\n        updated = await component.update_build_config(build_config, None, None)\\n\\n        for fname in component.mode_config[MODE_INGEST]:\\n            assert updated[fname][\\\"show\\\"] is True\\n        for fname in component.mode_config[MODE_RETRIEVE]:\\n            assert updated[fname][\\\"show\\\"] is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# Class-level outputs + update_outputs filtering\\n# ---------------------------------------------------------------------------\\nclass TestModeDrivenOutputSwap:\\n    def test_class_level_declares_both_outputs_for_runtime_dispatch(self) -> None:\\n        \\\"\\\"\\\"Both output methods are declared at the class level so the runtime can dispatch correctly.\\n\\n        Without this, the runtime falls back to the only declared output and\\n        crashes when the wrong-mode method runs against missing inputs (e.g.\\n        ``build_kb_info`` calling ``convert_to_dataframe(None)`` in retrieve\\n        mode).\\n        \\\"\\\"\\\"\\n        output_names = {o.name for o in KnowledgeComponent.outputs}\\n        assert output_names == {\\\"dataframe_output\\\", \\\"retrieve_data\\\"}\\n        method_names = {o.method for o in KnowledgeComponent.outputs}\\n        assert method_names == {\\\"build_kb_info\\\", \\\"retrieve_data\\\"}\\n\\n    def test_retrieve_mode_replaces_output_with_retrieve_result(self) -> None:\\n        component = KnowledgeComponent()\\n        frontend_node: dict = {\\\"outputs\\\": list(component.outputs)}\\n\\n        result = component.update_outputs(frontend_node, \\\"mode\\\", MODE_RETRIEVE)\\n\\n        assert len(result[\\\"outputs\\\"]) == 1\\n        out = result[\\\"outputs\\\"][0]\\n        # Legacy output name preserved so saved flow edges keyed on\\n        # ``retrieve_data`` continue to resolve.\\n        assert out.name == \\\"retrieve_data\\\"\\n        assert out.method == \\\"retrieve_data\\\"\\n\\n    def test_ingest_mode_replaces_output_with_ingest_result(self) -> None:\\n        component = KnowledgeComponent()\\n        # Pretend we were previously in retrieve mode.\\n        frontend_node: dict = {\\n            \\\"outputs\\\": [\\n                {\\\"name\\\": \\\"retrieve_data\\\", \\\"method\\\": \\\"retrieve_data\\\", \\\"display_name\\\": \\\"Results\\\"},\\n            ]\\n        }\\n\\n        result = component.update_outputs(frontend_node, \\\"mode\\\", MODE_INGEST)\\n\\n        assert len(result[\\\"outputs\\\"]) == 1\\n        out = result[\\\"outputs\\\"][0]\\n        # Legacy output name preserved so saved flow edges keyed on\\n        # ``dataframe_output`` continue to resolve.\\n        assert out.name == \\\"dataframe_output\\\"\\n        assert out.method == \\\"build_kb_info\\\"\\n\\n    def test_non_mode_field_change_leaves_outputs_untouched(self) -> None:\\n        component = KnowledgeComponent()\\n        original = [{\\\"name\\\": \\\"dataframe_output\\\", \\\"method\\\": \\\"build_kb_info\\\"}]\\n        frontend_node: dict = {\\\"outputs\\\": list(original)}\\n\\n        result = component.update_outputs(frontend_node, \\\"top_k\\\", 10)\\n\\n        assert result[\\\"outputs\\\"] == original\\n\\n\\n# ---------------------------------------------------------------------------\\n# Output-method mode dispatch (stale edges + legacy labels)\\n# ---------------------------------------------------------------------------\\nclass TestOutputMethodModeDispatch:\\n    \\\"\\\"\\\"Output methods dispatch by mode so saved flows survive edge staleness.\\n\\n    If a user wires the ingest output, then switches to retrieve mode, the\\n    saved edge still references ``build_kb_info``. Without dispatch, the\\n    runtime would call the wrong method against the (now-None) ingest\\n    inputs and crash with ``NoneType.to_dataframe``.\\n    \\\"\\\"\\\"\\n\\n    def test_is_retrieve_mode_matches_canonical_and_legacy_labels(self) -> None:\\n        assert _is_retrieve_mode(MODE_RETRIEVE) is True\\n        # Legacy emoji label from the original PR version of this component\\n        # \u2014 saved flows may still carry it.\\n        assert _is_retrieve_mode(\\\"\ud83d\udd0d Retrieve\\\") is True\\n        assert _is_retrieve_mode(MODE_INGEST) is False\\n        assert _is_retrieve_mode(\\\"\ud83d\udce5 Ingest\\\") is False\\n        assert _is_retrieve_mode(None) is False\\n        assert _is_retrieve_mode(42) is False\\n\\n    async def test_build_kb_info_delegates_to_retrieve_when_mode_is_retrieve(self) -> None:\\n        \\\"\\\"\\\"Stale-edge safety net: wiring the ingest output should not crash a retrieve flow.\\\"\\\"\\\"\\n        component = KnowledgeComponent()\\n        component.mode = MODE_RETRIEVE\\n        sentinel = object()\\n        component.retrieve_data = AsyncMock(return_value=sentinel)\\n\\n        result = await component.build_kb_info()\\n\\n        assert result is sentinel\\n        component.retrieve_data.assert_awaited_once()\\n\\n    async def test_retrieve_data_delegates_to_ingest_when_mode_is_ingest(self) -> None:\\n        \\\"\\\"\\\"Symmetric safety net for the inverse stale-edge case.\\\"\\\"\\\"\\n        component = KnowledgeComponent()\\n        component.mode = MODE_INGEST\\n        sentinel = object()\\n        component.build_kb_info = AsyncMock(return_value=sentinel)\\n\\n        result = await component.retrieve_data()\\n\\n        assert result is sentinel\\n        component.build_kb_info.assert_awaited_once()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Subclass shims \u2014 backward-compat\\n# ---------------------------------------------------------------------------\\nclass TestLegacySubclassesPinMode:\\n    def test_ingestion_subclass_pins_ingest_mode(self) -> None:\\n        component = KnowledgeIngestionComponent()\\n        assert component.mode == MODE_INGEST\\n        assert component.name == \\\"KnowledgeIngestion\\\"\\n        assert component.display_name == \\\"Knowledge Ingestion\\\"\\n\\n    def test_retrieval_subclass_pins_retrieve_mode(self) -> None:\\n        component = KnowledgeBaseComponent()\\n        assert component.mode == MODE_RETRIEVE\\n        assert component.name == \\\"KnowledgeBase\\\"\\n        assert component.display_name == \\\"Knowledge Base\\\"\\n\\n    def test_subclasses_inherit_merged_inputs(self) -> None:\\n        \\\"\\\"\\\"Saved legacy flows must keep loading against either subclass.\\n\\n        Both subclasses must declare the full superset of inputs so that\\n        saved legacy flows (which reference field names like ``input_df`` /\\n        ``top_k``) continue to load against either class.\\n        \\\"\\\"\\\"\\n        ingest_input_names = {i.name for i in KnowledgeIngestionComponent.inputs}\\n        retrieve_input_names = {i.name for i in KnowledgeBaseComponent.inputs}\\n        for name in (\\\"input_df\\\", \\\"top_k\\\", \\\"knowledge_base\\\", \\\"mode\\\"):\\n            assert name in ingest_input_names, f\\\"KnowledgeIngestionComponent missing input: {name}\\\"\\n            assert name in retrieve_input_names, f\\\"KnowledgeBaseComponent missing input: {name}\\\"\\n\\n    def test_retrieval_module_reexports_filter_helpers(self) -> None:\\n        \\\"\\\"\\\"Back-compat re-export keeps legacy test imports working.\\n\\n        ``test_retrieval.py`` imports these helpers from the retrieval\\n        module \u2014 the back-compat re-export must keep that working.\\n        \\\"\\\"\\\"\\n        from lfx.components.files_and_knowledge.retrieval import (\\n            _chunk_matches_filter,\\n            _parse_metadata_filter,\\n        )\\n\\n        assert _parse_metadata_filter(None) == {}\\n        assert _chunk_matches_filter(None, {}) is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# Knowledge Base path isolation\\n#\\n# Path resolution now runs through the shared ``resolve_local_store_path``\\n# helper, which is also the only place a local path is ever built \u2014 for local\\n# Chroma and nothing else.\\n# ---------------------------------------------------------------------------\\nclass TestKnowledgeBasePathIsolation:\\n    @staticmethod\\n    def _resolve(kb_root, username, kb_name, *, backend_type=\\\"chroma\\\", backend_config=None):\\n        from langflow.api.utils.kb_helpers import resolve_local_store_path\\n\\n        with patch(\\n            \\\"langflow.api.utils.kb_helpers.KBStorageHelper.get_root_path\\\",\\n            return_value=kb_root,\\n        ):\\n            return resolve_local_store_path(\\n                kb_name,\\n                username,\\n                backend_type=backend_type,\\n                backend_config=backend_config,\\n            )\\n\\n    @pytest.mark.parametrize(\\\"knowledge_base\\\", [\\\"../../outside\\\", \\\"../victim/secret_kb\\\"])\\n    def test_rejects_kb_names_outside_the_current_user_directory(self, knowledge_base, tmp_path) -> None:\\n        with pytest.raises(ValueError, match=\\\"KB path escapes root directory\\\"):\\n            self._resolve(tmp_path, \\\"attacker\\\", knowledge_base)\\n\\n    def test_rejects_username_that_escapes_the_global_kb_root(self, tmp_path) -> None:\\n        with pytest.raises(ValueError, match=\\\"KB path escapes root directory\\\"):\\n            self._resolve(tmp_path, \\\"../outside\\\", \\\"safe_kb\\\")\\n\\n    def test_rejects_symlink_escape_from_current_user_directory(self, tmp_path) -> None:\\n        user_root = tmp_path / \\\"attacker\\\"\\n        outside_root = tmp_path.parent / \\\"outside\\\"\\n        user_root.mkdir()\\n        outside_root.mkdir(exist_ok=True)\\n        (user_root / \\\"linked\\\").symlink_to(outside_root, target_is_directory=True)\\n\\n        with pytest.raises(ValueError, match=\\\"KB path escapes root directory\\\"):\\n            self._resolve(tmp_path, \\\"attacker\\\", \\\"linked/secret_kb\\\")\\n\\n    def test_preserves_kb_names_inside_the_current_user_directory(self, tmp_path) -> None:\\n        assert self._resolve(tmp_path, \\\"current_user\\\", \\\"existing_kb\\\") == (tmp_path / \\\"current_user\\\" / \\\"existing_kb\\\")\\n\\n    @pytest.mark.parametrize(\\n        (\\\"backend_type\\\", \\\"backend_config\\\"),\\n        [(\\\"opensearch\\\", {}), (\\\"postgres\\\", {}), (\\\"chroma\\\", {\\\"mode\\\": \\\"cloud\\\"})],\\n    )\\n    def test_remote_backends_resolve_no_path_at_all(self, tmp_path, backend_type, backend_config) -> None:\\n        \\\"\\\"\\\"Only local Chroma gets a directory; everything else stays off-disk.\\n\\n        Notably a traversing name is harmless for these \u2014 there is no path to\\n        traverse, because none is built.\\n        \\\"\\\"\\\"\\n        assert (\\n            self._resolve(\\n                tmp_path,\\n                \\\"attacker\\\",\\n                \\\"../victim/secret_kb\\\",\\n                backend_type=backend_type,\\n                backend_config=backend_config,\\n            )\\n            is None\\n        )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Backend resolution: the ``knowledge_base`` row is the sole authority, and an\\n# unresolvable backend must raise rather than silently degrade to local storage.\\n#\\n# Ingestion used to read ``embedding_metadata.json`` while retrieval read the\\n# database row. Across replicas those disagree \u2014 a pod without the sidecar wrote\\n# a remote-backed KB into a local Chroma dir while queries followed the row to\\n# the configured cluster and returned nothing, with no error raised anywhere.\\n# The sidecar is gone entirely now; both paths resolve from the row.\\n# ---------------------------------------------------------------------------\\nclass TestBackendResolution:\\n    KB_NAME = \\\"support_docs\\\"\\n    USER_ID = \\\"3f1c9c1e-6d2a-4a53-8a4e-9c0b1d2e3f40\\\"\\n\\n    @staticmethod\\n    def _record(backend_type: str, backend_config: dict | None = None) -> SimpleNamespace:\\n        return SimpleNamespace(backend_type=backend_type, backend_config=backend_config or {})\\n\\n    def _component(self) -> KnowledgeComponent:\\n        # ``user_id`` is a read-only property backed by ``_user_id``; the public\\n        # name is ignored by the constructor (it lands as the string \\\"None\\\").\\n        return KnowledgeComponent(knowledge_base=self.KB_NAME, _user_id=self.USER_ID)\\n\\n    @staticmethod\\n    def _write_sidecar(kb_path, backend_type: str, backend_config: dict | None = None) -> None:\\n        kb_path.mkdir(parents=True, exist_ok=True)\\n        (kb_path / \\\"embedding_metadata.json\\\").write_text(\\n            json.dumps({\\\"backend_type\\\": backend_type, \\\"backend_config\\\": backend_config or {}})\\n        )\\n\\n    async def test_resolves_from_the_database_row(self) -> None:\\n        component = self._component()\\n\\n        with patch(\\n            \\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\",\\n            new=AsyncMock(return_value=self._record(\\\"opensearch\\\", {\\\"index_name\\\": \\\"kb_support\\\"})),\\n        ):\\n            backend_type, backend_config = await component._resolve_backend_config()\\n\\n        assert backend_type == \\\"opensearch\\\"\\n        assert backend_config == {\\\"index_name\\\": \\\"kb_support\\\"}\\n\\n    async def test_a_stale_sidecar_cannot_override_the_row(self, tmp_path) -> None:\\n        \\\"\\\"\\\"A sidecar left on one pod is inert \u2014 nothing reads it any more.\\\"\\\"\\\"\\n        self._write_sidecar(tmp_path, \\\"chroma\\\")\\n        component = self._component()\\n\\n        with patch(\\n            \\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\",\\n            new=AsyncMock(return_value=self._record(\\\"opensearch\\\", {\\\"index_name\\\": \\\"kb_support\\\"})),\\n        ):\\n            backend_type, _ = await component._resolve_backend_config()\\n\\n        assert backend_type == \\\"opensearch\\\"\\n\\n    async def test_raises_without_a_row_even_when_a_sidecar_exists(self, tmp_path) -> None:\\n        \\\"\\\"\\\"No row is unknown, not local \u2014 refuse to guess, sidecar or not.\\n\\n        A legacy directory is adopted explicitly via\\n        ``langflow reconcile-kb-from-disk``, never by an implicit read here.\\n        \\\"\\\"\\\"\\n        self._write_sidecar(tmp_path, \\\"opensearch\\\", {\\\"index_name\\\": \\\"legacy\\\"})\\n        component = self._component()\\n\\n        with (\\n            patch(\\n                \\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\",\\n                new=AsyncMock(return_value=None),\\n            ),\\n            pytest.raises(ValueError, match=\\\"Refusing to fall back to local storage\\\"),\\n        ):\\n            await component._resolve_backend_config()\\n\\n    async def test_database_lookup_failure_propagates(self, tmp_path) -> None:\\n        \\\"\\\"\\\"A DB error must not be swallowed into a local-storage default.\\\"\\\"\\\"\\n        self._write_sidecar(tmp_path, \\\"chroma\\\")\\n        component = self._component()\\n\\n        with (\\n            patch(\\n                \\\"langflow.api.utils.knowledge_base_service.get_by_user_and_name\\\",\\n                new=AsyncMock(side_effect=RuntimeError(\\\"connection lost\\\")),\\n            ),\\n            pytest.raises(RuntimeError, match=\\\"connection lost\\\"),\\n        ):\\n            await component._resolve_backend_config()\\n\\n\\nclass TestKnowledgeProviderPolicyPreflight:\\n    \\\"\\\"\\\"Embedding policy is resolved from raw dialog values or stored KB metadata.\\\"\\\"\\\"\\n\\n    USER_ID = \\\"3f1c9c1e-6d2a-4a53-8a4e-9c0b1d2e3f40\\\"\\n\\n    async def test_create_dialog_selection_is_denied_before_dynamic_hook_work(self, monkeypatch) -> None:\\n      ";
